CET.data.listeningByYear[2023] = [{"id":"L5","level":"CET4","type":"新闻","source":"2023年6月 · 四级 · 新闻","year":2023,"session":"6月","title":"共享单车新规","intro":"新闻报道某城市出台共享单车停放新规，以及市民的不同反应。","audio":"assets/audio/2023/cet4-2023-06-set1.mp3","lines":[{"sp":"Q1","en":"A woman was charged with allegedly violating a Rhode Island city law against feeding wild animals.","cn":"一名女子被指控涉嫌违反罗德岛州某市禁止喂食野生动物的法律。"},{"sp":"Q1","en":"The 55-year-old woman's neighbors blame her for making the area's rat problem worse.","cn":"这名55岁女子的邻居指责她加剧了该地区的老鼠问题。"},{"sp":"Q1","en":"Newly installed cameras captured several rats active in the middle of the day.","cn":"新安装的摄像头拍摄到数只老鼠在白天活动。"},{"sp":"Q1","en":"Neighbors say that it's even worse during the night.","cn":"邻居们表示夜间情况更加严重。"},{"sp":"Q1","en":"The woman and her parents, who own the home, told reporters that she's being charged for feeding birds.","cn":"这名女子及其拥有该房产的父母告诉记者,她被指控的原因是喂鸟。"},{"sp":"Q1","en":"\"Who would have known just loving animals gets you that much trouble,\" she said.","cn":"她说:\"谁能想到仅仅是喜爱动物就会惹来这么大的麻烦。\""},{"sp":"Q1","en":"It is prohibited to feed any wild animals including birds in Rhode Island City.","cn":"在罗德岛市,禁止喂食包括鸟类在内的任何野生动物。"},{"sp":"Q1","en":"Nevertheless, while the woman's intention was to feed birds, it is clear that rats were also benefiting.","cn":"然而,尽管该女子的本意是喂鸟,但显然老鼠也从中受益。"},{"sp":"Q1","en":"Anthony Moretti, director of the city administration, said he saw more than 20 rats near the woman's home.","cn":"市政管理部门主任Anthony Moretti表示,他在该女子家附近看到了20多只老鼠。"},{"sp":"Q1","en":"He said it will take months to get the problem under control.","cn":"他说控制这个问题需要数月时间。"},{"sp":"Q3","en":"To prepare for eventually sending astronauts to Mars, NASA began taking applications Friday for four people to live for a year in Mars Dune Alpha.","cn":"为了准备最终将宇航员送往火星,NASA于周五开始接受四人申请,让他们在Mars Dune Alpha中生活一年。"},{"sp":"Q3","en":"That's a 1,700-square-foot Martian habitat inside a building in Houston.","cn":"这是位于休斯顿一座建筑内的一个1700平方英尺的火星栖息地。"},{"sp":"Q3","en":"The paid volunteers will work in an environment similar to Mars.","cn":"这些有偿志愿者将在类似火星的环境中工作。"},{"sp":"Q3","en":"They will have limited communications with family, restricted food and resources.","cn":"他们与家人的通讯将受到限制,食物和资源也会受限。"},{"sp":"Q3","en":"NASA is planning three experiments with the first one starting in the fall next year.","cn":"NASA正在计划三次实验,第一次实验将于明年秋季开始。"},{"sp":"Q3","en":"Food will all be ready-to-eat space food.","cn":"食物将全部是即食太空食品。"},{"sp":"Q3","en":"Some plants will be grown, but not potatoes like in the movie The Martian.","cn":"会种植一些植物,但不会像电影《火星救援》中那样种植土豆。"},{"sp":"Q3","en":"\"We want to understand how humans perform in them,\" said lead scientist Grace Douglas.","cn":"首席科学家Grace Douglas说:\"我们想了解人类在这些环境中的表现。"},{"sp":"Q3","en":"\"We are looking at Mars-realistic situations.\"","cn":"我们关注的是符合火星实际情况的场景。\""},{"sp":"Q3","en":"The application process opens Friday and they're not seeking just anybody.","cn":"申请流程于周五开放,他们寻找的并非普通人选。"},{"sp":"Q3","en":"The requirements are strict, including a master's degree in a science, engineering or math field or pilot experience.","cn":"要求非常严格,包括拥有科学、工程或数学领域的硕士学位或飞行员经验。"},{"sp":"Q3","en":"Only American citizens or permanent U.S. residents are acceptable.","cn":"只接受美国公民或美国永久居民。"},{"sp":"Q3","en":"Applicants must be between 30 and 55 and in good physical health.","cn":"申请人必须年龄在30至55岁之间,身体健康状况良好。"},{"sp":"Q3","en":"Attitude is key, said former Canadian astronaut Chris Hadfield.","cn":"加拿大前宇航员Chris Hadfield表示,态度是关键。"},{"sp":"Q3","en":"He said the participants need to be super competent, resourceful, and not relying on other people to feel comfortable.","cn":"他说参与者需要非常能干、足智多谋,不依赖他人也能感到自在。"},{"sp":"Q5","en":"A Japanese mayor apologized Thursday for biting the Olympic gold medal of a softball player.","cn":"日本一位市长周四为咬了一名垒球运动员的奥运金牌道歉。"},{"sp":"Q5","en":"Nagoya mayor Takashi Kawamura had praised an athlete, Miu Goto, during a public media event.","cn":"名古屋市长河村隆之在一次公开媒体活动中表扬了运动员后藤希友。"},{"sp":"Q5","en":"He asked her to put the medal around his neck.","cn":"他请她把奖牌挂在他的脖子上。"},{"sp":"Q5","en":"Kawamura then bit into it.","cn":"随后河村咬了那枚奖牌。"},{"sp":"Q5","en":"Biting a medal in front of journalists and photographers has become a common pose for Olympic medalists.","cn":"在记者和摄影师面前咬奖牌已成为奥运奖牌获得者的常见姿势。"},{"sp":"Q5","en":"However, it is only for the winners themselves, not others.","cn":"然而,这只适用于获奖者本人,而非其他人。"},{"sp":"Q5","en":"\"I'm really sorry that I hurt the treasure of the gold medalist,\" Kawamura told reporters Thursday.","cn":"河村周四告诉记者:\"我真的很抱歉伤害了金牌得主的珍宝。\""},{"sp":"Q5","en":"The mayor said the medal was undamaged, though he offered to pay for the cost of a new one.","cn":"市长表示奖牌没有损坏,不过他提出愿意支付一枚新奖牌的费用。"},{"sp":"Q5","en":"Goto, however, has accepted the International Olympic Committee's offer of a replacement, according to Japanese media reports.","cn":"然而,据日本媒体报道,后藤已接受国际奥委会提供的替换奖牌。"},{"sp":"Q5","en":"The scene broadcast on television prompted thousands of complaints to city hall.","cn":"电视上播出的这一幕引发了数千人向市政厅投诉。"},{"sp":"Q5","en":"Some Olympians said they treat their medals as treasures and that it was disrespectful and unacceptable for Kawamura to bite one.","cn":"一些奥运选手表示,他们把奖牌视为珍宝,河村咬奖牌是不尊重的、不可接受的行为。"},{"sp":"Q5","en":"\"I would cry if that happened to me,\" said another athlete, Naohisa Takato.","cn":"另一位运动员高藤直寿说:\"如果这发生在我身上,我会哭的。"},{"sp":"Q5","en":"\"I handle my own gold medal so gently that I would not scratch it.\"","cn":"我对待自己的金牌非常温柔,不会让它划伤。\""},{"sp":"Q8","en":"M: What's that orange thing on your computer screen?","cn":"M: 你电脑屏幕上那个橙色的东西是什么？"},{"sp":"Q8","en":"W: It's something I bought yesterday.","cn":"W: 这是我昨天买的。"},{"sp":"Q8","en":"It's a plastic sheet that blocks blue light.","cn":"是一张能阻挡蓝光的塑料贴膜。"},{"sp":"Q8","en":"I have one that I use to cover my phone screen too.","cn":"我还有一张用来贴手机屏幕的。"},{"sp":"Q8","en":"M: What do you mean by blue light?","cn":"M: 你说的蓝光是什么意思？"},{"sp":"Q8","en":"W: Blue light includes natural light, but it also includes light that isn't natural, for example, from computers, phones, televisions and other electronic devices.","cn":"W: 蓝光包括自然光，但也包括非自然光，比如来自电脑、手机、电视和其他电子设备的光。"},{"sp":"Q8","en":"M: So blue light is harmful and that's why you want to block it.","cn":"M: 所以蓝光是有害的，这就是你想阻挡它的原因。"},{"sp":"Q8","en":"W: It isn't that simple.","cn":"W: 没那么简单。"},{"sp":"Q8","en":"Blue light isn't necessarily bad for us.","cn":"蓝光不一定对我们有害。"},{"sp":"Q8","en":"In fact, we need blue light during the day to be healthy.","cn":"事实上，我们白天需要蓝光来保持健康。"},{"sp":"Q8","en":"But too much blue light, especially from electronic devices, can harm our health by weakening our vision and making it harder for us to fall asleep.","cn":"但过多的蓝光，尤其是来自电子设备的蓝光，会削弱我们的视力，让我们更难入睡，从而损害我们的健康。"},{"sp":"Q8","en":"And poor sleep can cause all sorts of health problems.","cn":"而睡眠不好会导致各种健康问题。"},{"sp":"Q8","en":"M: I'm not so sure that sleep is nearly as important as people always say it is.","cn":"M: 我不太确定睡眠真的像人们常说的那么重要。"},{"sp":"Q8","en":"I haven't slept enough in months because I have too much work to do, and I feel fine.","cn":"我好几个月都没睡够了，因为工作太多，但我感觉挺好的。"},{"sp":"Q8","en":"And it's the same for most of my friends.","cn":"我大多数朋友也是这样。"},{"sp":"Q8","en":"Poor sleep might be a problem for older people, but surely young people can handle late nights.","cn":"睡眠不好可能对老年人是个问题，但年轻人肯定能应付熬夜吧。"},{"sp":"Q8","en":"W: Well, the research I've read shows that sleep is probably even more important than we thought, and that not having enough sleep can contribute to serious health problems like obesity and heart disease.","cn":"W: 嗯，我读到的研究表明，睡眠可能比我们想象的还要重要，睡眠不足会导致肥胖和心脏病等严重的健康问题。"},{"sp":"Q8","en":"And all the artificial blue light from electronic devices means we have to try harder to sleep well.","cn":"而且电子设备发出的所有人造蓝光意味着我们必须更努力才能睡好。"},{"sp":"Q8","en":"M: Maybe you're right.","cn":"M: 也许你说得对。"},{"sp":"Q8","en":"I'm on my computer very late most nights, and that's probably why I don't sleep enough.","cn":"我大多数晚上都很晚还在用电脑，这可能就是我睡眠不足的原因。"},{"sp":"Q12","en":"W: As a kid, did you know what job you wanted to do when you grew up?","cn":"W: 你小时候知道自己长大后想做什么工作吗？"},{"sp":"Q12","en":"M: No, I didn't.","cn":"M: 不知道。"},{"sp":"Q12","en":"And I got sick every time adults asked me what I wanted to be when I grew up.","cn":"每次大人问我长大后想做什么，我都觉得烦。"},{"sp":"Q12","en":"W: It's the same with me.","cn":"W: 我也是。"},{"sp":"Q12","en":"And I'm tired of people asking that question of my 10-year-old daughter.","cn":"我也受够了别人老问我10岁女儿这个问题。"},{"sp":"Q12","en":"My daughter's stock answers are basketball player, pop singer, mechanical engineer.","cn":"我女儿的标准答案是篮球运动员、流行歌手、机械工程师。"},{"sp":"Q12","en":"Adults love that last one, as it's the perfect mix of the sensible and the ambitious.","cn":"大人们特别喜欢最后那个，因为它既实际又有抱负，是完美的结合。"},{"sp":"Q12","en":"When she was much younger, my daughter used to say she wanted to be Queen of the Clouds, which I loved.","cn":"我女儿小时候曾说她想当云朵女王，我特别喜欢这个。"},{"sp":"Q12","en":"That's the kind of goal-setting I like to see in children, springing from their boundless imaginations.","cn":"这才是我希望在孩子身上看到的那种目标设定，源于他们无边无际的想象力。"},{"sp":"Q12","en":"M: Yes, we grown-ups can be tedious and limiting in our need for reality.","cn":"M: 是啊，我们成年人为了现实可能会变得乏味和局限。"},{"sp":"Q12","en":"And we teach a very gloomy image of adulthood—that whatever our children's future holds, it must be seen within the context of a job.","cn":"而且我们给孩子灌输了一种非常灰暗的成年生活形象——无论我们孩子的未来是什么样的，都必须放在工作这个框架里看。"},{"sp":"Q12","en":"W: How utterly overwhelming and dull!","cn":"W: 这太让人喘不过气来了，而且多无聊啊！"},{"sp":"Q12","en":"M: When people ask my son what he wants to be when he grows up, I have to swallow the urge to say, \"Hey, back off my kid's dreams!\"","cn":"M: 每当有人问我儿子长大后想做什么时，我都得忍住不说：嘿，别对我孩子的梦想指手画脚！"},{"sp":"Q12","en":"W: We can't dismiss the idea that teenagers have to plan to do something after they finish school, and parents are entitled to hope it's more than simply spending 10 hours a day playing computer games.","cn":"W: 我们不能否认青少年确实需要为毕业后做点什么而规划，家长也有权希望那不仅仅是每天花10个小时玩电脑游戏。"},{"sp":"Q12","en":"M: But asking \"What do you want to be?\" isn't going to lead a child to a fulfilled life, rather at least to false expectations and a high chance of disappointment.","cn":"M: 但问\"你想做什么\"并不会引导孩子走向充实的人生，反而至少会带来错误的期望和很大的失望可能。"},{"sp":"Q12","en":"W: Exactly.","cn":"W: 没错。"},{"sp":"Q12","en":"We should be helping our kids understand who they are, even if that means letting go of who we think they should be.","cn":"我们应该帮助孩子了解他们自己是谁，即使这意味着放下我们认为他们应该成为什么样的人。"},{"sp":"Q16","en":"Greater Internet access correlates directly with improved health care, education and economic development.","cn":"互联网接入的扩大与医疗保健、教育和经济发展的改善直接相关。"},{"sp":"Q16","en":"People living in rural areas, however, lag behind in online use, which limits their access to government services, banking and job opportunities.","cn":"然而,生活在农村地区的人们在网络使用方面落后,这限制了他们获得政府服务、银行业务和就业机会的途径。"},{"sp":"Q16","en":"Nowhere is this challenge clearer than in Africa.","cn":"这一挑战在非洲表现得最为明显。"},{"sp":"Q16","en":"Most Africans live in rural areas that are tough to wire for Internet access.","cn":"大多数非洲人生活在难以铺设互联网接入线路的农村地区。"},{"sp":"Q16","en":"Now, some phone companies are trying to introduce Internet-ready phones into African markets.","cn":"现在,一些手机公司正试图将支持互联网的手机引入非洲市场。"},{"sp":"Q16","en":"Certain companies have started selling simple smartphones for only $20.","cn":"某些公司已经开始销售售价仅为20美元的简易智能手机。"},{"sp":"Q16","en":"Previously, the lowest price had been around $40, well out of reach for many people.","cn":"此前,最低价格约为40美元,这对许多人来说遥不可及。"},{"sp":"Q16","en":"These devices are powered by software from the giant electronics company, KaiOS Technologies Limited.","cn":"这些设备由大型电子公司KaiOS Technologies Limited的软件驱动。"},{"sp":"Q16","en":"Most companies are trying to make phones ever more powerful and capable.","cn":"大多数公司都在努力让手机变得更强大、功能更多。"},{"sp":"Q16","en":"But KaiOS went the other way.","cn":"但KaiOS反其道而行之。"},{"sp":"Q16","en":"It made every effort to keep the essential capabilities of smartphones, but strip out costs and preserve battery life for people who likely have inadequate access to electricity.","cn":"它竭尽全力保留智能手机的基本功能,同时降低成本并延长电池续航时间,以满足那些可能无法充分获得电力供应的人们的需求。"},{"sp":"Q16","en":"The KaiOS devices offer an alternative to the more expensive models that remain out of reach of many Africans and contribute to the digital divide.","cn":"KaiOS设备为许多非洲人提供了一种替代选择,那些价格更高的机型仍然遥不可及,并加剧了数字鸿沟。"},{"sp":"Q16","en":"The body of KaiOS phones is as basic as it gets.","cn":"KaiOS手机的机身设计极其简单。"},{"sp":"Q16","en":"Instead of a touchscreen, they're controlled with an old-school keypad.","cn":"它们不使用触摸屏,而是通过老式键盘进行操控。"},{"sp":"Q16","en":"They're designed for 3G networks because 4G coverage doesn't reach two thirds of Africa's customers.","cn":"它们是为3G网络设计的,因为4G覆盖范围无法触及非洲三分之二的用户。"},{"sp":"Q16","en":"In total, KaiOS phones are made from about $15 worth of parts, while Apple's top-of-the-line iPhone has $390 worth of stuff.","cn":"总的来说,KaiOS手机由价值约15美元的零部件制成,而苹果公司的顶级iPhone则使用了价值390美元的材料。"},{"sp":"Q19","en":"For years, using recycled plastic to make plastic products was cheap.","cn":"多年来，使用再生塑料制造塑料产品的成本较低。"},{"sp":"Q19","en":"By contrast, fossil fuel plastic was more expensive.","cn":"相比之下，化石燃料塑料则更加昂贵。"},{"sp":"Q19","en":"Thus this sustainable option was an economic option too.","cn":"因此，这种可持续选择也是一种经济选择。"},{"sp":"Q19","en":"But now it is cheaper for major manufacturers to use new plastic.","cn":"但现在对于大型制造商来说，使用新塑料更便宜。"},{"sp":"Q19","en":"According to one recent business report, recycled plastic now costs an extra $72 a tonne compared with newly-made plastic.","cn":"根据最近的一份商业报告，与新制塑料相比，再生塑料现在每吨要多花费72美元。"},{"sp":"Q19","en":"This may be because of consumer demands.","cn":"这可能是因为消费者的需求。他们推动在新产品中使用更多再生塑料。"},{"sp":"Q19","en":"They are pushing for more recycled plastics in new products.","cn":"与此同时，新塑料正变得更便宜。"},{"sp":"Q19","en":"Meanwhile, new plastic is becoming cheaper.","cn":"这是因为美国石油化工生产的繁荣。"},{"sp":"Q19","en":"This is because of a boom in petroleum chemical production from the U.S. The price increase of recycled plastic could cost sustainable manufacturers an extra $250 million a year.","cn":"再生塑料价格的上涨可能会使可持续制造商每年多支出2.5亿美元。"},{"sp":"Q19","en":"Smaller manufacturers may also be forced to use new plastic to reduce costs.","cn":"较小的制造商也可能被迫使用新塑料以降低成本。"},{"sp":"Q19","en":"Makers of clear plastic bottles may also opt for new fossil-fuel based plastic to save money.","cn":"透明塑料瓶的制造商也可能选择使用新的化石燃料基塑料来省钱。"},{"sp":"Q19","en":"Plastic packaging makers are being pressured to use more recycled plastic.","cn":"塑料包装制造商正面临使用更多再生塑料的压力。"},{"sp":"Q19","en":"This is done in hopes of reducing the enormous amount of plastic pollution in the oceans.","cn":"这样做是为了减少海洋中大量的塑料污染。"},{"sp":"Q19","en":"The UK government plans to tax companies which don't use at least 30% recycled plastic in their products.","cn":"英国政府计划对产品中再生塑料使用量未达到至少30%的公司征税。"},{"sp":"Q19","en":"Additionally, the government is planning to increase the quantity of recycled plastic in the market.","cn":"此外，政府正计划增加市场上再生塑料的数量。"},{"sp":"Q19","en":"This could mean incentives for new recycling plants.","cn":"这可能意味着对新回收工厂的激励措施。"},{"sp":"Q19","en":"Additionally, recycling facilities may be improved at a local council level and recycled plastic could be imported.","cn":"此外，地方议会层面的回收设施可能会得到改善，再生塑料也可以进口。"},{"sp":"Q19","en":"This would help increase the amount of recycled plastic in circulation.","cn":"这将有助于增加流通中再生塑料的数量。"},{"sp":"Q22","en":"At the Dreamery, a business in Manhattan, naps are for sale.","cn":"在曼哈顿的 Dreamery，小睡是用来出售的。"},{"sp":"Q22","en":"A 45-minute session in a darkened enclosure with peace and quiet costs $25.","cn":"在一个幽暗的封闭空间里享受平静与安宁的 45 分钟小睡需要 25 美元。"},{"sp":"Q22","en":"To be clear, this institution is no hotel.","cn":"需要明确的是，这家机构不是酒店。"},{"sp":"Q22","en":"This is a nap joint.","cn":"这是一家小睡店。"},{"sp":"Q22","en":"It sells the idea of the nap as much as the nap itself.","cn":"它出售的是小睡这个理念，就像出售小睡本身一样。"},{"sp":"Q22","en":"Is a nap worth $25?","cn":"一次小睡值 25 美元吗？"},{"sp":"Q22","en":"The answer is obviously yes.","cn":"答案显然是肯定的。"},{"sp":"Q22","en":"Here, at this point in the argument, it's traditional for me to bring up all the studies that show the benefits of napping.","cn":"在论证的这一点上，按惯例我应该列举所有显示小睡益处的研究。"},{"sp":"Q22","en":"But do you really need experts to tell you that?","cn":"但你真的需要专家告诉你这些吗？"},{"sp":"Q22","en":"Just look at the world around you at 2:30 in the afternoon.","cn":"只需看看下午两点半你周围的世界。"},{"sp":"Q22","en":"I've been working from home for more than 10 years now.","cn":"我在家工作已经超过 10 年了。"},{"sp":"Q22","en":"And the quality and quantity of work I can do emerges directly from my ability to concentrate.","cn":"我能完成的工作质量和数量直接来源于我的专注能力。"},{"sp":"Q22","en":"I don't understand how people have creative careers without napping.","cn":"我不明白人们如何能在不小睡的情况下从事创意职业。"},{"sp":"Q22","en":"Every day at about 1 p.m., everyone faces the same choice: sleep until 2 p.m. and then work until 5, or daydream and drift around social media and attend pointless meetings until 7 p.m.","cn":"每天大约下午一点，每个人都面临同样的选择：睡到下午两点然后工作到五点，或者做白日梦、在社交媒体上闲逛、参加毫无意义的会议直到晚上七点。"},{"sp":"Q22","en":"The friends I have who still work in offices inform me their bosses insist that they take the second option, and that napping is associated with laziness.","cn":"我那些仍在办公室工作的朋友告诉我，他们的老板坚持让他们选择第二种方案，而且小睡被认为与懒惰联系在一起。"},{"sp":"Q22","en":"I genuinely find it odd.","cn":"我真的觉得这很奇怪。"},{"sp":"Q22","en":"For if you nap properly, it's like waking up from a full night's sleep and you can double your day's worth of concentration.","cn":"因为如果你好好小睡，那就像从一整夜的睡眠中醒来，你可以让一天的专注力翻倍。"}],"questions":[{"q":"What must riders do starting next month?","options":["Pay a monthly fee","Park bikes in marked areas","Register their bicycles","Wear a helmet"],"answer":1,"explain":"新闻开头说 shared bicycles must be parked in marked areas starting next month。"},{"q":"What happens after a first warning?","options":["The bike is taken away","A fine of fifty yuan","A one month ban","Nothing at all"],"answer":1,"explain":"原文说 receive a warning for the first time and a fine of fifty yuan after that，再犯罚款五十元。"},{"q":"What will the government do by the end of the year?","options":["Add one thousand parking zones","Remove all shared bikes","Build new bike lanes","Raise the price of riding"],"answer":0,"explain":"新闻最后一句说 it will add one thousand parking zones before the end of the year。"}],"cloze":[{"text":"Riders who leave a bike outside these areas will receive a ______ for the first time.","answers":["warning"],"hint":"警告"},{"text":"Companies will be required to remove ______ ones within forty eight hours.","answers":["broken"],"hint":"损坏的"},{"text":"The government says it will add one thousand parking ______ before the end of the year.","answers":["zones"],"hint":"区域"}]},{"id":"L10","level":"CET6","type":"讲座","source":"2023年6月 · 六级 · 讲座","year":2023,"session":"6月","title":"人工智能会取代哪些岗位","intro":"讲座讨论人工智能对岗位任务的影响，并以历史经验给出启示。","audio":"assets/audio/2023/cet6-2023-06-set1.mp3","lines":[{"sp":"Q1","en":"M: Hi, Lily, how's the new apartment?","cn":"M: 嗨，莉莉，新公寓怎么样？"},{"sp":"Q1","en":"W: It's okay.","cn":"W: 还行吧。"},{"sp":"Q1","en":"M: What?","cn":"M: 什么？"},{"sp":"Q1","en":"How can it be just okay when last week you were thrilled about the place and kept posting photos of it online?","cn":"上周你还对这个地方兴奋不已，还不停地把照片发到网上，怎么现在只能说还行？"},{"sp":"Q1","en":"W: Well, last week when I moved in, the apartment seemed cozy, just the right size for one person.","cn":"W: 嗯，我上周搬进去的时候，觉得公寓很温馨，对一个人来说大小正合适。"},{"sp":"Q1","en":"But now it just seems tiny, shabby and solitary.","cn":"但现在我只觉得它又小又破旧，还很孤单。"},{"sp":"Q1","en":"M: Ah, that's the problem.","cn":"M: 啊，问题就在这儿。"},{"sp":"Q1","en":"You miss your roommates from university, don't you?","cn":"你想念大学时的室友了，对吧？"},{"sp":"Q1","en":"W: I'm going to sound like an idiot, because I used to complain to you all the time about how crowded our dormitory room was, and about all the things they did to irritate me, like watching movies late at night without headphones, or talking loudly early in the morning.","cn":"W: 我这么说听起来可能像个傻瓜，因为我以前总是向你抱怨我们的宿舍有多拥挤，还抱怨他们做的那些让我恼火的事，比如深夜不戴耳机看电影，或者一大早大声说话。"},{"sp":"Q1","en":"But now I miss them terribly.","cn":"可现在我特别想念他们。"},{"sp":"Q1","en":"M: Of course you do.","cn":"M: 你当然会想念他们，这完全正常。我刚有自己的住处时，记得自己当时想的是，真等不及要独自生活，摆脱那些幼稚的室友和他们烦人的习惯。"},{"sp":"Q1","en":"That's perfectly normal.","cn":"可是后来我开始想念他们，感到孤独，还觉得我们的宿舍简直像天堂，尽管我们六个大男人挤在一个小房间里。"},{"sp":"Q1","en":"When I got my first place I remember thinking I couldn't wait to live by myself and get away from my juvenile roommates and all their annoying habits.","cn":""},{"sp":"Q1","en":"But then I began missing them and feeling lonely and thinking that our dormitory was like paradise, even though there were six of us guys in one small room.","cn":""},{"sp":"Q1","en":"W: I thought it was just me who felt like that.","cn":"W: 我还以为只有我会有这种感觉。"},{"sp":"Q1","en":"M: Look, you lived at home with us, and then you had three roommates, and this is your first time living alone.","cn":"M: 你以前和我们住在家里，后来又和三个室友一起住，而这是你第一次独居，所以确实很难适应。"},{"sp":"Q1","en":"So it's hard.","cn":"不过，你的第一套公寓是人生中的一个里程碑，你应该庆祝一下。"},{"sp":"Q1","en":"But your first apartment is a milestone in your life, and you should celebrate it.","cn":"跟我说说这套公寓吧。"},{"sp":"Q1","en":"Tell me about the apartment.","cn":""},{"sp":"Q1","en":"W: Actually, it's not bad.","cn":"W: 其实，它还不错。"},{"sp":"Q1","en":"In fact, it's pretty adorable, now that I have decorated it and it has everything I need.","cn":"事实上，我把它装饰好，也置办齐了所有需要的东西之后，发现它还挺可爱的。"},{"sp":"Q1","en":"I have a kitchen to cook in and a bathroom all to myself, and then another room with my bed at one end, and a sofa, a small table and chairs at the other end.","cn":"我有一间可以做饭的厨房和一间完全属于自己的浴室，另外还有一个房间，一头放着我的床，另一头放着沙发、小桌子和椅子。"},{"sp":"Q1","en":"M: That does sound adorable and I can't wait to see it, and neither can mom and dad.","cn":"M: 听起来确实很可爱，我都等不及想去看看了，爸爸妈妈也一样。"},{"sp":"Q5","en":"W: Welcome to our program Book Talk.","cn":"W: 欢迎收听我们的节目《图书访谈》。"},{"sp":"Q5","en":"Our guest today is Frank Jones, a critic of our education system, and the author of a new book, How to Reform Our Universities.","cn":"今天的嘉宾是弗兰克·琼斯，他是我们教育体系的批评者，也是新书《如何改革我们的大学》的作者。"},{"sp":"Q5","en":"M: Hello, Susan.","cn":"M: 你好，苏珊。"},{"sp":"Q5","en":"W: Frank, you support radically changing universities in America?","cn":"W: 弗兰克，你支持彻底改变美国的大学吗？"},{"sp":"Q5","en":"M: Yes, I believe that the purpose of higher education is to prepare young people to enter the workforce, and that our current system fails to do this.","cn":"M: 是的，我认为高等教育的目的是让年轻人为进入职场做好准备，而我们目前的体系没有做到这一点。"},{"sp":"Q5","en":"We're allocating too many resources to disciplines that don't match the needs of employers.","cn":"我们把太多资源分配给了与雇主需求不匹配的学科。"},{"sp":"Q5","en":"W: I think your attitude to education is a bit cynical, Frank.","cn":"W: 弗兰克，我觉得你对教育的态度有点愤世嫉俗。"},{"sp":"Q5","en":"Surely the purpose of university is to prepare young people to participate fully in civic life, rather than just to find well-paid jobs.","cn":"大学的目的当然应该是让年轻人充分参与公民生活，而不只是找到高薪工作。"},{"sp":"Q5","en":"M: Susan, many young graduates struggle to find any job, let alone a good one.","cn":"M: 苏珊，许多年轻的毕业生连工作都很难找到，更不用说一份好工作了。"},{"sp":"Q5","en":"The job market is grim, particularly for students who study the arts.","cn":"就业市场很不景气，尤其是对学习艺术的学生而言。"},{"sp":"Q5","en":"W: I agree that it isn't easy for young people to find work, but you propose closing down all departments that aren't directly related to science and technology.","cn":"W: 我同意年轻人找工作并不容易，但你提议关闭所有与科学和技术没有直接关系的院系。"},{"sp":"Q5","en":"Is that really the solution?","cn":"这真的是解决办法吗？"},{"sp":"Q5","en":"M: You're overstating my point.","cn":"M: 你夸大了我的观点。"},{"sp":"Q5","en":"My argument is that we need to use more of our budget on areas like science and engineering.","cn":"我的意思是，我们需要把更多预算用于科学和工程等领域。"},{"sp":"Q5","en":"To do that, we need to take money from subjects like literature and music.","cn":"要做到这一点，我们就得从文学、音乐等学科中抽走资金。"},{"sp":"Q5","en":"W: But the arts have value.","cn":"W: 但艺术是有价值的。"},{"sp":"Q5","en":"They're an important part of our culture.","cn":"它们是我们文化的重要组成部分。"},{"sp":"Q5","en":"Studying literature or music or sculpture might not result in a job in that area, but it helps young people to think about the world in a deeper way, which makes them better citizens and makes for a better society.","cn":"学习文学、音乐或雕塑也许不会让人最终从事相关领域的工作，但这能帮助年轻人更深入地思考世界，使他们成为更好的公民，也让社会变得更好。"},{"sp":"Q5","en":"M: I agree that the arts are valuable to society, but it's naive to think that not only the most talented, but all students should study them at university level.","cn":"M: 我同意艺术对社会有价值，但认为不仅最有天赋的学生，所有学生都应该在大学阶段学习艺术，这种想法很天真。"},{"sp":"Q5","en":"The arts are very competitive, and most graduates will end up with a great deal of debt, obtaining a degree that has little value on the job market.","cn":"艺术领域竞争非常激烈，大多数毕业生最终会背负巨额债务，拿到一个在就业市场上价值不大的学位。"},{"sp":"Q9","en":"Do you ever have the annoying feeling that you don't have time to really think anymore?","cn":"你是否常有一种恼人的感觉，觉得自己再也没有时间真正思考了？"},{"sp":"Q9","en":"You are not alone.","cn":"你并不孤单。"},{"sp":"Q9","en":"A variety of factors have conspired to rob us of time for reflection about ourselves and our lives.","cn":"各种因素共同作用，夺走了我们用于反思自己和生活的时间。"},{"sp":"Q9","en":"Today, our preoccupied minds are rarely silent.","cn":"如今，我们被各种事务占据的头脑很少有安静的时候。"},{"sp":"Q9","en":"The average person receives hundreds of texts and voice messages a day, and holidays for many of us are action-packed weeks more likely full of family activities than opportunities for tranquility and contemplation.","cn":"普通人每天会收到数百条短信和语音消息，而对我们许多人来说，假期也是安排得满满当当的一周，更多的是充满家庭活动，而不是拥有宁静与沉思的机会。"},{"sp":"Q9","en":"Regular reflection, however, underlies all great professionals.","cn":"然而，定期反思是一切杰出专业人士的基础。"},{"sp":"Q9","en":"It's a prerequisite for you to recharge your mental batteries, see things in a new light and tap into your creativity.","cn":"这是你重新充实心理能量、以新的眼光看待事物并发挥创造力的先决条件。"},{"sp":"Q9","en":"Almost all of the great advisors that I have studied have found ways to get away from it all and contemplate their life and work.","cn":"我研究过的几乎所有杰出顾问，都找到了远离一切、思考自己生活和工作的方式。"},{"sp":"Q9","en":"Some researchers in the field of creativity, in fact, believe that insight occurs during the reflection and relaxation that follows a period of intense activity.","cn":"事实上，一些创造力领域的研究人员认为，洞见产生于高强度活动之后的反思与放松期间。"},{"sp":"Q9","en":"Schedule time for reflection about your work or a particular project you're engaged in.","cn":"安排时间反思你的工作或正在参与的某个项目。"},{"sp":"Q9","en":"I usually block out half an hour.","cn":"我通常会留出半小时。"},{"sp":"Q9","en":"Don't answer the phone.","cn":"不要接电话。"},{"sp":"Q9","en":"Push your papers to the side.","cn":"把文件推到一边。"},{"sp":"Q9","en":"Sketch, make lists, draw \"mind maps\" of ideas that come to you.","cn":"画草图、列清单、把浮现出的想法绘制成“思维导图”。"},{"sp":"Q9","en":"At the end, write down any emerging ideas.","cn":"最后，把任何新出现的想法记下来。"},{"sp":"Q9","en":"When you're alone, stop worrying and think.","cn":"独处时，停止担忧，认真思考。"},{"sp":"Q9","en":"A lot of our down time is spent worrying about troublesome things in our lives or fantasizing about how we'd like our lives to be.","cn":"我们许多空闲时间都花在担心生活中令人烦恼的事情上，或幻想自己的生活应该是什么样子。"},{"sp":"Q9","en":"Revisit things during moments of relaxation after a period of intense work.","cn":"在一段高强度工作之后的放松时刻，重新思考这些事情。"},{"sp":"Q9","en":"This is when we are the most creative.","cn":"此时正是我们最具创造力的时候。"},{"sp":"Q12","en":"Even before Colorado was a state, it had post offices.","cn":"甚至在科罗拉多成为一个州之前，这里就已经有了邮局。"},{"sp":"Q12","en":"The first opened in 1859, in a settlement founded by migrants searching for gold.","cn":"第一家邮局于1859年在一个由寻找黄金的移民建立的定居点开业。"},{"sp":"Q12","en":"Life could be unpredictable out west—gold failed to appear, drought ruined farmers and settlers clashed with Native Americans.","cn":"西部的生活充满不可预测性——黄金未能出现，干旱摧残了农民，移居者与美洲原住民发生冲突。"},{"sp":"Q12","en":"On the settlement's location now stands a sprawling university campus.","cn":"在该定居点如今的位置上，耸立着一座庞大的大学校园。"},{"sp":"Q12","en":"Amid all the changes, one feature remained constant—the postal service.","cn":"在所有的变迁中，有一个特征始终保持不变——那就是邮政服务。"},{"sp":"Q12","en":"The maps tracing America's westward expansion are telling.","cn":"追溯美国西进运动的地图非常具有说服力。"},{"sp":"Q12","en":"In 1864, there were few postal branches on land controlled by Native Americans, which still accounted for most of the West.","cn":"1864年，在美洲原住民控制的土地上几乎没有邮政分局，而这些土地当时仍占据了西部的大部分。"},{"sp":"Q12","en":"Over the next 25 years, post offices grew quickly.","cn":"在接下来的25年里，邮局迅速增多。"},{"sp":"Q12","en":"Colonization of the West could be regarded as a result of big government rather than pioneers.","cn":"对西部的拓殖可以被视为大政府而非拓荒者的产物。"},{"sp":"Q12","en":"As federal subsidies and land grants tempted people into the deserts and plains, the post kept them connected.","cn":"随着联邦补贴和土地赠予吸引人们深入沙漠和平原，邮政保持了他们之间的联系。"},{"sp":"Q12","en":"In the mid-19th century, the Post Office Department was far from a centralized bureaucracy.","cn":"在19世纪中叶，邮政部远非一个集权的官僚机构。"},{"sp":"Q12","en":"To keep up with migration patterns, postal services were added to existing businesses.","cn":"为了跟上移民模式的脚步，邮政服务被附加到了现有的商业经营中。"},{"sp":"Q12","en":"The federal government commissioned private wagons to carry the mail.","cn":"联邦政府委托私人马车运送邮件。"},{"sp":"Q12","en":"Short-term contracts were granted to local businessmen to act as postmasters.","cn":"当地商人获得了担任邮局局长的短期合同。"},{"sp":"Q12","en":"These partnerships enabled the mail to quickly follow migrants, helping knit together remote parts of the country.","cn":"这些合作关系使邮件能够迅速跟随移民，有助于将该国偏远地区紧密联系在一起。"},{"sp":"Q12","en":"Mr. Blevins, a digital historian, wrote a book on the history of the US postal service.","cn":"数字历史学家布莱文斯先生写了一本关于美国邮政服务历史的书。"},{"sp":"Q12","en":"He used data science to analyze historical trends.","cn":"他利用数据科学分析了历史趋势。"},{"sp":"Q12","en":"Most strikingly, he built an accompanying website, complete with interactive maps.","cn":"最引人注目的是，他建立了一个配套网站，里面配备了完整的互动地图。"},{"sp":"Q12","en":"They show readers how, within a generation, the postal service helped colonize a continent.","cn":"它们向读者展示了在短短一代人的时间内，邮政服务是如何协助拓殖整块大陆的。"},{"sp":"Q12","en":"These online interactive maps illustrate the formative power of snail mail.","cn":"这些在线互动地图展示了传统邮政的塑造力量。"},{"sp":"Q16","en":"In last week's lecture, we discussed reasons why people forget things.","cn":"在上周的讲座中，我们讨论了人们遗忘事物的原因。"},{"sp":"Q16","en":"This week, we will discuss a surprising reason why we might remember some things—anxiety.","cn":"本周，我们将讨论一个令人惊讶的、可能使我们记住某些事物的原因——焦虑。"},{"sp":"Q16","en":"Think about something as simple as buying a coffee.","cn":"想一想像买咖啡这样简单的事情。"},{"sp":"Q16","en":"That may not seem like an experience that would make a deep impression on your memory, but anxiety could change that.","cn":"这似乎不太像是一种会在记忆中留下深刻印象的经历，但焦虑可能会改变这一点。"},{"sp":"Q16","en":"In fact, a new study suggests that people with higher anxiety levels might remember certain information better than people with lower anxiety levels.","cn":"事实上，一项新的研究表明，焦虑程度较高的人可能比焦虑程度较低的人更能记住某些信息。"},{"sp":"Q16","en":"That's because higher levels of anxiety may make people more susceptible to negative feelings, putting them in a more negative state of mind.","cn":"这是因为较高程度的焦虑可能使人更容易受到负面情绪的影响，使他们处于更加消极的心理状态。"},{"sp":"Q16","en":"That in turn may make them able to better remember some events.","cn":"这反过来可能使他们能够更好地记住某些事件。"},{"sp":"Q16","en":"Let's take a closer look at that new study now.","cn":"现在让我们更仔细地了解一下这项新研究。"},{"sp":"Q16","en":"In the study, the researchers started by giving 80 undergraduate students an anxiety test.","cn":"在这项研究中，研究人员首先让80名本科生接受焦虑测试。"},{"sp":"Q16","en":"The test measured the participants' anxiety levels over the preceding two weeks.","cn":"该测试测量了参与者在此前两周内的焦虑程度。"},{"sp":"Q16","en":"Then, to test memory, the participants were shown a series of neutral words, one at a time.","cn":"随后，为了测试记忆力，研究人员让参与者逐一观看一系列中性词语。"},{"sp":"Q16","en":"Some of the words were printed on to photos of negative scenes, meaning images that could affect their emotions negatively, such as a photo of a car accident or a cemetery.","cn":"其中一些词语印在负面场景的照片上，也就是可能对他们的情绪产生负面影响的图像上，例如车祸或墓地的照片。"},{"sp":"Q16","en":"The rest of the words were printed on to photos of neutral scenes, such as a photo of a lake or trees.","cn":"其余词语则印在中性场景的照片上，例如湖泊或树木的照片。"},{"sp":"Q16","en":"Neutral words included words like \"table\" or \"desk\" that don't elicit emotion.","cn":"中性词语包括“桌子”或“书桌”之类不会引发情绪的词语。"},{"sp":"Q16","en":"Later, the participants were asked to think back to the words they were shown earlier, which caused them to reenter either a negative or a neutral mindset.","cn":"之后，研究人员要求参与者回想刚才看到的词语，这使他们重新进入消极或中性的心理状态。"},{"sp":"Q16","en":"The participants were then presented with another set of neutral words, and their memory of these new words was tested.","cn":"然后，研究人员向参与者展示另一组中性词语，并测试他们对这些新词语的记忆。"},{"sp":"Q16","en":"The researchers found that the new words presented to people in a negative mindset were better remembered by people with higher levels of anxiety than those with lower levels of anxiety.","cn":"研究人员发现，对于处于消极心理状态的人，新呈现的词语中，焦虑程度较高的人比焦虑程度较低的人记得更好。"},{"sp":"Q16","en":"In other words, when highly anxious individuals took in otherwise emotionally neutral information that was presented to them, it became colored by their negative mindset, making them remember the information better.","cn":"换句话说，高度焦虑的人接收到原本在情感上中性的信息时，这些信息会受到其消极心理状态的影响，从而使他们更好地记住这些信息。"},{"sp":"Q16","en":"But these same effects were not seen in people with low levels of anxiety.","cn":"但在焦虑程度较低的人身上并未观察到同样的效果。"},{"sp":"Q16","en":"Previous studies have found that extreme levels of anxiety, such as those experienced by people diagnosed with an anxiety disorder, can be quite detrimental to memory and cognitive performance.","cn":"先前的研究发现，极高程度的焦虑，例如被诊断患有焦虑障碍的人所经历的焦虑，可能会严重损害记忆力和认知表现。"},{"sp":"Q16","en":"But the highly anxious people in this study represent individuals who are managing their anxiety and for whom anxiety is not a serious problem.","cn":"但这项研究中的高度焦虑者代表的是那些能够管理自己的焦虑、且焦虑并非严重问题的人。"},{"sp":"Q19","en":"Over the past 20 years, the internet has gradually become a dominant feature of our lives.","cn":"在过去20年里，互联网逐渐成为我们生活中的主导因素。"},{"sp":"Q19","en":"It has changed how we communicate with each other, and it has definitely transformed the way we do business with each other.","cn":"它改变了我们彼此沟通的方式，也确实改变了我们彼此开展业务的方式。"},{"sp":"Q19","en":"Marketing has also changed in a number of ways.","cn":"营销也在许多方面发生了变化。"},{"sp":"Q19","en":"For instance, in the past, consumers had to call a phone number and patiently wait on hold, in order to get the information they wanted.","cn":"例如，过去，消费者必须拨打一个电话号码，并耐心等待接通，才能获得他们想要的信息。"},{"sp":"Q19","en":"Today, they want the information immediately.","cn":"如今，他们希望立即获得信息。"},{"sp":"Q19","en":"They'll go to the company's social media page and post comments and questions, expecting to receive an immediate response.","cn":"他们会前往公司的社交媒体页面，发布评论和问题，并期待立即得到回应。"},{"sp":"Q19","en":"If they don't get their questions answered soon, they'll move on to another company that will answer them quickly.","cn":"如果他们的问题很快得不到解答，就会转而选择另一家能够迅速回答他们问题的公司。"},{"sp":"Q19","en":"Marketing departments today need to follow technological development.","cn":"如今，营销部门需要跟上技术的发展。例如，今年的智能手机比去年的更智能；"},{"sp":"Q19","en":"For example, this year's smartphone is smarter than last year's; self-driving cars are now on the road.","cn":"自动驾驶汽车如今已经上路。"},{"sp":"Q19","en":"Marketers have to do research on which technologies are coming into being.","cn":"营销人员必须研究哪些技术正在出现，否则就有被抛在虚拟尘埃中的风险。"},{"sp":"Q19","en":"Otherwise, they risk being left behind in the virtual dust.","cn":"营销也因视频的重要性而发生了变化。"},{"sp":"Q19","en":"Marketing has also changed due to the importance of video.","cn":"人们不只是想阅读文字；"},{"sp":"Q19","en":"People don't just want to read text; they want to watch things happening.","cn":"他们还想观看事情发生的过程。"},{"sp":"Q19","en":"Companies now have to explore how they can use video on a consistent basis to share information about their businesses.","cn":"如今，公司必须探索如何持续利用视频来分享有关自身业务的信息。"},{"sp":"Q19","en":"Fortunately, it's extremely easy to shoot something these days.","cn":"幸运的是，现在拍摄视频非常容易。"},{"sp":"Q19","en":"All you need is a smartphone.","cn":"你只需要一部智能手机。"},{"sp":"Q19","en":"But what's the result of all this?","cn":"但这一切带来了什么结果呢？"},{"sp":"Q19","en":"Shorter attention spans.","cn":"注意力持续时间变短了。"},{"sp":"Q19","en":"We aren't the same people that we were 20 years ago.","cn":"我们已经不是20年前的那群人了。"},{"sp":"Q19","en":"Not only have we grown accustomed to getting the information we want instantaneously, our attention spans are much shorter.","cn":"我们不仅已经习惯于即时获得想要的信息，注意力持续时间也短得多了。"},{"sp":"Q19","en":"If something doesn't capture our attention within a few seconds, we're on to the next piece of content.","cn":"如果某件事在几秒钟内无法吸引我们的注意力，我们就会转向下一条内容。"},{"sp":"Q19","en":"Marketers need to figure out ways to speak directly to the customers' emotions, and they need to figure out how to do that as quickly as possible.","cn":"营销人员需要想办法直接与客户的情感沟通，也需要想办法尽快做到这一点。"},{"sp":"Q19","en":"Once people are emotionally engaged, they'll stick with you.","cn":"一旦人们在情感上投入其中，他们就会一直关注你。"},{"sp":"Q19","en":"If marketing has changed this much in the past 20 years, imagine what the next 20 years will bring.","cn":"如果营销在过去20年里发生了如此大的变化，想象一下未来20年会带来什么。"},{"sp":"Q19","en":"In a recent survey, only 9% of marketers could say with confidence that their marketing efforts were actually working.","cn":"在最近的一项调查中，只有9%的营销人员能够自信地说，他们的营销工作确实奏效了。"},{"sp":"Q19","en":"Their confidence is being shaken, because the rules of the game change every year.","cn":"他们的信心正在受到动摇，因为游戏规则每年都在变化。"},{"sp":"Q19","en":"That's why it's important for marketers to pay attention to the latest technological developments and consider collaborating with technological innovators.","cn":"这就是营销人员关注最新技术发展并考虑与技术创新者合作十分重要的原因。"},{"sp":"Q19","en":"That way, they'll be moving at the same pace as the tech industry.","cn":"这样一来，他们就能与科技行业保持同样的步调。"},{"sp":"Q22","en":"You might be surprised to learn that the benefits of friendships extend beyond people's social life and into their work, which is interesting when considering the extent to which people sacrifice friendships, or at least the time they spend with friends, because of the extended hours they're devoting to work.","cn":"你可能会惊讶地得知，友谊带来的益处不仅限于人们的社交生活，还延伸到了工作领域。想到人们常常因为投入工作、延长工作时间，而牺牲友谊，或者至少牺牲与朋友相处的时间，这一点就很有意思。"},{"sp":"Q22","en":"Just last week, I was remarking to a colleague that I'm content with only one social engagement per week.","cn":"就在上周，我还对一位同事说，我每周只参加一次社交活动就满足了。"},{"sp":"Q22","en":"But according to recent research, that's evidently not enough.","cn":"但根据最近的研究，显然这还不够。"},{"sp":"Q22","en":"In an initial study of more than 700 respondents, scholars from an American university analyzed the impact that friends, as opposed to family, have on self-esteem and well-being.","cn":"在一项对700多名受访者进行的初步研究中，一所美国大学的学者分析了朋友相较于家人对自尊和幸福感的影响。"},{"sp":"Q22","en":"Friends came out substantially on top.","cn":"结果显示，朋友的影响明显更大。"},{"sp":"Q22","en":"That's because to be someone's mate is a voluntary act, unlike family who people rarely get to choose.","cn":"这是因为，成为某人的朋友是一种自愿行为，而家人通常并不是人们可以选择的。"},{"sp":"Q22","en":"The researchers found that when people choose to cultivate and maintain supportive friendships with an individual, it means that the person is valued and worthy of their limited time.","cn":"研究人员发现，当人们选择与某个人培养并维持相互支持的友谊时，这意味着那个人受到重视，值得人们投入有限的时间。"},{"sp":"Q22","en":"Such sentiments of value and worthiness boost our self-esteem.","cn":"这种受到重视和认可的感受会提升我们的自尊。"},{"sp":"Q22","en":"The second study comprised more than 300 participants.","cn":"第二项研究由300多名参与者组成。研究证明，我们对自己的感觉越好，就越有可能自信而出色地完成工作。"},{"sp":"Q22","en":"It proved that the better we feel about ourselves, the more likely we'll perform our job confidently and competently.","cn":"这项后续研究发现，工作之外的朋友甚至还能提高人们的工作满意度。"},{"sp":"Q22","en":"This follow-up study found that non-work friends even improve people's job satisfaction.","cn":"尽管这些朋友并不在我们的工作场所，但他们对我们有多喜欢自己的工作所产生的影响，与工作中的朋友一样大。"},{"sp":"Q22","en":"They have as much of an impact on how much they love their jobs as do the friends they have at work, despite not actually being at our place of work.","cn":"这类朋友往往是我们倾诉工作相关事情的首选对象，而在办公室里未必有这样的倾诉渠道。"},{"sp":"Q22","en":"These types of friends tend to be our preferred outlet for venting about work-related matters.","cn":""},{"sp":"Q22","en":"This is an avenue that may not be available at the office.","cn":""},{"sp":"Q22","en":"So even though friendships can be easy to neglect when confronted by pressures at work, or even pressures at home, neglecting our friends can turn out to be harmful and counterproductive.","cn":"因此，尽管在工作压力甚至家庭压力面前，友谊很容易被忽视，但忽视朋友最终可能会带来伤害，并产生适得其反的效果。"},{"sp":"Q22","en":"That's why, when determining how to create a better work-life balance, we need to consider not only how to balance work and family demands, but also how to cultivate and sustain supportive friendships.","cn":"这就是为什么，在确定如何实现更好的工作与生活平衡时，我们不仅需要考虑如何平衡工作和家庭的要求，还需要考虑如何培养并维持相互支持的友谊。"},{"sp":"Q22","en":"It's for this reason that managers should never discriminate when it comes to requests from employees for flexible work arrangements.","cn":"正因如此，管理者在员工提出弹性工作安排请求时，绝不应区别对待。"},{"sp":"Q22","en":"It's irrelevant whether their need for a desired schedule is due to, say, parenting responsibilities, or a craving to hang out with a best mate.","cn":"无论他们希望采用某种工作时间安排是因为需要承担育儿责任，还是因为想与最要好的朋友出去相聚，这都无关紧要。"},{"sp":"Q22","en":"What matters is the opportunity to engage in a nourishing activity outside of work.","cn":"重要的是，他们有机会参与工作之外有益身心的活动。"},{"sp":"Q22","en":"That will definitely have a follow-on effect at work.","cn":"这肯定会对工作产生后续影响。"}],"questions":[{"q":"What does the speaker say AI will take?","options":["Whole jobs immediately","Some tasks rather than whole jobs","Only jobs in banks","No jobs at all"],"answer":1,"explain":"原文说 it will take some tasks, not whole jobs, at least in the near future。"},{"q":"What example from history does he give?","options":["Banks installing cash machines","Factories using robots in 1900","Farmers leaving the land","Schools closing their doors"],"answer":0,"explain":"原文举例 When banks installed cash machines, the number of bank clerks did not fall。"},{"q":"Who faces the highest risk according to the lecture?","options":["People with narrow routine skills","People who combine technical knowledge with communication","Managers who negotiate contracts","Workers who keep learning"],"answer":0,"explain":"原文说 the risk is highest for narrow skills，技能单一者风险最高。"}],"cloze":[{"text":"Machines are very good at tasks that ______, such as checking invoices.","answers":["repeat"],"hint":"重复"},{"text":"They are still poor at tasks that need ______, negotiation, or care for another person.","answers":["judgment"],"hint":"判断力"},{"text":"We should ask which tasks we can hand over, and what new tasks that ______ us to do.","answers":["frees"],"hint":"使……腾出、解放"}]},{"id":"cet4-2023-03-1","level":"CET4","exam":"2023_03_1","year":2023,"month":3,"set":1,"type":"整卷听力","title":"2023年3月 四级第1套 · 听力真题","source":"2023年3月 CET-4 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet4-2023-03-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"African leaders plan to turn the continent into a continent without borders. They will introduce a single passport policy, allowing free movement between countries. The idea from the African Union has been modeled on the EU Schengen free movement deal. Europe has abolished many internal borders. This enables visa-free movement across the continent. Currently, 13 African countries have visa-free deals in place with each other. These allow citizens to visit another country without a visa. Some countries offer visas on arrival. In contrast, Americans are able to travel to 20 of the continent's countries without a visa, or secure a visa on arrival. The African Union, which represents 54 states, wants to abolish the requirement of a visa for Africans visiting other African countries. It also wants to establish a free trade deal across the continent in the near future, as trade within the African continent costs more than any other region.","cn":"非洲领导人计划将该大陆变成一个无边界的大陆。他们将推行单一护照政策,允许各国之间自由流动。这一来自非洲联盟的想法是以欧盟申根自由流动协议为蓝本的。欧洲已经取消了许多内部边界,这使得整个大陆可以免签证自由流动。目前,13个非洲国家之间已经建立了免签证协议。这些协议允许公民无需签证即可访问另一个国家。一些国家提供落地签证。相比之下,美国人能够在无需签证或获得落地签证的情况下前往该大陆的20个国家。代表54个国家的非洲联盟希望取消非洲人访问其他非洲国家的签证要求。它还希望在不久的将来在整个大陆建立自由贸易协定,因为非洲大陆内部的贸易成本高于任何其他地区。"},{"sp":"短篇新闻 2","en":"Researchers in Iceland found a new way of tackling climate change by pumping carbon dioxide underground and turning it into stone.","cn":"冰岛的研究人员发现了一种应对气候变化的新方法，即将二氧化碳泵入地下并将其转化为石头。"},{"sp":"短篇新闻 2","en":"Other carbon capture and storage methods store carbon dioxide as a gas.","cn":"其他碳捕获和储存方法以气体形式储存二氧化碳。"},{"sp":"短篇新闻 2","en":"But problems include a high cost and concern about leaks.","cn":"但问题包括成本高昂以及对泄漏的担忧。"},{"sp":"短篇新闻 2","en":"This new method of burying carbon dioxide and turning it into stone is cheaper and more secure, the Guardian reports.","cn":"据《卫报》报道，这种埋藏二氧化碳并将其转化为石头的新方法更便宜、更安全。"},{"sp":"短篇新闻 2","en":"To turn carbon dioxide into stone, researchers with the CarbFix project pumped the gas into volcanic rock and sped up the natural process, in which the volcanic rock reacts with gas and forms carbon minerals.","cn":"为了将二氧化碳转化为石头，CarbFix项目的研究人员将气体泵入火山岩中，并加速了火山岩与气体反应形成碳矿物的自然过程。"},{"sp":"短篇新闻 2","en":"The gas turned into solid in just two years, much faster than the hundreds or thousands of years researchers had predicted.","cn":"气体仅在两年内就转化为固体,远快于研究人员预测的数百年或数千年。"},{"sp":"短篇新闻 2","en":"The research took place at Iceland's Hellisheidi power plant.","cn":"该研究在冰岛的Hellisheidi发电厂进行。"},{"sp":"短篇新闻 2","en":"Already, the project in Iceland has been increased in scale to bury 10,000 tons of carbon dioxide each year.","cn":"冰岛的该项目规模已经扩大,每年可埋藏10,000吨二氧化碳。"},{"sp":"短篇新闻 2","en":"One potential difficulty is that for each ton of carbon dioxide buried, the technique requires 25 tons of water.","cn":"一个潜在的困难是,每埋藏一吨二氧化碳,该技术需要25吨水。"},{"sp":"短篇新闻 2","en":"However, the lead researcher said sea water could be used.","cn":"然而,首席研究员表示可以使用海水。"},{"sp":"短篇新闻 3","en":"People in France are keeping away from the narrow French stick loaf in favour of healthier, cheaper options, a millers' association has said.","cn":"法国一家磨坊协会表示,法国人正在远离细长的法式棍子面包,转而选择更健康、更便宜的食品。"},{"sp":"短篇新闻 3","en":"The National Association of French Millers says bread consumption is on the decline, with French people eating nine grams less than in the previous year.","cn":"法国全国磨坊协会称,面包消费量正在下降,法国人的食用量比前一年减少了9克。"},{"sp":"短篇新闻 3","en":"The association is concerned about the effects this trend will have on their trade and suggests three reasons why it is happening.","cn":"该协会对这一趋势将对其行业产生的影响表示担忧,并提出了造成这种情况的三个原因。"},{"sp":"短篇新闻 3","en":"Firstly, the association cited changing diets, in particular, the switch to those low in calories, as a factor in the reduction of bread consumption.","cn":"首先,该协会指出饮食习惯的改变,特别是转向低热量饮食,是面包消费量减少的一个因素。"},{"sp":"短篇新闻 3","en":"This could explain why the difference in consumption between genders is so big.","cn":"这可以解释为什么性别之间的消费差异如此之大。"},{"sp":"短篇新闻 3","en":"Nowadays, men eat an approximate average of 140 grams of bread daily, whereas women eat 80 to 90 grams.","cn":"如今,男性平均每天吃大约140克面包,而女性吃80到90克。"},{"sp":"短篇新闻 3","en":"The second reason they say is lifestyle changes in the country, with people dedicating less time to breakfast when bread would traditionally be eaten with butter and jam.","cn":"他们所说的第二个原因是该国生活方式的变化,人们用于早餐的时间减少了,而早餐传统上会搭配黄油和果酱吃面包。"},{"sp":"短篇新闻 3","en":"Finally, the rising cost of bread is considered to be a factor, with the price of a French stick loaf increasing by nearly 25% in the last 10 years.","cn":"最后,面包价格上涨被认为是一个因素,法式棍子面包的价格在过去10年中上涨了近25%。"},{"sp":"长对话 1","en":"W: Next, please.","cn":"W: 下一位，请。"},{"sp":"长对话 1","en":"M: Yes, I'd like to book two train tickets to London tomorrow morning, please.","cn":"M: 好的，我想订两张明天早上去伦敦的火车票。"},{"sp":"长对话 1","en":"W: Okay.","cn":"W: 好的。"},{"sp":"长对话 1","en":"What time would you like to go?","cn":"您想什么时候出发？"},{"sp":"长对话 1","en":"M: Well, after the rush hour, I think.","cn":"M: 嗯，我想在高峰期之后吧。"},{"sp":"长对话 1","en":"We'd like to avoid the crowds if possible.","cn":"如果可能的话，我们想避开人群。"},{"sp":"长对话 1","en":"So, probably sometime around 10 o'clock.","cn":"所以，大概10点左右吧。"},{"sp":"长对话 1","en":"W: No problem.","cn":"W: 没问题。"},{"sp":"长对话 1","en":"Just give me a minute.","cn":"稍等一下。"},{"sp":"长对话 1","en":"There's one here at 9:47, then one at 10:12, and then a third at 10:26.","cn":"这里有一班9点47分的，然后10点12分有一班，还有第三班10点26分的。"},{"sp":"长对话 1","en":"M: The one at 10:12 sounds good.","cn":"M: 10点12分那班听起来不错。"},{"sp":"长对话 1","en":"W: All right.","cn":"W: 好的。"},{"sp":"长对话 1","en":"Would you like to sit in first or second class?","cn":"您想坐头等舱还是二等舱？"},{"sp":"长对话 1","en":"M: Second class is fine.","cn":"M: 二等舱就可以。"},{"sp":"长对话 1","en":"Thanks.","cn":"谢谢。"},{"sp":"长对话 1","en":"Is there any chance we could have a window seat for one of those?","cn":"有没有可能给我们其中一个安排靠窗的座位？"},{"sp":"长对话 1","en":"W: No problem.","cn":"W: 没问题。"},{"sp":"长对话 1","en":"And I've booked those seats next to each other for you.","cn":"我已经给您订了相邻的座位。"},{"sp":"长对话 1","en":"The total price is 36 pounds, 50 cents.","cn":"总价是36英镑50便士。"},{"sp":"长对话 1","en":"Is there anything else?","cn":"还有其他需要吗？"},{"sp":"长对话 1","en":"M: Yes, actually, we'll be taking our bicycles with us.","cn":"M: 有的，实际上我们会带着自行车一起去。"},{"sp":"长对话 1","en":"What is the arrangement for that?","cn":"这方面怎么安排？"},{"sp":"长对话 1","en":"And will it cost extra?","cn":"需要额外收费吗？"},{"sp":"长对话 1","en":"W: It's no extra cost.","cn":"W: 不需要额外费用。"},{"sp":"长对话 1","en":"The price will be the same.","cn":"价格是一样的。"},{"sp":"长对话 1","en":"All you need to do is wait at the far end of the platform.","cn":"您只需要在站台最远端等候。"},{"sp":"长对话 1","en":"When the train arrives, tell the train guard where you're going, and he will help you secure the bicycles in the last carriage and give you a ticket.","cn":"火车到达时，告诉列车员您要去哪里，他会帮您把自行车固定在最后一节车厢并给您一张票。"},{"sp":"长对话 1","en":"Then you can walk down through the train to your carriage and take your seats.","cn":"然后您就可以穿过列车走到您的车厢就座。"},{"sp":"长对话 1","en":"When you arrive in London, hand the ticket to the guard and he will return the bicycles to you.","cn":"到达伦敦后，把票交给列车员，他会把自行车还给您。"},{"sp":"长对话 1","en":"M: Thank you for the information.","cn":"M: 谢谢您提供的信息。"},{"sp":"长对话 1","en":"That's very helpful.","cn":"非常有帮助。"},{"sp":"长对话 2","en":"M: Good morning.","cn":"M: 早上好。"},{"sp":"长对话 2","en":"Our guest today is Karen Brook.","cn":"我们今天的嘉宾是 Karen Brook。"},{"sp":"长对话 2","en":"Karen is the managing director of Cube Movie Theater, located on Underhill Road.","cn":"Karen 是位于 Underhill 路的 Cube 电影院的总经理。"},{"sp":"长对话 2","en":"Thank you for coming, Karen.","cn":"谢谢你来，Karen。"},{"sp":"长对话 2","en":"W: Thank you for having me.","cn":"W: 谢谢你们邀请我。"},{"sp":"长对话 2","en":"M: So, tell us about your cinema—Cube Movie Theater.","cn":"M: 那么，跟我们说说你的电影院——Cube 电影院吧。"},{"sp":"长对话 2","en":"W: Sure.","cn":"W: 好的。"},{"sp":"长对话 2","en":"Cube Movie Theater has been around now for 11 years.","cn":"Cube 电影院到现在已经有11年了。"},{"sp":"长对话 2","en":"It's located in what used to be a hat factory.","cn":"它位于以前的一家帽子工厂里。"},{"sp":"长对话 2","en":"M: Oh, really?","cn":"M: 哦，真的吗?"},{"sp":"长对话 2","en":"W: Yeah.","cn":"W: 是的。"},{"sp":"长对话 2","en":"There used to be many hat factories in Britain until around the 1950s, but fashion changed and most people stopped wearing hats.","cn":"英国在20世纪50年代之前有很多帽子工厂，但后来时尚改变了，大多数人不再戴帽子了。"},{"sp":"长对话 2","en":"So practically all of those factories had to close down.","cn":"所以几乎所有这些工厂都不得不关闭。"},{"sp":"长对话 2","en":"This one, in particular, was closed for 47 years before we transformed it into a movie theater.","cn":"这家工厂关闭了47年，之后我们才把它改造成了电影院。"},{"sp":"长对话 2","en":"M: I see.","cn":"M: 我明白了。"},{"sp":"长对话 2","en":"I hear there's something else that makes your theater special.","cn":"我听说还有其他东西让你们的电影院很特别。"},{"sp":"长对话 2","en":"What is it that sets you apart from other theaters?","cn":"是什么让你们与其他电影院不同呢?"},{"sp":"长对话 2","en":"W: We are the only movie theater in the whole country that only shows foreign movies.","cn":"W: 我们是全国唯一一家只放映外国电影的电影院。"},{"sp":"长对话 2","en":"M: Is there enough demand for that? I would have thought that in London, most people don't speak foreign languages.","cn":"M: 有足够的需求吗?我原以为在伦敦，大多数人不会说外语。"},{"sp":"长对话 2","en":"W: Sure, there's enough demand.","cn":"W: 当然，有足够的需求。"},{"sp":"长对话 2","en":"The fact that we have been open and in business for all these years proves it.","cn":"我们这些年一直开业营业的事实就证明了这一点。"},{"sp":"长对话 2","en":"London is a very large and international city.","cn":"伦敦是一个非常大而且国际化的城市。"},{"sp":"长对话 2","en":"There are lots of people interested in watching such movies.","cn":"有很多人对观看这类电影感兴趣。"},{"sp":"长对话 2","en":"Furthermore, I might add, all movies come with English text at the bottom of the screen.","cn":"而且，我还要补充一点，所有电影在屏幕底部都配有英文字幕。"},{"sp":"长对话 2","en":"So even if you don't understand what the actors say, you can still read it.","cn":"所以即使你听不懂演员在说什么，你仍然可以阅读字幕。"},{"sp":"长对话 2","en":"M: Of course.","cn":"M: 当然。"},{"sp":"长对话 2","en":"What movie are you showing right now?","cn":"你们现在正在放映什么电影?"},{"sp":"长对话 2","en":"W: This week we're showing a musical from Pakistan.","cn":"W: 这周我们正在放映一部来自巴基斯坦的音乐片。"},{"sp":"长对话 2","en":"It's very popular.","cn":"非常受欢迎。"},{"sp":"听力篇章 1","en":"Love them or hate them, smartphones have become an integral part of our daily lives.","cn":"无论喜欢还是讨厌，智能手机已经成为我们日常生活中不可或缺的一部分。"},{"sp":"听力篇章 1","en":"But should they be left outside the classroom?","cn":"但它们应该被拒之于课堂之外吗？"},{"sp":"听力篇章 1","en":"Nick Gibb, Minister for School Standards in England, believes schools should ban their pupils from bringing in smartphones.","cn":"英格兰学校标准大臣Nick Gibb认为，学校应该禁止学生携带智能手机。"},{"sp":"听力篇章 1","en":"Astrid Natley, a secondary school math teacher, incorporates phones into her classroom. \"My school doesn't have money for tablets,\" she says. \"When students use their phones for research, they learn they have a powerful tool in their hands. If we stop children using phones, we're rejecting something they care about.\"","cn":"中学数学教师Astrid Natley在课堂上使用手机。她说：\"我的学校没有钱买平板电脑。当学生用手机做研究时，他们会意识到自己手中握有一个强大的工具。如果我们禁止孩子使用手机，我们就是在拒绝他们关心的东西。\""},{"sp":"听力篇章 1","en":"Meanwhile, Helen Lockhart, a registered nurse working for community education, supports a complete ban. \"I'm banned from mobile use at work, and my phone must be handed in. If I'm caught with it in my pocket, I will be subject to disciplinary procedure, which will impact on my career. We need to teach children how to behave like the professionals they are striving to become.\"","cn":"与此同时，在社区教育部门工作的注册护士Helen Lockhart支持全面禁止。\"我在工作时被禁止使用手机,而且必须上交手机。如果我被发现口袋里有手机,我将受到纪律处分,这会影响我的职业生涯。我们需要教会孩子们如何表现得像他们努力成为的专业人士。\""},{"sp":"听力篇章 1","en":"Richard Stone, an English teacher, thinks there should be a clear separation between school and home. \"Students should do things differently in the two environments. Children are getting more than enough screen time in their lives without the need to bring their phone into the classroom. The internet is too easy and too unreliable a research tool, so let's leave phones and laptops at home, and show them a different world in their lessons—one of books and pens,\" he says.","cn":"英语教师Richard Stone认为学校和家庭之间应该有明确的界限。\"学生在这两种环境中应该做不同的事情。孩子们在生活中已经有足够多的屏幕时间,没有必要把手机带进课堂。互联网作为研究工具过于便捷且不够可靠,所以让我们把手机和笔记本电脑留在家里,在课堂上向他们展示一个不同的世界——一个书本和笔的世界。\"他说。"},{"sp":"听力篇章 2","en":"Kate, a six-year-old girl, helped her brother wash windows to get a reward promised by her mother, a purple doll that she wanted.","cn":"六岁女孩Kate帮哥哥擦窗户，以获得母亲承诺的奖励——她想要的一个紫色玩偶。"},{"sp":"听力篇章 2","en":"She watched her mother order the doll online.","cn":"她看着母亲在网上订购这个玩偶。"},{"sp":"听力篇章 2","en":"The next day Kate asked if she could check the shipping status, so her mom clicked on the web page and then walked out of the room.","cn":"第二天Kate问能否查看物流状态，于是她妈妈点开网页后走出了房间。"},{"sp":"听力篇章 2","en":"Kate saw that her doll would be arriving the next afternoon, but then she noticed something else, suggestions about other dolls and toys she could order.","cn":"Kate看到她的玩偶将在第二天下午送达，但随后她注意到了别的东西——关于她可以订购的其他玩偶和玩具的推荐。"},{"sp":"听力篇章 2","en":"15 minutes and a few clicks later, with more than $350 worth of dolls in her cart, Kate placed the order and ran off to play.","cn":"15分钟和几次点击之后，购物车里装着价值超过350美元的玩偶，Kate下了单并跑去玩了。"},{"sp":"听力篇章 2","en":"The next day, while checking on another online order, her mother noticed a long list of dolls on the way.","cn":"第二天，在查看另一个网上订单时，她母亲注意到了一长串在途的玩偶。"},{"sp":"听力篇章 2","en":"She was able to cancel two of them, but it was too late to cancel the rest.","cn":"她能够取消其中两个，但已经来不及取消其余的了。"},{"sp":"听力篇章 2","en":"She told her daughter that they were going to be returned.","cn":"她告诉女儿这些玩偶将被退回。"},{"sp":"听力篇章 2","en":"When the packages arrived, Kate wanted to open them, but her parents said no.","cn":"当包裹到达时，Kate想打开它们，但她父母说不行。"},{"sp":"听力篇章 2","en":"Instead of sending back the dolls, her father suggested giving them to the local children's hospital.","cn":"她父亲建议把玩偶送给当地儿童医院，而不是退回去。"},{"sp":"听力篇章 2","en":"So the next week, Kate's family loaded up their car and took all the dolls to the playroom at the children's hospital.","cn":"于是下周，Kate一家装满了他们的车，把所有玩偶送到了儿童医院的游戏室。"},{"sp":"听力篇章 2","en":"Kate was depressed at first, but then she sat with some girl patients and they opened up all the boxes together, laughing and playing.","cn":"Kate起初很沮丧，但随后她和几个住院的女孩坐在一起，她们一起打开了所有盒子，笑着玩着。"},{"sp":"听力篇章 2","en":"She had a lot of fun and learned a really good lesson.","cn":"她玩得很开心，并学到了非常好的一课。"},{"sp":"听力篇章 3","en":"Can the date you were born affect how successful your life is?","cn":"出生日期能否影响你的人生成功程度？"},{"sp":"听力篇章 3","en":"According to recent research done in Australia, the answer is yes.","cn":"根据澳大利亚最近进行的研究，答案是肯定的。"},{"sp":"听力篇章 3","en":"The researchers found that the time when a person starts school has an enduring impact on their lives.","cn":"研究人员发现，一个人开始上学的时间对其一生有持久的影响。"},{"sp":"听力篇章 3","en":"Those who are relatively old, compared to their classmates, have certain advantages over them.","cn":"那些与同学相比年龄相对较大的人比他们具有某些优势。"},{"sp":"听力篇章 3","en":"Previous research has found older students achieve better results.","cn":"先前的研究发现年龄较大的学生取得更好的成绩。"},{"sp":"听力篇章 3","en":"They are also more likely to attend university and become professional athletes, chief executives and even important politicians.","cn":"他们也更有可能上大学，成为职业运动员、首席执行官甚至重要的政治家。"},{"sp":"听力篇章 3","en":"But the Australian researchers wanted to discover what was driving these differences.","cn":"但澳大利亚研究人员想要发现是什么驱动了这些差异。"},{"sp":"听力篇章 3","en":"They suspected older, more mature students obtained more self-confidence than their peers because they achieved better grades.","cn":"他们怀疑年龄较大、更成熟的学生因为取得更好的成绩而获得比同龄人更多的自信。"},{"sp":"听力篇章 3","en":"To test this out, they conducted two studies.","cn":"为了验证这一点，他们进行了两项研究。"},{"sp":"听力篇章 3","en":"One was with high school students and the other with more than a thousand Australian adults, age between 24 and 60 years old.","cn":"一项针对高中生，另一项针对一千多名年龄在24至60岁之间的澳大利亚成年人。"},{"sp":"听力篇章 3","en":"In the first study more than 600 high school students were surveyed about their tendency to take risks and feel confident.","cn":"在第一项研究中，600多名高中生接受了关于他们冒险倾向和自信心的调查。"},{"sp":"听力篇章 3","en":"In the second study, those born on both sides of the cutoff date for starting school were asked to complete online math questions and rate their performance.","cn":"在第二项研究中,那些出生在入学截止日期两侧的人被要求完成在线数学题并评估自己的表现。"},{"sp":"听力篇章 3","en":"They were also asked about the risks they took while riding bicycles and managing their finances.","cn":"他们还被问及骑自行车和管理财务时所冒的风险。"},{"sp":"听力篇章 3","en":"The researchers found that older students displayed greater risk-taking tendencies.","cn":"研究人员发现年龄较大的学生表现出更大的冒险倾向。"},{"sp":"听力篇章 3","en":"While risk-taking can be considered a negative attribute, it's also a characteristic of successful people, including athletes, political leaders and entrepreneurs.","cn":"虽然冒险可以被视为一种负面特质，但它也是成功人士的特征，包括运动员、政治领袖和企业家。"}]},{"id":"cet4-2023-06-2","level":"CET4","exam":"2023_06_2","year":2023,"month":6,"set":2,"type":"整卷听力","title":"2023年6月 四级第2套 · 听力真题","source":"2023年6月 CET-4 第2套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet4-2023-06-set2.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"Police have reported a man being bitten by a 4-foot snake when he lifted his toilet seat on Sunday morning.","cn":"警方报告称,周日早晨一名男子在掀开马桶盖时被一条4英尺长的蛇咬伤。"},{"sp":"短篇新闻 1","en":"The snake was not poisonous, so the man did not have to go to the hospital, but his arm was medically treated at the scene.","cn":"这条蛇没有毒性,因此该男子无需前往医院,但他的手臂在现场接受了医疗处理。"},{"sp":"短篇新闻 1","en":"The police officer interviewed told news reporters the snake didn't belong to the man and it was unclear how it got into the apartment.","cn":"接受采访的警官告诉新闻记者,这条蛇不属于该男子,目前尚不清楚它是如何进入公寓的。"},{"sp":"短篇新闻 1","en":"The snake was eventually captured by the local animal handlers and taken to an animal hospital afterward.","cn":"这条蛇最终被当地动物处理人员捕获,随后被送往动物医院。"},{"sp":"短篇新闻 1","en":"It was being treated for an outer skin infection.","cn":"它正在接受外层皮肤感染的治疗。"},{"sp":"短篇新闻 1","en":"It was unclear who the owner was.","cn":"目前尚不清楚主人是谁。"},{"sp":"短篇新闻 1","en":"The snake may be taken to a local zoo for care if the owner does not come forward.","cn":"如果主人不出现认领,这条蛇可能会被送到当地动物园照料。"},{"sp":"短篇新闻 1","en":"Over the years, other creatures like frogs and fish have found their way into toilets.","cn":"多年来,青蛙和鱼等其他生物也曾以各种方式进入马桶。"},{"sp":"短篇新闻 1","en":"But this was the first instance of a snake in recent years.","cn":"但这是近年来首次出现蛇的情况。"},{"sp":"短篇新闻 2","en":"Every week since last April, Andrea Belcher has been doing something slightly unusual and amusing when she takes out her trash.","cn":"自去年四月以来,每周当Andrea Belcher倒垃圾时,她都会做一件略显不寻常而有趣的事。"},{"sp":"短篇新闻 2","en":"It all started off when a movie star shared a photo of herself putting her trash bins out in a ball gown.","cn":"这一切始于一位电影明星分享了一张自己穿着晚礼服倒垃圾的照片。"},{"sp":"短篇新闻 2","en":"This inspired Andrea to get dressed up to take out the trash.","cn":"这启发了Andrea盛装打扮去倒垃圾。"},{"sp":"短篇新闻 2","en":"She was too embarrassed to do it during the day.","cn":"她白天不好意思这样做。"},{"sp":"短篇新闻 2","en":"So one dark evening, she put on her black off-the-shoulder gown and put her trash bin out.","cn":"所以在一个漆黑的夜晚,她穿上了黑色露肩礼服去倒垃圾桶。"},{"sp":"短篇新闻 2","en":"Her daughter filmed it and the whole family laughed, but it seemed to go down well.","cn":"她女儿拍摄了这一幕,全家人都笑了,但效果似乎不错。"},{"sp":"短篇新闻 2","en":"The following weeks, she found other outfits in her dressing-up box, and dressed up as different characters and famous people, sharing her exploits on social media.","cn":"接下来的几周,她从自己的装扮箱里找出其他服装,打扮成不同的角色和名人,在社交媒体上分享她的趣事。"},{"sp":"短篇新闻 2","en":"Before long, people started offering up their own fancy dresses for her to wear.","cn":"不久之后,人们开始主动提供自己的华丽服装给她穿。"},{"sp":"短篇新闻 2","en":"And before she knew it, she had done 20 weeks.","cn":"在她意识到之前,她已经坚持了20周。"},{"sp":"短篇新闻 2","en":"Explaining why she has kept up the videos, Andrea explained how nice it was to have a little bit of fun and craziness that made people smile.","cn":"在解释为什么她一直坚持拍摄这些视频时,Andrea说能有一点乐趣和疯狂让人们微笑是多么美好。"},{"sp":"短篇新闻 2","en":"Besides, it also helps to remind people in the community to put out their trash bins each week.","cn":"此外,这也有助于提醒社区里的人们每周倒垃圾桶。"},{"sp":"短篇新闻 3","en":"No money but still hungry?","cn":"没钱但仍然饿着？"},{"sp":"短篇新闻 3","en":"No problem!","cn":"没问题！"},{"sp":"短篇新闻 3","en":"Welcome to Frank's restaurant where customers are paying for meals and leaving receipts on a board.","cn":"欢迎来到Frank's餐厅，这里的顾客为餐食付款后会把收据留在一块板子上。"},{"sp":"短篇新闻 3","en":"Anyone who is hungry and wants something to eat can take one, no questions asked and hand it to the staff for some food.","cn":"任何饿了想吃东西的人都可以拿走一张，无需回答任何问题，然后把它交给工作人员换取食物。"},{"sp":"短篇新闻 3","en":"The idea for the board of free meals started after a donor came in with $100 for each member of its staff.","cn":"免费餐食板的想法始于一位捐赠者带着100美元来给每位员工。"},{"sp":"短篇新闻 3","en":"After two staffers returned to their share, there was $700 leftover according to Tarah Morris, the owner of the restaurant, so they decided to do something more by creating the board.","cn":"据餐厅老板Tarah Morris说,两名员工退还了他们的份额后,还剩下700美元,于是他们决定通过创建这块板子来做更多的事情。"},{"sp":"短篇新闻 3","en":"The board of free meals inside the restaurant shows a host of potential meals already paid for by customers, each costing about $10. The board has messages of kindness like, \"If you want more kindness in the world, put it here.\"","cn":"餐厅内的免费餐食板展示着许多已由顾客付款的潜在餐食,每份约10美元。板子上有善意的留言,比如\"如果你想让世界有更多善意,就把它放在这里。\""},{"sp":"短篇新闻 3","en":"The drive has been going on for two weeks and Morris said just under 50 customers have picked up a free meal.","cn":"这项活动已经进行了两周,Morris说有将近50位顾客领取了免费餐食。"},{"sp":"短篇新闻 3","en":"There have been no reports of anyone taking advantage of the situation.","cn":"没有任何人利用这种情况的报告。"},{"sp":"短篇新闻 3","en":"In fact, there are a lot more people giving tickets than receiving.","cn":"事实上,给予餐券的人比领取的人多得多。"},{"sp":"短篇新闻 3","en":"It seems people want to help and are driven by helping others.","cn":"似乎人们想要帮助他人,并被帮助他人所驱动。"},{"sp":"长对话 1","en":"W: Welcome to our program, Friends and Relationships.","cn":"W: 欢迎来到我们的节目《朋友与关系》。"},{"sp":"长对话 1","en":"Our guest today is psychologist Steve Pinker from McGill University.","cn":"我们今天的嘉宾是来自McGill大学的心理学家Steve Pinker。"},{"sp":"长对话 1","en":"M: Glad to be here, Jane.","cn":"M: 很高兴来到这里,Jane。"},{"sp":"长对话 1","en":"W: Hi, Steve.","cn":"W: 你好,Steve。"},{"sp":"长对话 1","en":"Our question today is why friends suddenly disappear.","cn":"我们今天的问题是为什么朋友会突然消失。"},{"sp":"长对话 1","en":"They may block us on their social media accounts and stop responding to our emails.","cn":"他们可能会在社交媒体账号上屏蔽我们,不再回复我们的邮件。"},{"sp":"长对话 1","en":"They simply vanish without a trace.","cn":"他们就这样消失得无影无踪。"},{"sp":"长对话 1","en":"M: The answer may lie in childhood, the way the person related to their mom and dad.","cn":"M: 答案可能在于童年时期,也就是这个人与父母相处的方式。"},{"sp":"长对话 1","en":"It's related to their attachment styles.","cn":"这与他们的依恋类型有关。"},{"sp":"长对话 1","en":"W: Attachment styles?","cn":"W: 依恋类型?"},{"sp":"长对话 1","en":"M: Yeah.","cn":"M: 是的。"},{"sp":"长对话 1","en":"There are two different attachment styles: an anxious attachment style and an avoidant attachment style.","cn":"有两种不同的依恋类型:焦虑型依恋和回避型依恋。"},{"sp":"长对话 1","en":"When there is a relationship breakdown with their parents, children with an anxious attachment style scream and cry to get their parents to come back.","cn":"当与父母的关系破裂时,焦虑型依恋的孩子会又哭又闹,想让父母回来。"},{"sp":"长对话 1","en":"But other children simply shut down and try to deal with their emotions by ignoring the situation.","cn":"但另一些孩子只是封闭自己,试图通过忽视这种情况来处理自己的情绪。"},{"sp":"长对话 1","en":"And these attachment styles carry on into adulthood.","cn":"而这些依恋类型会延续到成年期。"},{"sp":"长对话 1","en":"W: Does avoidance reduce their stress levels?","cn":"W: 回避能降低他们的压力水平吗?"},{"sp":"长对话 1","en":"M: Not really.","cn":"M: 并不能。"},{"sp":"长对话 1","en":"Their stress levels are actually the same as those experienced by the children who yell and scream.","cn":"他们的压力水平实际上和那些大喊大叫的孩子经历的压力水平是一样的。"},{"sp":"长对话 1","en":"W: And I assume both might be termed insecure.","cn":"W: 我猜这两种都可以被称为不安全型。"},{"sp":"长对话 1","en":"M: Exactly.","cn":"M: 完全正确。"},{"sp":"长对话 1","en":"And it's a very insecure attachment.","cn":"这是一种非常不安全的依恋。"},{"sp":"长对话 1","en":"W: How does an insecure attachment affect relationships between friends, co-workers and romantic relationships?","cn":"W: 不安全型依恋如何影响朋友之间、同事之间以及恋爱关系?"},{"sp":"长对话 1","en":"M: It's the same as conflicts.","cn":"M: 和冲突的情况一样。"},{"sp":"长对话 1","en":"So if you have a disagreement with a securely attached person, they're not going to panic.","cn":"所以如果你和一个安全型依恋的人产生分歧,他们不会惊慌失措。"},{"sp":"长对话 1","en":"They're able to hear what the other person is saying and express their own feelings and thoughts effectively.","cn":"他们能够听进对方在说什么,并有效地表达自己的感受和想法。"},{"sp":"长对话 1","en":"However, an insecurely attached person won't.","cn":"然而,不安全型依恋的人不会这样。"},{"sp":"长对话 1","en":"They might either attack you, get defensive, or just disappear from your life.","cn":"他们可能会攻击你,变得防御性很强,或者直接从你的生活中消失。"},{"sp":"长对话 1","en":"To them, a difference, no matter how small in your eyes, signals the end of the relationship.","cn":"对他们来说,分歧,无论在你眼中多么微小,都预示着关系的终结。"},{"sp":"长对话 1","en":"W: That explains why they suddenly disappear.","cn":"W: 这就解释了为什么他们会突然消失。"},{"sp":"长对话 2","en":"M: I hear you're going to Japan soon.","cn":"M: 我听说你快要去日本了。"},{"sp":"长对话 2","en":"W: Yes, that's right.","cn":"W: 是的，没错。"},{"sp":"长对话 2","en":"M: Could I ask you a favor?","cn":"M: 我能请你帮个忙吗？"},{"sp":"长对话 2","en":"W: Sure.","cn":"W: 当然可以。"},{"sp":"长对话 2","en":"What is it?","cn":"什么事？"},{"sp":"长对话 2","en":"M: I was wondering if you could get me some jeans while you're there.","cn":"M: 我在想你在那儿的时候能不能帮我买条牛仔裤。"},{"sp":"长对话 2","en":"I'll pay you back, of course.","cn":"当然我会还你钱的。"},{"sp":"长对话 2","en":"W: A pair of jeans?","cn":"W: 一条牛仔裤？"},{"sp":"长对话 2","en":"Okay.","cn":"好吧。"},{"sp":"长对话 2","en":"I don't see why not.","cn":"我觉得没问题。"},{"sp":"长对话 2","en":"But what's wrong with jeans here?","cn":"但这里的牛仔裤有什么不好吗？"},{"sp":"长对话 2","en":"M: Well, I just love good jeans and Japan happens to make the best in the world.","cn":"M: 嗯，我就是喜欢好牛仔裤，而日本恰好生产世界上最好的牛仔裤。"},{"sp":"长对话 2","en":"My friend brought me a pair from there five years ago, and they still look new.","cn":"我朋友五年前从那儿给我带了一条，现在看起来还跟新的一样。"},{"sp":"长对话 2","en":"W: Really?","cn":"W: 真的吗？"},{"sp":"长对话 2","en":"I had no idea Japan made jeans.","cn":"我完全不知道日本还生产牛仔裤。"},{"sp":"长对话 2","en":"I would have thought America made the best jeans because it's a typical American garment.","cn":"我还以为美国生产最好的牛仔裤呢，因为这是典型的美国服装。"},{"sp":"长对话 2","en":"M: Yeah, I thought so too.","cn":"M: 是啊，我也是这么想的。"},{"sp":"长对话 2","en":"But it turns out Japan still has some very old mills with the traditional weaving tools used to make jeans the original way.","cn":"但事实证明日本仍然有一些非常古老的工厂，使用传统的织布工具以原始方式制作牛仔裤。"},{"sp":"长对话 2","en":"It's a slower process of making clothing.","cn":"这是一种比较慢的服装制作工艺。"},{"sp":"长对话 2","en":"But the end result is surely superior.","cn":"但最终成品绝对更优质。"},{"sp":"长对话 2","en":"Also, the fabric they use is of a higher quality and the dyes are natural.","cn":"而且，他们使用的面料质量更高，染料也是天然的。"},{"sp":"长对话 2","en":"They have a denser weave, and are more durable than any other jeans in the world.","cn":"织得更密实，比世界上任何其他牛仔裤都更耐用。"},{"sp":"长对话 2","en":"W: That sounds cool.","cn":"W: 听起来不错。"},{"sp":"长对话 2","en":"What size do you want and how much are they?","cn":"你要什么尺码的，多少钱？"},{"sp":"长对话 2","en":"M: I have a 34 waist and size 30 or 32 in length.","cn":"M: 我腰围34，长度30或32都行。"},{"sp":"长对话 2","en":"Either is fine.","cn":"哪个都可以。"},{"sp":"长对话 2","en":"They should be around $500.","cn":"大概500美元左右。"},{"sp":"长对话 2","en":"But make double certain they are made in Japan.","cn":"但一定要再三确认是日本制造的。"},{"sp":"长对话 2","en":"W: $500?","cn":"W: 500美元？"},{"sp":"长对话 2","en":"Boy, that's expensive.","cn":"天哪，太贵了。"},{"sp":"长对话 2","en":"Do you typically spend that much on a pair of casual trousers?","cn":"你平时买休闲裤都花这么多钱吗？"},{"sp":"长对话 2","en":"M: They are a little pricey, yes.","cn":"M: 确实是有点贵。"},{"sp":"长对话 2","en":"But they are very special.","cn":"但它们很特别。"},{"sp":"长对话 2","en":"Bear in mind, they will last me several years and they're very fashionable too.","cn":"要知道，它们能穿好几年，而且也很时尚。"},{"sp":"长对话 2","en":"I think they're totally worth it.","cn":"我觉得完全值得。"},{"sp":"听力篇章 1","en":"Every time I walk out of a superhero movie, I feel the same way.","cn":"每次走出超级英雄电影院，我都有同样的感受。"},{"sp":"听力篇章 1","en":"I experience a sense of longing, realizing that there should be more in life.","cn":"我体验到一种渴望感，意识到生活中应该有更多东西。"},{"sp":"听力篇章 1","en":"The desire for adventure is a human one.","cn":"对冒险的渴望是人类共有的。"},{"sp":"听力篇章 1","en":"Superhero films capture this desire perfectly.","cn":"超级英雄电影完美地捕捉了这种渴望。"},{"sp":"听力篇章 1","en":"The plot of each superhero film has become relatively predictable: the world is in peril, the world needs a hero, the hero is in peril, the hero resolves the peril, the hero saves the world.","cn":"每部超级英雄电影的情节都变得相对可预测：世界陷入危险，世界需要英雄，英雄陷入危险，英雄化解危险，英雄拯救世界。"},{"sp":"听力篇章 1","en":"Each film has an attractive lead, several expensive explosions, a few jokes to lighten the mood, and numerous punches that land unrealistically well.","cn":"每部电影都有一个有魅力的主角、几场昂贵的爆炸、一些缓和气氛的笑话，以及无数不切实际地精准命中的拳头。"},{"sp":"听力篇章 1","en":"Even though we basically know what will happen, we keep coming back for more.","cn":"尽管我们基本上知道会发生什么，我们还是不断回来观看更多。"},{"sp":"听力篇章 1","en":"The elites of our society have rejected superhero films.","cn":"我们社会的精英阶层排斥超级英雄电影。"},{"sp":"听力篇章 1","en":"They say the films lack any form of artistry.","cn":"他们说这些电影缺乏任何形式的艺术性。"},{"sp":"听力篇章 1","en":"These movies are criticized as being too simple.","cn":"这些电影被批评为过于简单。"},{"sp":"听力篇章 1","en":"But they give the fans what they want—entertainment.","cn":"但它们给粉丝想要的东西——娱乐。"},{"sp":"听力篇章 1","en":"No matter the form in which they reveal themselves, hero stories will always be present in life. It's not just about being entertained, but also being inspired. One author has mentioned that women desire to play an irreplaceable role in a great adventure. \"Most young women want to be a part of something grand, something important.\" It seems clear that this principle applies to men, as well.","cn":"无论以何种形式呈现，英雄故事将始终存在于生活中。这不仅关乎娱乐，也关乎激励。一位作者曾提到，女性渴望在一场伟大的冒险中扮演不可替代的角色。\"大多数年轻女性想成为宏大事物、重要事物的一部分。\"这一原则显然也适用于男性。"},{"sp":"听力篇章 1","en":"So next time you see your favorite superhero film, be entertained, but also be inspired.","cn":"所以下次你观看最喜欢的超级英雄电影时，享受娱乐，但也要受到激励。"},{"sp":"听力篇章 1","en":"Let that small longing you feel motivate you to make a difference.","cn":"让你感受到的那种微小渴望激励你去做出改变。"},{"sp":"听力篇章 2","en":"Telling stories is one of the most powerful means leaders have to influence, teach and inspire.","cn":"讲故事是领导者用来影响、教导和激励他人的最有力手段之一。"},{"sp":"听力篇章 2","en":"Storytelling forges connections among people.","cn":"讲故事能在人与人之间建立联系。"},{"sp":"听力篇章 2","en":"When it comes to our countries, our communities, and our families, we understand instinctively that the stories we hold in common are an important part of the ties that bind.","cn":"当涉及我们的国家、我们的社区和我们的家庭时,我们本能地理解,我们共同拥有的故事是维系彼此纽带的重要组成部分。"},{"sp":"听力篇章 2","en":"This understanding also holds true in the business world, where an organization's stories, and the stories its leaders tell, help solidify relationships in a way that factual statements don't.","cn":"这种理解在商业世界中同样适用,在那里,一个组织的故事以及其领导者讲述的故事,能以一种事实陈述所无法做到的方式帮助巩固关系。"},{"sp":"听力篇章 2","en":"Good stories do more than create a sense of connection.","cn":"好的故事不仅仅能创造一种联系感。"},{"sp":"听力篇章 2","en":"They build familiarity and trust.","cn":"它们建立熟悉感和信任。"},{"sp":"听力篇章 2","en":"They allow the listener to enter the story, making them more open to learning.","cn":"它们让听众进入故事之中,使他们更愿意学习。"},{"sp":"听力篇章 2","en":"Good stories can contain multiple meanings, so they're surprisingly economical in conveying complex ideas in graspable ways.","cn":"好的故事可以包含多重含义,因此它们在以可理解的方式传达复杂思想方面出人意料地经济高效。"},{"sp":"听力篇章 2","en":"And stories are more engaging than the recital of data points or a discussion of abstract ideas.","cn":"而且故事比罗列数据点或讨论抽象概念更具吸引力。"},{"sp":"听力篇章 2","en":"Stories about professional mistakes and what leaders learned from them are another great avenue for learning.","cn":"关于职业错误以及领导者从中学到的经验的故事是另一条很好的学习途径。"},{"sp":"听力篇章 2","en":"Because people identify so closely with stories, they can imagine how they would have acted in similar circumstances.","cn":"因为人们与故事产生如此紧密的认同,他们可以想象自己在类似情况下会如何行动。"},{"sp":"听力篇章 2","en":"They're able to work through situations in a way that's risk-free.","cn":"他们能够以一种零风险的方式来处理各种情境。"},{"sp":"听力篇章 2","en":"There are extra benefits for leaders: with a simple personal story, they can convey fundamental values.","cn":"对领导者来说还有额外的好处:通过一个简单的个人故事,他们可以传达基本价值观。"},{"sp":"听力篇章 2","en":"They can offer insight into the evolution of their own experience and knowledge, presenting themselves as more approachable and then they are more likely to inspire others to want to know more.","cn":"他们可以深入展现自己经验和知识的演变过程,使自己显得更平易近人,从而更有可能激发他人想要了解更多的愿望。"},{"sp":"听力篇章 3","en":"The U.S. was founded by successive waves of immigrants, and immigrants are still contributing to America today—statistics prove it.","cn":"美国是由一波又一波的移民建立起来的,移民至今仍在为美国做出贡献——统计数据证明了这一点。"},{"sp":"听力篇章 3","en":"On two key measures of financial performance, immigrants outperform native-born Americans.","cn":"在衡量财务表现的两个关键指标上,移民的表现优于本土出生的美国人。"},{"sp":"听力篇章 3","en":"First, they are more likely to be entrepreneurs. From 1996 to 2016, the pace at which immigrants started businesses was double that of U.S.-born individuals. Immigrants aren't just becoming entrepreneurs more frequently. They're often succeeding. Over 40% of Fortune 500 companies had a founder who was either an immigrant or the child of one.","cn":"首先,他们更有可能成为企业家。从1996年到2016年,移民创业的速度是美国本土出生者的两倍。移民不仅更频繁地成为企业家,而且往往取得成功。超过40%的财富500强企业的创始人是移民或移民子女。"},{"sp":"听力篇章 3","en":"Another key measure of financial strength is debt level. Immigrants do better in this area too. Immigrants use credit less often for purchasing cars, homes or starting businesses. This results in significantly lower levels of debt than native-born Americans. For example, 34% of Americans born in Latin America report no credit card or installment loan debt. This can be compared to just 19% of the general population.","cn":"另一个衡量财务实力的关键指标是负债水平。移民在这方面也表现更好。移民较少使用信贷购买汽车、房屋或创业,因此其负债水平显著低于本土出生的美国人。例如,34%的拉丁美洲出生的美国人表示没有信用卡或分期贷款债务,而整体人口中这一比例仅为19%。"},{"sp":"听力篇章 3","en":"Why are immigrants doing so well? The values and habits they bring from their own homelands help explain some of the success.","cn":"为什么移民表现如此出色?他们从祖国带来的价值观和习惯有助于解释部分成功原因。"},{"sp":"听力篇章 3","en":"Unemployment tends to be higher in developing countries. That means more people must become entrepreneurs. Credit is also scarcer in most developing countries. This means individuals must save more in order to achieve their goals, or they borrow money from friends and family rather than a bank. That means less debt and potentially better credit outcomes when they reach the U.S.","cn":"发展中国家的失业率往往更高,这意味着更多人必须成为企业家。在大多数发展中国家,信贷也更加稀缺,这意味着个人必须储蓄更多才能实现目标,或者从朋友和家人而非银行借钱,这意味着更少的债务,并且在他们到达美国时可能获得更好的信用结果。"}]},{"id":"cet4-2023-12-1","level":"CET4","exam":"2023_12_1","year":2023,"month":12,"set":1,"type":"整卷听力","title":"2023年12月 四级第1套 · 听力真题","source":"2023年12月 CET-4 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet4-2023-12-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"Have you noticed how similar you are to your friends? It may be because your brains operate in harmony with each other. We know that friends are more likely to be the same age, gender and ethnic background as each other. Now it seems their brains are alike, too.","cn":"你有没有注意到你和朋友有多相似?这可能是因为你们的大脑彼此协调运作。我们知道朋友之间更有可能拥有相同的年龄、性别和种族背景。现在看来他们的大脑也很相似。"},{"sp":"短篇新闻 1","en":"Researchers at the University of California scanned the brains of 42 classmates while they watched videos intended to provoke varying responses.","cn":"加利福尼亚大学的研究人员扫描了42名同学的大脑,同时让他们观看旨在引发不同反应的视频。"},{"sp":"短篇新闻 1","en":"Some people might find a romantic scene touching, for instance, while others would feel it was embarrassing.","cn":"例如,有些人可能会觉得浪漫场景令人感动,而另一些人则会觉得尴尬。"},{"sp":"短篇新闻 1","en":"The activity of friends' brains was more similar than that of people who didn't know each other, particularly in regions involved in attention, emotion and language.","cn":"朋友大脑的活动比不认识的人更相似,特别是在涉及注意力、情绪和语言的区域。"},{"sp":"短篇新闻 1","en":"This similarity was strong enough that it could be used to predict whether two people were already friends or not.","cn":"这种相似性强到足以用来预测两个人是否已经是朋友。"},{"sp":"短篇新闻 1","en":"The relationship probably goes two ways.","cn":"这种关系可能是双向的。"},{"sp":"短篇新闻 1","en":"We are drawn to people who think like us; we then influence their thoughts over time, which may push their brain activity into more closely resembling our own.","cn":"我们会被那些思维方式与我们相似的人所吸引;随着时间的推移,我们会影响他们的想法,这可能会促使他们的大脑活动更接近我们自己的。"},{"sp":"短篇新闻 2","en":"Two men who have been best friends for 60 years have just realized they are actually brothers.","cn":"两名保持了60年最佳友谊的男子刚刚意识到他们实际上是兄弟。"},{"sp":"短篇新闻 2","en":"It's reported that Alan Robinson and Walter MacDonald met in the 6th grade at a school in Hawaii.","cn":"据报道，Alan Robinson和Walter MacDonald在夏威夷的一所学校读六年级时相识。"},{"sp":"短篇新闻 2","en":"They have been best friends ever since.","cn":"从那时起他们就一直是最好的朋友。"},{"sp":"短篇新闻 2","en":"Alan was given away for adoption soon after he was born, and Walter never knew his father.","cn":"Alan出生后不久就被送去领养，而Walter从未见过自己的父亲。"},{"sp":"短篇新闻 2","en":"So recently, they made separate attempts on DNA matching websites to discover more about their ancestry.","cn":"因此最近，他们分别在DNA匹配网站上尝试了解更多关于自己祖先的信息。"},{"sp":"短篇新闻 2","en":"Walter was astonished to find that he matched with website user Robi 737.","cn":"Walter惊讶地发现他与网站用户Robi 737匹配。"},{"sp":"短篇新闻 2","en":"He knew immediately that this was his best friend Alan, whose friends call him Robi and flew 737 airplanes when he was a pilot.","cn":"他立即知道这就是他最好的朋友Alan，Alan的朋友们都叫他Robi，而且他当飞行员时驾驶737飞机。"},{"sp":"短篇新闻 2","en":"The pair were born to the same mother 15 months apart.","cn":"这对朋友出生于同一位母亲，相隔15个月。"},{"sp":"短篇新闻 3","en":"Amid all the election drama, air pollution problems and disease outbreaks, five tourists' good work is being spread online.","cn":"在所有选举闹剧、空气污染问题和疾病爆发之中,五名游客的善举正在网上传播。"},{"sp":"短篇新闻 3","en":"Yesterday two male and three female tourists were spotted walking the kilometer-long beach, picking up trash.","cn":"昨天,两名男性游客和三名女性游客被发现在长达一公里的海滩上行走,捡拾垃圾。"},{"sp":"短篇新闻 3","en":"One of the male tourists from Australia commented that although there was a lot of trash, nobody was doing anything.","cn":"其中一名来自澳大利亚的男性游客评论说,尽管有很多垃圾,却没有人在做任何事情。"},{"sp":"短篇新闻 3","en":"The beach was not as nice or beautiful as it should be.","cn":"海滩并不像它本应该的那样美好或美丽。"},{"sp":"短篇新闻 3","en":"He felt so sad to see such a gorgeous place littered with so much trash.","cn":"看到如此gorgeous的地方被这么多垃圾弄得一片狼藉,他感到非常难过。"},{"sp":"短篇新闻 3","en":"Thus, he and his friends decided to grab a few trash bags and clean it all up.","cn":"因此,他和他的朋友们决定拿几个垃圾袋把这些都清理干净。"},{"sp":"短篇新闻 3","en":"A man passing by decided to video their good deed and put it on the internet.","cn":"一名路过的男子决定录下他们的善举并放到网上。"},{"sp":"短篇新闻 3","en":"It was unclear where the rest of the group was from, but they were most likely traveling together.","cn":"目前还不清楚这个团队其余成员来自哪里,但他们很可能是一起旅行的。"},{"sp":"短篇新闻 3","en":"One local woman commented on being embarrassed that tourists were cleaning up their beach.","cn":"一位当地女性评论说,游客在清理他们的海滩让她感到尴尬。"},{"sp":"短篇新闻 3","en":"Another mentioned that it was actually the natives who brought food and drinks then left trash all along the island.","cn":"另一个人提到,实际上是本地人带来食物和饮料,然后把垃圾留在整个岛上。"},{"sp":"长对话 1","en":"W: Hello Benjamin, Dan and I will be going for a run along the canal Saturday morning.","cn":"W: 你好 Benjamin,我和 Dan 周六早上要沿着运河跑步。"},{"sp":"长对话 1","en":"Would you like to join us?","cn":"你想一起来吗?"},{"sp":"长对话 1","en":"M: I'd love to, but I hurt my ankle last weekend playing football with work colleagues.","cn":"M: 我很想去,但我上周末和同事踢足球时伤了脚踝。"},{"sp":"长对话 1","en":"W: Oh dear, is it serious?","cn":"W: 哎呀,严重吗?"},{"sp":"长对话 1","en":"M: No, not at all.","cn":"M: 不,一点也不严重。"},{"sp":"长对话 1","en":"I landed badly during a fall and twisted it a little, but it's no big deal.","cn":"我摔倒的时候落地不太好,扭了一下,但不是什么大事。"},{"sp":"长对话 1","en":"It's just a little swollen and I should be fine for next Saturday if you still want to go for a jog then.","cn":"只是有点肿,下周六应该就没事了,如果你那时候还想去慢跑的话。"},{"sp":"长对话 1","en":"W: I won't be here next Saturday.","cn":"W: 我下周六不在这儿。"},{"sp":"长对话 1","en":"I'm going to the zoo.","cn":"我要去动物园。"},{"sp":"长对话 1","en":"M: The zoo?","cn":"M: 动物园?"},{"sp":"长对话 1","en":"W: Yeah.","cn":"W: 对。"},{"sp":"长对话 1","en":"My little nephew turns six, and he loves the zoo, so the whole family is going.","cn":"我小侄子要过六岁生日了,他很喜欢动物园,所以全家人都要去。"},{"sp":"长对话 1","en":"M: Oh, okay then.","cn":"M: 哦,好吧。"},{"sp":"长对话 1","en":"I haven't been to a zoo since I was a kid.","cn":"我从小时候起就没去过动物园了。"},{"sp":"长对话 1","en":"W: They are nowhere near as popular as they used to be when we were children.","cn":"W: 动物园远不像我们小时候那么受欢迎了。"},{"sp":"长对话 1","en":"I personally feel sorry for the poor animals stuck in cages, but there's no denying they are fun and educational for children.","cn":"我个人觉得那些被关在笼子里的可怜动物很可怜,但不可否认的是,它们对孩子们来说既有趣又有教育意义。"},{"sp":"长对话 1","en":"M: Do you know if Dan will be around next Saturday?","cn":"M: 你知道 Dan 下周六有空吗?"},{"sp":"长对话 1","en":"W: Yeah, I think he will.","cn":"W: 嗯,我觉得他应该有空。"},{"sp":"长对话 1","en":"Just send him a text message.","cn":"给他发个短信吧。"},{"sp":"长对话 1","en":"He's always keen on physical activities.","cn":"他总是很热衷于体育活动。"},{"sp":"长对话 1","en":"M: That's true.","cn":"M: 没错。"},{"sp":"长对话 1","en":"Dan is extremely fit and healthy.","cn":"Dan 身体特别好。"},{"sp":"长对话 1","en":"He goes to the gym most days, plus tennis two or three times a week.","cn":"他几乎每天都去健身房,再加上每周打两三次网球。"},{"sp":"长对话 1","en":"W: So, what have you been doing to stay busy while you've had that swollen ankle?","cn":"W: 那么,你脚踝肿的这段时间都在忙些什么呢?"},{"sp":"长对话 1","en":"M: I've been catching up on some reading.","cn":"M: 我一直在补看一些书。"},{"sp":"长对话 1","en":"I was given three books over Christmas, and I'm only now getting around to reading them.","cn":"圣诞节的时候收到了三本书,现在才开始读。"},{"sp":"长对话 2","en":"W: Our guest on today's Book Talk is John Black, the author of the new bestseller, Retire Early.","cn":"W: 我们今天《书谈》节目的嘉宾是 John Black，新晋畅销书《提前退休》的作者。"},{"sp":"长对话 2","en":"M: Thanks for having me on the show, Lisa.","cn":"M: 谢谢邀请我来节目，Lisa。"},{"sp":"长对话 2","en":"W: John, your book is getting a lot of attention, partly because you write that most people can retire by 40.","cn":"W: John，你的书正受到很多关注，部分原因是你在书中写到大多数人可以在 40 岁退休。"},{"sp":"长对话 2","en":"Is that realistic?","cn":"这现实吗？"},{"sp":"长对话 2","en":"M: Definitely.","cn":"M: 绝对现实。"},{"sp":"长对话 2","en":"When researching this book, I interviewed hundreds of people who retired by 40.","cn":"在研究这本书时，我采访了数百位在 40 岁前退休的人。"},{"sp":"长对话 2","en":"W: Okay, but how much money does a person need to retire?","cn":"W: 好吧，但是一个人需要多少钱才能退休？"},{"sp":"长对话 2","en":"I've read articles recommending one million dollars as a good figure for retirement.","cn":"我读过一些文章推荐一百万美元作为退休的合适数字。"},{"sp":"长对话 2","en":"M: While most financial planners do give numbers, I don't think that's useful, as people are living in different areas with different costs of living, and have different needs and wants, which is why I suggest that people aim for financial independence.","cn":"M: 虽然大多数理财规划师确实会给出具体数字，但我认为那没什么用，因为人们生活在不同地区，生活成本不同，需求和期望也不同，所以我建议人们以财务独立为目标。"},{"sp":"长对话 2","en":"W: What do you mean by financial independence?","cn":"W: 你说的财务独立是什么意思？"},{"sp":"长对话 2","en":"M: Having investment income that's greater than monthly expenses.","cn":"M: 就是投资收入大于月度开销。"},{"sp":"长对话 2","en":"W: That sounds risky to me.","cn":"W: 这在我看来有点冒险。"},{"sp":"长对话 2","en":"What if an accident happens or you get ill and need medical treatment?","cn":"如果发生意外或者生病需要医疗怎么办？"},{"sp":"长对话 2","en":"Shouldn't people have extra cash for emergencies?","cn":"人们不应该留些额外现金以备不时之需吗？"},{"sp":"长对话 2","en":"M: Too many people spend their lives working on jobs they hate because they're afraid, so I counsel people to take risks.","cn":"M: 太多人因为恐惧而一辈子做着自己讨厌的工作，所以我建议人们去冒险。"},{"sp":"长对话 2","en":"Retirement doesn't have to be permanent, and if people need to, they can go back to work.","cn":"退休不一定是永久的，如果需要，人们可以重返工作。"},{"sp":"长对话 2","en":"W: But it's not always easy to get back into the workforce after an extended absence.","cn":"W: 但是长时间离开职场后再回去并不总是那么容易。"},{"sp":"长对话 2","en":"M: True, but if you keep current with your skills, you will be attracted to employers.","cn":"M: 确实，但如果你保持技能更新，你会对雇主有吸引力的。"},{"sp":"长对话 2","en":"W: Maybe, but how can anyone save enough to retire by 40 when most people can't retire at 60?","cn":"W: 也许吧，但大多数人 60 岁都退不了休，怎么可能有人能存够钱在 40 岁退休呢？"},{"sp":"长对话 2","en":"M: Simple, by cutting housing, food, and transport expenses, and investing half your monthly income.","cn":"M: 很简单，削减住房、食物和交通开支，然后把月收入的一半用于投资。"},{"sp":"长对话 2","en":"W: That sounds impossible.","cn":"W: 这听起来不可能。"},{"sp":"长对话 2","en":"M: I admit it's difficult, but it has worked for thousands.","cn":"M: 我承认很难，但对成千上万的人确实有效。"},{"sp":"听力篇章 1","en":"New research from America studies the role that the presence of individuals from different social or racial groups has in influencing consumers' food choices.","cn":"来自美国的新研究探讨了来自不同社会或种族群体的个体的存在对消费者食物选择的影响作用。"},{"sp":"听力篇章 1","en":"This research found college students were more likely to choose healthy food in the presence of an observer of a different race, as opposed to an observer from their own race.","cn":"该研究发现,与同种族观察者在场相比,大学生在不同种族观察者在场时更有可能选择健康食品。"},{"sp":"听力篇章 1","en":"The same was true when they were with someone from a different university, compared to someone from their own.","cn":"当他们与来自不同大学的人在一起时,情况也是如此,而不是与来自自己大学的人在一起时。"},{"sp":"听力篇章 1","en":"Researchers say this was because participants anticipated more negative judgment from an outsider group.","cn":"研究人员表示,这是因为参与者预期会受到外部群体更多的负面评判。"},{"sp":"听力篇章 1","en":"In contrast, they felt less judged by members of their own group.","cn":"相比之下,他们感到受到自己群体成员的评判较少。"},{"sp":"听力篇章 1","en":"In one experiment, participants were offered the choice between candy and fruit as a snack.","cn":"在一项实验中,参与者可以选择糖果或水果作为零食。"},{"sp":"听力篇章 1","en":"When in the presence of an unknown student from their own university, only 12 percent of students selected the healthier option.","cn":"当与一名来自自己大学的陌生学生在场时,只有12%的学生选择了更健康的选项。"},{"sp":"听力篇章 1","en":"However, this number was 31 percent when in the presence of an unknown student from another university.","cn":"然而,当与一名来自另一所大学的陌生学生在场时,这一数字为31%。"},{"sp":"听力篇章 1","en":"Other experiments showed similar results based on racial group.","cn":"其他基于种族群体的实验显示了类似的结果。"},{"sp":"听力篇章 1","en":"What's the reason for this pattern? The study found that people feel judged to a larger extent by members of other groups. Because of this, they strategically use healthy food choices to make a positive impression. There have been many attempts to help consumers make healthier choices, but consumers often struggle to maintain a healthy diet. This research finds that one way to promote a healthy diet could be to advertise the social benefits of healthy choices.","cn":"这种模式的原因是什么?该研究发现,人们感到在更大程度上受到其他群体成员的评判。因此,他们策略性地使用健康食品选择来留下积极印象。已经有许多尝试帮助消费者做出更健康的选择,但消费者往往难以保持健康饮食。该研究发现,促进健康饮食的一种方法可能是宣传健康选择的社会益处。"},{"sp":"听力篇章 2","en":"For college students under pressure, a dog may be the best stress fighter around, according to the finding of a recent study. \"It's a really powerful finding,\" said Patricia Pendry, who led the study. \"Universities are doing a lot of great work trying to help students succeed academically, especially those who may be at risk due to a history of mental health issues or academic and learning issues. This study shows that traditional stress management approaches aren't as effective for this population compared with programs that focus on providing opportunities to interact with therapy dogs.\"","cn":"根据最近一项研究的发现，对于压力之下的大学生来说，狗可能是最好的压力克星。领导这项研究的Patricia Pendry说：\"这是一个非常有力的发现。大学正在做大量出色的工作来帮助学生在学业上取得成功，尤其是那些可能因心理健康问题史或学业和学习问题而处于风险中的学生。这项研究表明，传统的压力管理方法对这一群体的效果不如那些专注于提供与治疗犬互动机会的项目。\""},{"sp":"听力篇章 2","en":"The researchers measured executive functioning in the students involved in the study.","cn":"研究人员测量了参与研究的学生的执行功能。"},{"sp":"听力篇章 2","en":"Executive function is a term for the skills one needs to plan, organize, motivate, concentrate and memorize.","cn":"执行功能是指一个人计划、组织、激励、集中注意力和记忆所需的技能。"},{"sp":"听力篇章 2","en":"These are skills students need to succeed in college.","cn":"这些是学生在大学取得成功所需要的技能。"},{"sp":"听力篇章 2","en":"The researchers found that students who were most at risk had the most improvements in executive functioning after interacting with therapy dogs.","cn":"研究人员发现,风险最高的学生在与治疗犬互动后,执行功能改善最大。"},{"sp":"听力篇章 2","en":"These results remained when researchers followed up six weeks later.","cn":"当研究人员在六周后进行随访时,这些结果仍然保持。"},{"sp":"听力篇章 2","en":"Many universities provide academic stress management programs and workshops.","cn":"许多大学提供学业压力管理项目和研讨会。"},{"sp":"听力篇章 2","en":"These are traditionally very similar to college classes.","cn":"这些传统上与大学课程非常相似。"},{"sp":"听力篇章 2","en":"They often talk about ways to get more sleep, set goals, or manage stress or anxiety.","cn":"它们通常讨论如何获得更多睡眠、设定目标或管理压力或焦虑的方法。"},{"sp":"听力篇章 2","en":"Pendry acknowledges that these are really important topics and these workshops help typical students succeed.","cn":"Pendry承认这些是非常重要的话题,这些研讨会帮助典型学生取得成功。"},{"sp":"听力篇章 2","en":"But they're less helpful for struggling students.","cn":"但它们对挣扎中的学生帮助较小。"},{"sp":"听力篇章 2","en":"Pendry believes those students may experience the programs as another lecture and feel even more stressed.","cn":"Pendry认为,那些学生可能会将这些项目体验为又一次讲座,并感到更加紧张。"},{"sp":"听力篇章 3","en":"Taking risks in business does not mean going into business blindly and then expecting great results.","cn":"在商业中冒险并不意味着盲目创业然后期待巨大的成果。"},{"sp":"听力篇章 3","en":"On the contrary, taking risks in entrepreneurship involves careful planning and hard work.","cn":"相反,创业中的冒险涉及周密的计划和艰苦的工作。"},{"sp":"听力篇章 3","en":"Nobody can really be sure if risks will be met with success, no matter how calculated they may be.","cn":"无论风险计算得多么仔细,没有人能真正确定风险是否会获得成功。"},{"sp":"听力篇章 3","en":"But this should not stop you from taking risks, as risks are necessary if you want your business to succeed.","cn":"但这不应该阻止你冒险,因为如果你想让企业成功,冒险是必要的。"},{"sp":"听力篇章 3","en":"Some risks may not work out, but an optimistic risk-taker will always look at failure as an opportunity to learn. The willingness to experiment with new ideas is key to business growth. As the old saying goes, \"Nothing ventured, nothing gained.\" Failure will teach you how to think and plan strategically. But just remember that not all risks are good ones, and when you fail, learn from it and move forward.","cn":"有些风险可能不会成功,但乐观的冒险者总是将失败视为学习的机会。愿意尝试新想法是企业成长的关键。正如老话所说,\"不入虎穴,焉得虎子。\"失败会教你如何进行战略思考和规划。但要记住,并非所有风险都是好的,当你失败时,要从中吸取教训并继续前进。"},{"sp":"听力篇章 3","en":"Since most people tend to avoid risk, businesses that are brave enough to take risks already have a competitive advantage.","cn":"由于大多数人倾向于规避风险,那些勇于冒险的企业已经拥有了竞争优势。"},{"sp":"听力篇章 3","en":"They are the ones setting the standard with new ideas, fresh offers and bold inventions.","cn":"他们用新想法、新颖的产品和大胆的发明树立标准。"},{"sp":"听力篇章 3","en":"Risk-takers are best at adapting in difficult times.","cn":"冒险者最善于在困难时期适应。"},{"sp":"听力篇章 3","en":"Simply put, when most individuals stay away from risk, it means less competition for risk-takers.","cn":"简单地说,当大多数人远离风险时,这意味着冒险者面临的竞争更少。"},{"sp":"听力篇章 3","en":"We don't know if you'll achieve what these risk-takers have achieved.","cn":"我们不知道你是否能取得这些冒险者所取得的成就。"},{"sp":"听力篇章 3","en":"But for as long as you want to stay safe, and for as long as you are content with where your business is right now, you will never find out.","cn":"但只要你想保持安全,只要你满足于企业目前的状况,你就永远不会知道答案。"}]},{"id":"cet4-2023-12-2","level":"CET4","exam":"2023_12_2","year":2023,"month":12,"set":2,"type":"整卷听力","title":"2023年12月 四级第2套 · 听力真题","source":"2023年12月 CET-4 第2套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet4-2023-12-set2.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"短篇新闻 1","en":"A police officer in the U.S. stopped a large SUV car that was going very slowly and drifting across lanes on a highway.","cn":"美国一名警察拦下了一辆在高速公路上行驶缓慢并跨车道漂移的大型SUV。"},{"sp":"短篇新闻 1","en":"He expected to find a driver who was either very drunk or having a medical emergency.","cn":"他原以为会发现一个醉酒严重或突发疾病的司机。"},{"sp":"短篇新闻 1","en":"Instead, the officer discovered a five-year-old boy sat on the edge of the driver's seat.","cn":"然而，警察却发现一个五岁男孩坐在驾驶座边缘。"},{"sp":"短篇新闻 1","en":"His feet could barely reach the brake, and his head was only just high enough to see out of the windows.","cn":"他的脚几乎够不到刹车，头部也刚好高到能看出车窗外。"},{"sp":"短篇新闻 1","en":"The child had taken the keys to the family car while his teenage sister was napping.","cn":"这个孩子趁十几岁的姐姐午睡时拿走了家里的车钥匙。"},{"sp":"短篇新闻 1","en":"He then drove three kilometers across town before getting on the highway.","cn":"然后他开车穿过城镇行驶了三公里后上了高速公路。"},{"sp":"短篇新闻 1","en":"The boy later told confused officers that he was planning to travel to California and buy a Lamborghini sports car.","cn":"男孩后来告诉困惑的警察，他计划去加利福尼亚州买一辆Lamborghini跑车。"},{"sp":"短篇新闻 1","en":"Although he only had three dollars in his wallet, at least he was driving in the right direction.","cn":"尽管他钱包里只有三美元，但至少他开车的方向是对的。"},{"sp":"短篇新闻 2","en":"Mobile phones have changed the way we live, how we read, work, communicate, and shop.","cn":"手机已经改变了我们的生活方式，改变了我们阅读、工作、交流和购物的方式。"},{"sp":"短篇新闻 2","en":"But we already know this.","cn":"但我们已经知道这一点。"},{"sp":"短篇新闻 2","en":"What we have not yet understood is the way the tiny machines in front of us are changing our skeletons, possibly altering not just the way we behave but even the very shape of our bodies.","cn":"我们尚未理解的是，我们面前的这些小型机器正在改变我们的骨骼，可能不仅改变我们的行为方式，甚至改变我们身体的形状。"},{"sp":"短篇新闻 2","en":"New scientific research at the University of the Sunshine Coast in Queensland, Australia, suggests that young people are developing extra pieces of bone at the backs of their heads.","cn":"澳大利亚昆士兰阳光海岸大学的最新科学研究表明，年轻人的后脑勺正在长出额外的骨块。"},{"sp":"短篇新闻 2","en":"These pieces of bone are caused by the way people bend their heads when they use the phone.","cn":"这些骨块是由人们使用手机时低头的方式造成的。"},{"sp":"短篇新闻 2","en":"This shifts weight onto the muscles at the back of the head and causes the bone to grow in a way that is not normal.","cn":"这会将重量转移到后脑勺的肌肉上，并导致骨骼以不正常的方式生长。"},{"sp":"短篇新闻 2","en":"This process can be compared to the way the skin hardens in response to constant rubbing or pressure.","cn":"这一过程可以与皮肤因持续摩擦或压力而变硬的方式相比较。"},{"sp":"短篇新闻 2","en":"The result is a piece of bone like a horn that sticks out from the head by the neck.","cn":"其结果是在颈部附近从头部突出的一块类似角的骨头。"},{"sp":"短篇新闻 3","en":"A village is going to throw a birthday party for an orange cat named Wilbur, who has become famous for making a regular appearance at local shops.","cn":"一个村庄将为一只名叫Wilbur的橘猫举办生日派对,这只猫因定期光顾当地商店而出名。"},{"sp":"短篇新闻 3","en":"Wilbur has his own Internet pages as he approaches his 10th birthday on July 7. Wilbur is both bold and friendly. He spends most of his time in shops and businesses around the village. He'll just take himself into any shop, anywhere. There was one time when the doctor's receptionist came back and he was sitting on her chair. Among his favorite haunts are a local hairdresser, two pubs, and the Nottingham Primary School.","cn":"Wilbur即将在7月7日迎来10岁生日,它有自己的网页。Wilbur既大胆又友好,它大部分时间都在村里的商店和企业中度过。它会自己走进任何商店、任何地方。有一次医生的接待员回来时,发现它正坐在她的椅子上。它最喜欢去的地方包括一家当地理发店、两家酒吧和Nottingham小学。"},{"sp":"短篇新闻 3","en":"Lesley Harper, who runs one of the pubs, said the cat has been a big hit with their customers. \"He's been a regular visitor for most of this year,\" she told the Press Association. \"He's a very relaxed cat, happy for customers and villagers young and old to come in and say hello.\" She also said he is a cat of expensive tastes who likes his high priced cat food.","cn":"经营其中一家酒吧的Lesley Harper说这只猫深受顾客喜爱。她告诉Press Association:\"今年大部分时间它都是常客。它是一只非常放松的猫,乐意让顾客和村民不论老少进来打招呼。\"她还说它是一只品味昂贵的猫,喜欢吃高价猫粮。"},{"sp":"短篇新闻 3","en":"Sarah Godfrey, who is organizing Wilbur's party, told the local newspaper, \"Wilbur is part of our lives, as he is for everyone who lives in the village.\"","cn":"正在组织Wilbur派对的Sarah Godfrey告诉当地报纸:\"Wilbur是我们生活的一部分,对村里每个人来说都是如此。"},{"sp":"长对话 1","en":"M: So, where do you want to go for lunch?","cn":"M: 那么，你想去哪儿吃午饭？"},{"sp":"长对话 1","en":"W: I don't know.","cn":"W: 我不知道。"},{"sp":"长对话 1","en":"Do you have anything in mind?","cn":"你有什么想法吗？"},{"sp":"长对话 1","en":"M: What about the Sandwich Place on Camden Street?","cn":"M: Camden Street 上的三明治店怎么样？"},{"sp":"长对话 1","en":"W: Hmm… No, sorry.","cn":"W: 嗯……不好意思。"},{"sp":"长对话 1","en":"I don't feel like sandwiches today.","cn":"我今天不想吃三明治。"},{"sp":"长对话 1","en":"It's a great place, but I think we go there too often.","cn":"那地方很不错，但我觉得我们去得太频繁了。"},{"sp":"长对话 1","en":"M: That's true.","cn":"M: 确实。"},{"sp":"长对话 1","en":"Remember that's where we saw Brigette Clark, the famous movie star.","cn":"还记得我们就是在那儿看到电影明星 Brigette Clark 的。"},{"sp":"长对话 1","en":"W: Of course.","cn":"W: 当然记得。"},{"sp":"长对话 1","en":"How could I ever forget?","cn":"我怎么可能忘记？"},{"sp":"长对话 1","en":"There were crowds of people around her asking for a photo with her.","cn":"当时一群人围着她要跟她合影。"},{"sp":"长对话 1","en":"M: What about hamburgers, then?","cn":"M: 那汉堡怎么样？"},{"sp":"长对话 1","en":"There's that American style diner on the way to the mall.","cn":"去购物中心路上有家美式餐厅。"},{"sp":"长对话 1","en":"W: I like that place.","cn":"W: 我喜欢那家店。"},{"sp":"长对话 1","en":"Their chips are great, but their service takes a long time.","cn":"他们的薯条很棒，但是上菜要等很久。"},{"sp":"长对话 1","en":"And I need to get back by 2:30 for a conference call.","cn":"而且我需要在两点半之前回去开电话会议。"},{"sp":"长对话 1","en":"How about trying something new?","cn":"要不试试新地方？"},{"sp":"长对话 1","en":"We could try Mario's, the new Italian restaurant on the corner.","cn":"我们可以去 Mario's，拐角处那家新开的意大利餐厅。"},{"sp":"长对话 1","en":"It looks all right.","cn":"看起来不错。"},{"sp":"长对话 1","en":"Have you been there?","cn":"你去过吗？"},{"sp":"长对话 1","en":"M: No, I haven't, but I've noticed that it has great reviews on the Internet.","cn":"M: 没有，我没去过，但我注意到它在网上评价很好。"},{"sp":"长对话 1","en":"It's supposed to be one of the best Italians in town.","cn":"据说是城里最好的意大利餐厅之一。"},{"sp":"长对话 1","en":"I think Jeremy has been there and said it was amazing.","cn":"我想 Jeremy 去过，说那里很棒。"},{"sp":"长对话 1","en":"I'm up for that.","cn":"我没意见。"},{"sp":"长对话 1","en":"W: Cool.","cn":"W: 好啊。"},{"sp":"长对话 1","en":"Have you asked Jeremy if he would like to come with us?","cn":"你问过 Jeremy 想不想跟我们一起去吗？"},{"sp":"长对话 1","en":"M: I already have.","cn":"M: 我问过了。"},{"sp":"长对话 1","en":"He says he can't.","cn":"他说不行。"},{"sp":"长对话 1","en":"He has brought his own lunch today, so he will stay in.","cn":"他今天自己带了午饭，所以要待在办公室。"},{"sp":"长对话 1","en":"I think his wife made him soup.","cn":"我想是他妻子给他做的汤。"},{"sp":"长对话 1","en":"W: Poor Jeremy.","cn":"W: 可怜的 Jeremy。"},{"sp":"长对话 1","en":"His wife is a terrible cook.","cn":"他妻子厨艺太差了。"},{"sp":"长对话 1","en":"He should throw that soup in the bin and join us.","cn":"他应该把那汤扔进垃圾桶，然后跟我们一起去。"},{"sp":"长对话 2","en":"W: Hi, there. How are you today? Do you have a reservation with us already?","cn":"W: 你好，今天怎么样？您已经在我们这里预订了吗？"},{"sp":"长对话 2","en":"M: Good afternoon.","cn":"M: 下午好。"},{"sp":"长对话 2","en":"Yes, we reserved our rooms yesterday morning on your website for three nights.","cn":"是的，我们昨天早上在你们的网站上预订了三晚的房间。"},{"sp":"长对话 2","en":"The name's Patterson.","cn":"名字是Patterson。"},{"sp":"长对话 2","en":"W: Okay. Let me have a look. Yes, we have it here. You brought the whole family with you, I see.","cn":"W: 好的，让我看看。是的，在这里找到了。我看您带着全家人一起来。"},{"sp":"长对话 2","en":"M: Yes, the two kids, my wife and I, and her parents too.","cn":"M: 是的，两个孩子，我妻子和我，还有她的父母。"},{"sp":"长对话 2","en":"W: Great.","cn":"W: 很好。"},{"sp":"长对话 2","en":"So we have a family room for you and your wife and the kids, and another double room for your parents-in-law.","cn":"我们为您和您的妻子以及孩子们准备了一间家庭房，还有另一间双人房给您的岳父岳母。"},{"sp":"长对话 2","en":"They are right next to each other on the ground floor, since you mentioned in your message that they have trouble with stairs.","cn":"两间房紧挨着，在一楼，因为您在留言中提到他们上下楼梯有困难。"},{"sp":"长对话 2","en":"M: That's wonderful.","cn":"M: 太好了。"},{"sp":"长对话 2","en":"My father-in-law has had terrible problems getting up and down stairs since his knee operation last April.","cn":"我岳父自从去年四月做了膝盖手术后，上下楼梯就一直很困难。"},{"sp":"长对话 2","en":"W: I'm sorry to hear that.","cn":"W: 听到这个我很遗憾。"},{"sp":"长对话 2","en":"And if you need any help to find transportation for the whole family, we can definitely recommend someone for you.","cn":"如果您需要任何帮助为全家人找交通工具，我们绝对可以为您推荐。"},{"sp":"长对话 2","en":"M: We were thinking of renting a car, but we will explore all the options available for sure.","cn":"M: 我们本来在考虑租车，但我们肯定会了解所有可选的方案。"},{"sp":"长对话 2","en":"So, yes, that would be very helpful in comparing prices.","cn":"所以，是的，这对比较价格会很有帮助。"},{"sp":"长对话 2","en":"We're also wondering what tours and day trips are available.","cn":"我们还想知道有哪些旅游团和一日游可以参加。"},{"sp":"长对话 2","en":"W: We have bunches of brochures here.","cn":"W: 我们这里有很多宣传册。"},{"sp":"长对话 2","en":"I would recommend getting out on a boat trip.","cn":"我建议您去坐船游览。"},{"sp":"长对话 2","en":"The kids will love it and there are so many islands nearby to explore.","cn":"孩子们会喜欢的，附近有很多岛屿可以探索。"},{"sp":"长对话 2","en":"There's also a great night market further into town that has all kinds of food and cool little shops selling souvenirs and local jewelry and clothing made by hand.","cn":"镇里还有一个很棒的夜市，有各种各样的食物和很酷的小店，卖纪念品、当地的珠宝和手工制作的服装。"},{"sp":"长对话 2","en":"M: That all sounds marvelous.","cn":"M: 听起来都很棒。"},{"sp":"长对话 2","en":"W: Now, all I need is to photocopy your passports and then I can get you all checked in and show you to your rooms.","cn":"W: 现在，我只需要复印一下您的护照，然后就可以为您办理入住手续，带您去房间了。"},{"sp":"听力篇章 1","en":"Artificial intelligence agents play ever more influential roles in our lives.","cn":"人工智能代理在我们的生活中扮演着越来越有影响力的角色。"},{"sp":"听力篇章 1","en":"They do everything from suggesting new friends to recommending purchases.","cn":"它们做各种事情，从推荐新朋友到推荐购物。"},{"sp":"听力篇章 1","en":"They're even beginning to drive our cars.","cn":"它们甚至开始驾驶我们的汽车。"},{"sp":"听力篇章 1","en":"Another role that they are expected to take over is negotiating on our behalf in commercial transactions or legal disputes.","cn":"它们预计将接管的另一个角色是在商业交易或法律纠纷中代表我们进行谈判。"},{"sp":"听力篇章 1","en":"So, it's important to know whether using an artificial intelligence agent might affect how we negotiate.","cn":"因此，了解使用人工智能代理是否会影响我们的谈判方式很重要。"},{"sp":"听力篇章 1","en":"Research indicates that it does.","cn":"研究表明确实会。"},{"sp":"听力篇章 1","en":"In a new study, participants were told to imagine that they were negotiating for something important to them, like a house.","cn":"在一项新研究中，参与者被告知想象他们正在为对自己重要的东西进行谈判,比如一套房子。"},{"sp":"听力篇章 1","en":"Next they were told either that they would negotiate for themselves, or they would program an artificial intelligence agent to negotiate for them.","cn":"接下来他们被告知要么自己谈判,要么编程一个人工智能代理代表他们谈判。"},{"sp":"听力篇章 1","en":"Participants then completed a survey indicating how tough, deceptive and pleasant or otherwise they wanted to be, or wanted their agent to be, in the negotiations.","cn":"然后参与者完成了一项调查,表明他们希望在谈判中表现得多么强硬、多么具有欺骗性和多么令人愉快,或者希望他们的代理表现得如何。"},{"sp":"听力篇章 1","en":"For example, participants could choose to be tough by making an opening demand far greater than what they'd be willing to accept.","cn":"例如,参与者可以选择通过提出远高于他们愿意接受的开价来表现强硬。"},{"sp":"听力篇章 1","en":"They could also choose to express sympathy with their opponent to appear pleasant.","cn":"他们也可以选择对对手表示同情以显得令人愉快。"},{"sp":"听力篇章 1","en":"But they could also indicate that they—or their agent—would strategically express anger toward the opponent to gain advantage, or they could opt to convey dissatisfaction with the encounter so that the other party would think they were losing interest.","cn":"但他们也可以表示他们或他们的代理会策略性地向对手表达愤怒以获得优势,或者他们可以选择表达对这次接触的不满,这样对方就会认为他们正在失去兴趣。"},{"sp":"听力篇章 1","en":"These are both examples of deceptive strategies.","cn":"这些都是欺骗性策略的例子。"},{"sp":"听力篇章 1","en":"Participants were more willing to employ deceptive strategies when assigned an agent to negotiate on their behalf.","cn":"当被分配一个代理代表他们进行谈判时,参与者更愿意使用欺骗性策略。"},{"sp":"听力篇章 2","en":"New research has studied the effects of a seven-week healthy cooking course.","cn":"新研究考察了为期七周的健康烹饪课程的效果。"},{"sp":"听力篇章 2","en":"Academics measured the program's effect on cooking confidence and self-perceived mental health.","cn":"学者们测量了该项目对烹饪信心和自我感知心理健康的影响。"},{"sp":"听力篇章 2","en":"Researchers also measured participants' overall satisfaction around cooking and diet-related behaviors.","cn":"研究人员还测量了参与者对烹饪的总体满意度以及与饮食相关的行为。"},{"sp":"听力篇章 2","en":"What were the findings? Course participants saw significant improvements in general health. They also reported improved mental health and subjective vitality immediately after the program. These benefits remained six months after the completion of the course.","cn":"研究发现了什么?课程参与者的总体健康状况有了显著改善。他们还报告称,在项目结束后心理健康和主观活力立即得到改善。这些益处在课程完成六个月后仍然保持。"},{"sp":"听力篇章 2","en":"What caused these improvements? Researchers have previously found a link between eating more fruits and vegetables, and improved longer term mental health. This would imply that the participants in the current study may have felt better due to improved diet.","cn":"是什么导致了这些改善?研究人员此前发现,摄入更多水果和蔬菜与长期心理健康改善之间存在联系。这意味着当前研究中的参与者可能因饮食改善而感觉更好。"},{"sp":"听力篇章 2","en":"However, the study showed participants' mental health improved even if their reported diet did not change after completing the program.","cn":"然而,研究显示,即使参与者报告的饮食在完成项目后没有改变,他们的心理健康也有所改善。"},{"sp":"听力篇章 2","en":"Also, the mental health benefits were equal among participants who were overweight or obese and those in a healthy weight range.","cn":"此外,超重或肥胖参与者与体重正常参与者获得的心理健康益处相当。"},{"sp":"听力篇章 2","en":"This suggests a link between cooking confidence and satisfaction around cooking, and mental health benefits.","cn":"这表明烹饪信心和对烹饪的满意度与心理健康益处之间存在联系。"},{"sp":"听力篇章 2","en":"Who benefits most from learning to cook? Gender plays a part. At the start of the program, 77 per cent of female participants were confident about cooking, but just 23 per cent of males were confident. At the end of the program, cooking confidence and skills were equal across both counterparts. This change in confidence could lead to a gender balance in home cooking. This in turn could reduce consumption of unhealthy, high-calorie processed meals.","cn":"谁从学习烹饪中受益最多?性别起到一定作用。在项目开始时,77%的女性参与者对烹饪有信心,但只有23%的男性有信心。项目结束时,双方的烹饪信心和技能达到了平衡。这种信心的变化可能导致家庭烹饪中的性别平衡。这反过来又可以减少不健康、高热量加工食品的消费。"},{"sp":"听力篇章 3","en":"What is personal space?","cn":"什么是个人空间？"},{"sp":"听力篇章 3","en":"We often think of it as an invisible bubble of space surrounding us that others can't enter, without causing discomfort.","cn":"我们常常认为它是环绕我们周围的一个无形气泡，他人不能进入，否则会引起不适。"},{"sp":"听力篇章 3","en":"Research shows, however, that we actually have bubbles of different sizes.","cn":"然而，研究表明，我们实际上拥有不同大小的气泡。"},{"sp":"听力篇章 3","en":"Each of these bubbles applies to a different set of people.","cn":"这些气泡中的每一个都适用于不同的人群。"},{"sp":"听力篇章 3","en":"The smallest zone, called \"intimate space\", extends outward from our bodies 18 inches in every direction.","cn":"最小的区域称为\"亲密空间\",从我们身体向外延伸18英寸的各个方向。"},{"sp":"听力篇章 3","en":"Only family, pets and one's closest friends may enter it.","cn":"只有家人、宠物和最亲密的朋友可以进入。"},{"sp":"听力篇章 3","en":"A mere acquaintance entering our intimate space makes us uncomfortable.","cn":"仅仅是熟人进入我们的亲密空间就会让我们感到不舒服。"},{"sp":"听力篇章 3","en":"Next is the bubble called \"personal space\", extending from 1.5 feet to 4 feet away.","cn":"接下来是称为\"个人空间\"的气泡,从1.5英尺延伸到4英尺之外。"},{"sp":"听力篇章 3","en":"Friends and acquaintances can comfortably occupy this zone, especially during informal conversations, but strangers are forbidden.","cn":"朋友和熟人可以舒适地占据这个区域,尤其是在非正式交谈期间,但陌生人是被禁止的。"},{"sp":"听力篇章 3","en":"Extending from 4 to 12 feet away from us is \"social space\".","cn":"从我们4到12英尺之外延伸的是\"社交空间\"。"},{"sp":"听力篇章 3","en":"Here people feel comfortable conducting routine social interactions with new acquaintances or total strangers.","cn":"在这里,人们可以舒适地与新认识的人或完全陌生的人进行日常社交互动。"},{"sp":"听力篇章 3","en":"Those are the average sizes of American's personal bubbles, anyway.","cn":"无论如何,这些是美国人个人气泡的平均大小。"},{"sp":"听力篇章 3","en":"It is important to keep in mind that personal space varies depending on culture and context.","cn":"重要的是要记住,个人空间因文化和环境而异。"},{"sp":"听力篇章 3","en":"Furthermore, there are significant individual differences.","cn":"此外,还存在显著的个体差异。"},{"sp":"听力篇章 3","en":"As we all know, cultural or individual differences in personal bubble diameters are all too often the cause of discomfort.","cn":"众所周知,个人气泡直径的文化或个体差异往往是造成不适的原因。"},{"sp":"听力篇章 3","en":"How did these personal bubbles arise?","cn":"这些个人气泡是如何产生的？"},{"sp":"听力篇章 3","en":"According to research, we begin to develop our individual sense of personal space around age 3 or 4.","cn":"根据研究,我们在3岁或4岁左右开始发展我们个人的个人空间意识。"},{"sp":"听力篇章 3","en":"The sizes of our bubbles are fixed by our teens.","cn":"我们气泡的大小在青少年时期就固定下来了。"},{"sp":"听力篇章 3","en":"These bubbles are constructed and monitored by the brain region involved in fear.","cn":"这些气泡是由与恐惧有关的大脑区域构建和监控的。"}]},{"id":"cet6-2023-03-1","level":"CET6","exam":"2023_03_1","year":2023,"month":3,"set":1,"type":"整卷听力","title":"2023年3月 六级第1套 · 听力真题","source":"2023年3月 CET-6 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet6-2023-03-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"M: Thanks for inviting me out tonight.","cn":"M：谢谢你今晚邀请我出来。"},{"sp":"长对话 1","en":"I've been wanting to try this place for weeks.","cn":"我一直想来这家店试试，已经好几个星期了。"},{"sp":"长对话 1","en":"I usually pass it on my way home from work but never seem to have time to stop.","cn":"我通常下班回家的路上会经过这里，但似乎总是没时间停下来。"},{"sp":"长对话 1","en":"W: I've been dying to come here as well.","cn":"W：我也一直特别想来这里。"},{"sp":"长对话 1","en":"I was worried that the menu might not be accommodating.","cn":"我当时还担心菜单可能不太适合不同的饮食需求。"},{"sp":"长对话 1","en":"But one of my close friends ate here last week.","cn":"不过，我有一位好朋友上周来这里吃过饭。"},{"sp":"长对话 1","en":"She's a vegetarian.","cn":"她是素食者。"},{"sp":"长对话 1","en":"She told me that there were a lot of options for her, and they offered alternative dishes.","cn":"她告诉我，这里有很多适合她的选择，而且他们还会提供替代菜品。"},{"sp":"长对话 1","en":"M: But you're not vegetarian, are you?","cn":"M：不过你不是素食者，对吧？"},{"sp":"长对话 1","en":"W: Well, not entirely.","cn":"W：嗯，也不完全是。"},{"sp":"长对话 1","en":"I don't eat meat at all, but I don't have a problem eating fish, seafood or eggs.","cn":"我一点肉都不吃，但鱼、海鲜和鸡蛋我都可以吃。"},{"sp":"长对话 1","en":"M: Isn't that very difficult?","cn":"M：这不是很难吗？"},{"sp":"长对话 1","en":"I can't imagine giving up a premium juicy steak or bacon cheeseburgers.","cn":"我无法想象放弃上等的多汁牛排或培根芝士汉堡。"},{"sp":"长对话 1","en":"W: I wouldn't know.","cn":"W：我也不知道。"},{"sp":"长对话 1","en":"My parents followed the same diet.","cn":"我父母遵循的也是同样的饮食习惯。"},{"sp":"长对话 1","en":"Even when I was younger, we never had meat during meals, and I never really had a craving to try it.","cn":"甚至在我小的时候，我们吃饭时也从来不吃肉，而我也从来没有特别想尝试。"},{"sp":"长对话 1","en":"I bet it would be hard though, giving up something you're accustomed to eating.","cn":"话说回来，放弃一种你已经习惯吃的东西，肯定会很难。"},{"sp":"长对话 1","en":"I tried cutting back on coffee in the morning, and it was awful.","cn":"我试过早上少喝咖啡，感觉糟透了。"},{"sp":"长对话 1","en":"Come to think of it, it was probably even worse for my colleagues that had to deal with me at morning meetings.","cn":"现在想想，那段时间可能对我的同事来说更糟，因为他们得在早会上应付我。"},{"sp":"长对话 1","en":"M: That's even harder to imagine you, without coffee.","cn":"M：我更难想象没有咖啡的你。"},{"sp":"长对话 1","en":"So you say your parents also followed a partially vegetarian diet?","cn":"你是说你父母也遵循半素食饮食？"},{"sp":"长对话 1","en":"Why did they decide to do that?","cn":"他们为什么决定这样做？"},{"sp":"长对话 1","en":"W: That's an interesting question.","cn":"W：这是个有意思的问题。"},{"sp":"长对话 1","en":"I never thought to ask them though.","cn":"不过我从来没想过要问他们。"},{"sp":"长对话 1","en":"My best guess is for health reasons.","cn":"我的最大猜测是出于健康原因。"},{"sp":"长对话 1","en":"They're not terribly active or knowledgeable about animal preservation efforts, but they're serious about their health.","cn":"他们并不是特别活跃，也不太了解动物保护方面的工作，但他们非常重视自己的健康。"},{"sp":"长对话 1","en":"Both are in their 70s now, but eat organic as often as possible and take part in regular physical exercise.","cn":"他们现在都七十多岁了，却尽可能经常吃有机食品，还定期参加体育锻炼。"},{"sp":"长对话 1","en":"Neither of them has any health problems, and they hardly ever get sick.","cn":"他们俩都没有任何健康问题，而且几乎从来不会生病。"},{"sp":"长对话 1","en":"M: In that case, I might give it a try someday.","cn":"M：这样的话，也许哪天我会试试看。"},{"sp":"长对话 1","en":"W: Now back to the menu.","cn":"W：现在回到菜单上来。"},{"sp":"长对话 1","en":"What are you going to have?","cn":"你打算吃什么？"},{"sp":"长对话 2","en":"W: How did your annual performance evaluation meeting with your manager go?","cn":"W: 你和经理的年度绩效评估会议进行得怎么样？"},{"sp":"长对话 2","en":"Did you get much in the way of praise?","cn":"他有没有怎么表扬你？"},{"sp":"长对话 2","en":"M: Next to zero.","cn":"M: 几乎没有。"},{"sp":"长对话 2","en":"When we came to the part about discussing my areas for growth, he bluntly told me that I had an attitude problem.","cn":"谈到讨论我需要改进的方面时，他直截了当地告诉我，我的态度有问题。"},{"sp":"长对话 2","en":"But he wouldn't really expand on that description.","cn":"但他并没有进一步解释这个说法。"},{"sp":"长对话 2","en":"He said it's the little things I do and say.","cn":"他说，是我做的一些小事和说的一些话造成的。"},{"sp":"长对话 2","en":"W: Did you ask him for a specific example?","cn":"W: 你有没有让他举个具体的例子？"},{"sp":"长对话 2","en":"M: I did ask him a few more questions to try and narrow it down.","cn":"M: 我确实又问了几个问题，想把范围缩小一些。"},{"sp":"长对话 2","en":"He said my constant questioning of him and his decisions was the most obvious example he could give.","cn":"他说，我不断质疑他和他的决定，就是他能举出的最明显的例子。"},{"sp":"长对话 2","en":"Then our conversation was swiftly brought to a close.","cn":"然后我们的谈话很快就结束了。"},{"sp":"长对话 2","en":"W: I had a similar experience once.","cn":"W: 我以前也有过类似的经历。"},{"sp":"长对话 2","en":"My manager told me I was too honest.","cn":"我的经理说我太诚实了。"},{"sp":"长对话 2","en":"In most cases, I thought my honesty was helpful, as did my colleagues, but my manager thought otherwise.","cn":"大多数情况下，我觉得我的诚实是有帮助的，我的同事也这么认为，但我的经理却不这么想。"},{"sp":"长对话 2","en":"Some managers really adopt manipulative language to disguise the unreasonable choices they have made.","cn":"有些经理确实会采用操纵性的语言，来掩饰他们做出的不合理选择。"},{"sp":"长对话 2","en":"They don't use the rational power of arguments to resolve issues of conflict or complaints about unfairness.","cn":"他们不会运用论证的理性力量，来解决冲突问题或人们对不公平的抱怨。"},{"sp":"长对话 2","en":"M: Right.","cn":"M: 没错。"},{"sp":"长对话 2","en":"Some employ their persuasive vocabulary and influential communication style to win workplace arguments by compelling people to perform the intended action.","cn":"有些人会运用有说服力的词汇和具有影响力的沟通方式，通过迫使人们采取预期的行动来赢得职场争论。"},{"sp":"长对话 2","en":"W: Exactly.","cn":"W: 正是。"},{"sp":"长对话 2","en":"Too honest?","cn":"太诚实了？"},{"sp":"长对话 2","en":"Isn't that a good thing?","cn":"这难道不是一件好事吗？"},{"sp":"长对话 2","en":"I thought that's surely something we should have covered earlier in the section discussing strengths and talents, but no.","cn":"我本以为这肯定是我们早些时候在讨论优势和才能的部分应该涉及的内容，但事实并非如此。"},{"sp":"长对话 2","en":"Honesty was deemed to be more of a sin than a virtue, since it made people feel uncomfortable, or at least it made the most powerful folks feel uncomfortable.","cn":"诚实被认为更像是一种罪过，而不是一种美德，因为它让人感到不自在，或者至少让那些最有权势的人感到不自在。"},{"sp":"长对话 2","en":"M: Indeed.","cn":"M: 的确如此。"},{"sp":"长对话 2","en":"Rhetoric is viewed by many philosophers as the method through which the powerful accumulate more power.","cn":"许多哲学家认为，修辞是有权势者积累更多权力的手段。"},{"sp":"长对话 2","en":"By virtue of having the loudest voice, they're able to command greater attention and to further assert their dominance, even when what they're saying doesn't really make much sense.","cn":"凭借最大的声音，他们能够获得更多关注，并进一步巩固自己的支配地位，即使他们所说的话其实没什么道理。"},{"sp":"长对话 2","en":"W: And retaining their power and prestige is their priority.","cn":"W: 而保住他们的权力和声望才是他们的首要任务。"},{"sp":"长对话 2","en":"M: It's what makes the most sense to a lot of them.","cn":"M: 对很多人来说，这才是最合理的做法。"},{"sp":"听力篇章 1","en":"Athletes are seen as heroes because they can do things that most of us can't do.","cn":"运动员被视为英雄，是因为他们能做到我们大多数人做不到的事情。"},{"sp":"听力篇章 1","en":"They can hit fastballs coming at them at nearly 100 miles an hour, and leap and hang in the air, seemingly defying gravity.","cn":"他们能击中以接近每小时100英里的速度飞向他们的快速球，还能跃起并悬停在空中，似乎在对抗重力。"},{"sp":"听力篇章 1","en":"They get paid millions of dollars for their efforts, and their names and faces appear on everything from running shoes to advertising boards.","cn":"他们因自己的努力而获得数百万美元的报酬，他们的名字和面孔出现在从跑鞋到广告牌的各种物品上。"},{"sp":"听力篇章 1","en":"Athletes who are champions also show qualities such as perseverance, dedication, and the ability to keep their cool under pressure.","cn":"成为冠军的运动员还展现出诸如毅力、奉献以及在压力下保持冷静的能力等品质。"},{"sp":"听力篇章 1","en":"Many show those same qualities off the playing field, too.","cn":"许多人在赛场之外也展现出相同的品质。"},{"sp":"听力篇章 1","en":"Stories about superstar athletes teach us about working hard and believing in ourselves and then being passionate about what we do.","cn":"关于超级巨星运动员的故事教导我们要努力拼搏、相信自己，并对自己所做的事情充满热情。"},{"sp":"听力篇章 1","en":"Although it's usually bad behavior that gets an athlete a spot on the six o'clock news, many high-profile players work hard to be positive role models to children.","cn":"尽管通常是不良行为让运动员登上六点钟新闻，但许多备受关注的球员仍努力成为孩子们积极的榜样。"},{"sp":"听力篇章 1","en":"They raise money for charities and act as mentors, talking to student groups and volunteering their time to programs that help children keep off drugs and stay in school.","cn":"他们为慈善机构筹集资金并担任导师，与学生群体交流，并志愿为帮助儿童远离毒品和留在学校的项目奉献时间。"},{"sp":"听力篇章 1","en":"Still, even the greatest champions have flaws. Just because an athlete has the perfect golf swing doesn't mean he is the perfect parent, friend or spokesperson. They also make mistakes. Separating an athlete's professional and personal lives can be tough. When a sports star gets in trouble with the law, or does something wrong in their private life, fans are often left disappointed. Before he died, baseball star Mickey Mantle, who was plagued with alcohol problems, told young ballplayers and the fans who admired him \"to play like me, don't be like me.\"","cn":"尽管如此，即使是最伟大的冠军也有缺陷。不能仅凭一名运动员拥有完美的高尔夫挥杆动作，就意味着他是完美的父母、朋友或代言人。他们也会犯错。将运动员的职业生活与个人生活区分开来可能会很困难。当体育明星触犯法律，或在私生活中做错事时，粉丝往往会感到失望。棒球巨星米奇·曼特尔生前饱受酗酒问题困扰，他在去世前曾对年轻球员和崇拜他的球迷说：“像我一样打球，不要像我一样做人。”"},{"sp":"听力篇章 2","en":"We don't need to tell you that weddings can get expensive.","cn":"我们无需告诉你，婚礼可能会变得非常昂贵。"},{"sp":"听力篇章 2","en":"Even with the most meticulous budgeting, a few unexpected costs are bound to occur.","cn":"即使预算安排得最为周密，也必然会出现一些意料之外的开支。"},{"sp":"听力篇章 2","en":"While most brides tend to accept this as fact, one Canadian woman, who is only known as Susan, attempted to avoid all wedding costs.","cn":"大多数新娘往往会接受这一事实，但一名仅以 Susan 为人所知的加拿大女子却试图避开所有婚礼费用。"},{"sp":"听力篇章 2","en":"She did this by asking her friends and family to pay up to attend her wedding.","cn":"她要求亲朋好友付费参加自己的婚礼。"},{"sp":"听力篇章 2","en":"It went about as well as you'd expect.","cn":"结果正如你所料，事情进展得相当不顺利。"},{"sp":"听力篇章 2","en":"Susan is causing quite the debate online after posting a bizarre Facebook complaint about her now-cancelled wedding.","cn":"Susan 在 Facebook 上发布了一篇抱怨她那场如今已经取消的婚礼的奇怪帖子后，在网上引发了激烈争论。"},{"sp":"听力篇章 2","en":"Yes, the couple called off the wedding just days before their wedding vows.","cn":"没错，这对情侣在交换结婚誓言前几天取消了婚礼。"},{"sp":"听力篇章 2","en":"Since their guests refused to pay the $1,500 attendance fee, the $60,000 dream wedding was put on permanent hold.","cn":"由于宾客拒绝支付 1,500 美元的参加费用，这场价值 60,000 美元的梦幻婚礼被无限期搁置。"},{"sp":"听力篇章 2","en":"In her long explanation filled with cursing and swearing, the bride accused her friends and family of ruining her marriage and her life.","cn":"在那篇充斥着咒骂和脏话的长篇解释中，新娘指责亲朋好友毁掉了她的婚姻和人生。"},{"sp":"听力篇章 2","en":"She stated that each guest would only need to pay $1,500 while she sacrificed everything for the day.","cn":"她表示，每位宾客只需支付 1,500 美元，而她为了这一天牺牲了一切。"},{"sp":"听力篇章 2","en":"Her maid of honor told her to stick to the budget, as she was asking too much from her guests.","cn":"她的伴娘告诉她要遵守预算，因为她向宾客索要的费用太高了。"},{"sp":"听力篇章 2","en":"But Susan ignored her.","cn":"但 Susan 没有理会她。"},{"sp":"听力篇章 2","en":"Not surprisingly, only eight people responded positively to the wedding invitations and money requests.","cn":"毫不意外，只有八个人对婚礼邀请和付款请求作出了积极回应。"},{"sp":"听力篇章 2","en":"Realizing they would not be able to afford their dream wedding, Susan's future husband suggested getting married in Las Vegas.","cn":"意识到他们将无法负担梦幻婚礼后，Susan 的未婚夫建议去拉斯维加斯结婚。"},{"sp":"听力篇章 2","en":"The bride quickly shut down the idea, saying she did not want a wedding of gambling and heavy drinking.","cn":"新娘很快否决了这个想法，称她不想要一场充斥着赌博和酗酒的婚礼。"},{"sp":"听力篇章 2","en":"It seems her dream wedding has now become a nightmare.","cn":"看来，她的梦幻婚礼如今已经变成了一场噩梦。"},{"sp":"讲座 1","en":"It has long been scientifically established that weather changes can affect people's moods.","cn":"天气变化会影响人的情绪，这一点早已得到科学证实。"},{"sp":"讲座 1","en":"Now, a new study has provided evidence that temperature can influence people's personalities.","cn":"如今，一项新的研究提供了温度能够影响人们性格的证据。"},{"sp":"讲座 1","en":"This study of over 1.6 million people revealed that 22 degrees Celsius is the perfect air temperature to live in.","cn":"这项针对超过160万人的研究显示，22摄氏度是最适合居住的空气温度。"},{"sp":"讲座 1","en":"A city with an average annual temperature closer to 22 tends to have a population who are more agreeable, conscientious, emotionally stable, and outgoing.","cn":"年平均气温更接近22摄氏度的城市，其居民往往更加随和、尽责、情绪稳定且外向。"},{"sp":"讲座 1","en":"It is the least taxing temperature for the body to regulate its own temperature.","cn":"这是人体调节自身温度时负担最小的温度。"},{"sp":"讲座 1","en":"The study was observational and didn't show cause and effect, but the scientists behind it theorized that better weather leads people to leave their home more often.","cn":"这项研究属于观察性研究，并未证明因果关系，但研究背后的科学家推测，更宜人的天气会使人们更频繁地外出。"},{"sp":"讲座 1","en":"This, in turn, leads to more social interaction, which encourages them to develop a friendlier and socially more acceptable personality.","cn":"这样一来，人们会有更多的社交互动，从而促使他们形成更加友善、在社交方面更容易被接受的性格。"},{"sp":"讲座 1","en":"Warmer climates also make people feel more positive in general.","cn":"较温暖的气候通常也会让人们更加积极乐观。"},{"sp":"讲座 1","en":"They tend to be more agreeable and conscientious.","cn":"他们往往更加随和、尽责。"},{"sp":"讲座 1","en":"The findings might help explain why colder and warmer countries tend to produce people with different personalities.","cn":"这些发现或许有助于解释为什么较寒冷和较温暖的国家往往会孕育出性格不同的人。"},{"sp":"讲座 1","en":"Roughly speaking, about 40% of a person's personality is determined by their genes, the other 60% by their environment.","cn":"大致来说，一个人的性格约有40%由基因决定，另外60%由环境决定。"},{"sp":"讲座 1","en":"It was already well-known that personality traits vary across geographic regions.","cn":"众所周知，性格特征在不同地理区域之间存在差异。"},{"sp":"讲座 1","en":"Scientists also knew that these geographic personality traits are associated with a broad range of consequential outcomes.","cn":"科学家们还知道，这些与地理区域相关的性格特征与广泛的重要结果有关。"},{"sp":"讲座 1","en":"These outcomes include economic activity, for example, entrepreneurial start-up rates, and also crime rates, health behaviors, and health outcomes.","cn":"这些结果包括经济活动，例如创业企业的初创率，也包括犯罪率、健康行为和健康状况。"},{"sp":"讲座 1","en":"And it is well established that personality traits differ between countries.","cn":"此外，不同国家之间的性格特征存在差异，这一点也已得到充分证实。"},{"sp":"讲座 1","en":"The research team speculated the two might be linked.","cn":"研究团队推测，这两者可能存在联系。"},{"sp":"讲座 1","en":"To test this, they gave online personality tests to 5,587 Chinese students and 1.66 million Americans.","cn":"为了检验这一点，他们对5587名中国学生和166万名美国人进行了在线性格测试。"},{"sp":"讲座 1","en":"They then compared the results with the average annual temperature where they grew up.","cn":"随后，他们将测试结果与这些人长大所在地的年平均气温进行了比较。"},{"sp":"讲座 1","en":"The tests measured personality along five well-studied characteristics.","cn":"这些测试依据五项经过充分研究的特征来衡量性格。"},{"sp":"讲座 1","en":"The five were agreeability, conscientiousness, emotional stability, outgoingness, and openness to new experiences.","cn":"这五项特征分别是随和性、尽责性、情绪稳定性、外向性以及对新体验的开放性。"},{"sp":"讲座 1","en":"In both groups, the researchers found the closer a town's average annual temperature was to 22 degrees, the more its population exhibited those personality characteristics.","cn":"在两组人群中，研究人员都发现，一个城镇的年平均气温越接近22摄氏度，其居民越明显地表现出这些性格特征。"},{"sp":"讲座 1","en":"However, the findings were much stronger for the Chinese group than the Americans studied, which suggests that though temperature plays a role, it does not play a dominant role.","cn":"然而，这些发现对中国群体的解释力远强于对所研究的美国人的解释力，这表明尽管温度确实发挥作用，但并非起主导作用。"},{"sp":"讲座 1","en":"The effects are fairly weak.","cn":"其影响相当微弱。"},{"sp":"讲座 1","en":"It's unlikely to lead to many arguments over the temperature setting of the office air conditioner.","cn":"因此，温度设定不太可能引发许多关于办公室空调温度的争论。"},{"sp":"讲座 2","en":"Today, we are talking about loneliness.","cn":"今天，我们来谈谈孤独。"},{"sp":"讲座 2","en":"Loneliness and social isolation are growing public health concerns for people of all ages in the United States, from adolescence to the elderly.","cn":"对于美国各个年龄段的人来说，从青少年到老年人，孤独和社会隔离正日益成为令人担忧的公共卫生问题。"},{"sp":"讲座 2","en":"Public health experts are worried because loneliness seems to be on the rise, and studies have long found correlations between loneliness and an assortment of medical conditions that threaten health and longevity.","cn":"公共卫生专家对此感到担忧，是因为孤独似乎正在增加，而研究长期以来一直发现，孤独与一系列威胁健康和长寿的疾病之间存在相关性。"},{"sp":"讲座 2","en":"The problem of loneliness may be even greater than we thought.","cn":"孤独问题可能比我们想象的还要严重。"},{"sp":"讲座 2","en":"A new national poll found that about a third of older Americans are lonely, and almost as many seniors feel isolated.","cn":"一项新的全国性民意调查发现，大约三分之一的美国老年人感到孤独，几乎同样多的老年人感到与社会隔绝。"},{"sp":"讲座 2","en":"This is a serious problem as research shows that chronic loneliness is particularly harmful to senior citizens.","cn":"研究表明，长期孤独对老年人尤其有害，因此这是一个严重的问题。"},{"sp":"讲座 2","en":"That's because it can impair older adults' memory and damage their physical and mental health.","cn":"这是因为孤独会损害老年人的记忆，并危害他们的身体和心理健康。"},{"sp":"讲座 2","en":"Chronic loneliness even impacts the life expectancy of seniors, increasing their risk of early mortality.","cn":"长期孤独甚至会影响老年人的预期寿命，增加他们过早死亡的风险。"},{"sp":"讲座 2","en":"Let's take a closer look at that poll now.","cn":"现在，让我们进一步了解这项民意调查。"},{"sp":"讲座 2","en":"More than a third of seniors in the poll said they felt lonely at least some of the time, and 27% said they sometimes or often felt isolated.","cn":"调查中超过三分之一的老年人表示，他们至少有一部分时间感到孤独，27%的人表示自己有时或经常感到与社会隔绝。"},{"sp":"讲座 2","en":"This reflects how much time the seniors spent with others.","cn":"这反映了老年人与他人相处的时间。"},{"sp":"讲座 2","en":"Almost 30% said they socialized with friends, family or neighbors once a week or less.","cn":"近30%的人表示，他们每周与朋友、家人或邻居社交的次数不超过一次。"},{"sp":"讲座 2","en":"Women were more likely than men to report loneliness.","cn":"女性报告感到孤独的可能性高于男性。"},{"sp":"讲座 2","en":"But there is good news.","cn":"但也有好消息。"},{"sp":"讲座 2","en":"It looks like loneliness can be reversed.","cn":"看来孤独是可以得到改善的。"},{"sp":"讲座 2","en":"But researchers are still trying to determine the best way to do so.","cn":"不过，研究人员仍在努力确定最佳方法。"},{"sp":"讲座 2","en":"Why is that?","cn":"为什么会这样呢？"},{"sp":"讲座 2","en":"Resolving the problem of loneliness among seniors often isn't as simple as getting them together with others or moving them in with their children.","cn":"解决老年人的孤独问题，往往并不像让他们与他人聚在一起或让他们搬去和子女同住那么简单。"},{"sp":"讲座 2","en":"In fact, the poll found that seniors who lived with their children were more likely to report feeling lonely than those who didn't.","cn":"事实上，调查发现，与子女同住的老年人比不与子女同住的老年人更有可能报告自己感到孤独。"},{"sp":"讲座 2","en":"This may be because loneliness refers to the discrepancy between actual and desired relationships.","cn":"这可能是因为，孤独指的是实际关系与期望关系之间的差距。"},{"sp":"讲座 2","en":"So it's possible that someone who lives alone doesn't meet that definition, while someone in a house full of busy people does.","cn":"因此，一个独居的人可能不符合这一定义，而一个住在满是忙碌人群的房子里的人却可能符合。"},{"sp":"讲座 2","en":"How can we solve the problem?","cn":"我们该如何解决这个问题呢？"},{"sp":"讲座 2","en":"Well, the researchers assert that it's important to address each person's underlying cause of loneliness, whether it's the death of a spouse, medical problems, or social expectations that haven't been fulfilled.","cn":"研究人员认为，重要的是要解决每个人孤独感背后的根本原因，无论是配偶去世、健康问题，还是未能满足的社会期望。"},{"sp":"讲座 2","en":"It's noteworthy that there is one general recommendation.","cn":"值得注意的是，有一条普遍建议。"},{"sp":"讲座 2","en":"While finding solutions for loneliness is highly personal, research suggests the best interventions are those that involve meaningful social contact at least once a week.","cn":"虽然寻找孤独问题的解决方案高度因人而异，但研究表明，最佳干预措施是至少每周进行一次有意义的社会接触。"},{"sp":"讲座 2","en":"Depending on the person, that could mean volunteering, seeing an old friend or something else.","cn":"根据个人情况，这可能意味着参加志愿活动、去见一位老朋友，或者采取其他方式。"},{"sp":"讲座 3","en":"Hello, I'm co-founder of the popular female travel community We Are Travel Girls. We collect and publish stories from women traveling all over the world. We promote women's blogs; we host meetings and events and are getting ready to launch our Travel With Us trips in Bali, Japan and Malawi.","cn":"你好，我是广受欢迎的女性旅行社区 We Are Travel Girls 的联合创始人。我们收集并发表世界各地女性旅行者的故事，推广女性博客，举办聚会和活动，并正准备推出在巴厘岛、日本和马拉维的“与我们一起旅行”旅程。"},{"sp":"讲座 3","en":"Before I started We Are Travel Girls, I had a successful 10-year career in finance in London, where I advised private clients on their investments.","cn":"在创办 We Are Travel Girls 之前，我在伦敦的金融行业拥有一份成功的十年职业生涯，为私人客户提供投资方面的建议。"},{"sp":"讲座 3","en":"Having always had a huge love for travel, I finally took the leap and left finance to pursue my dream of starting a travel company.","cn":"我一直非常热爱旅行，最终毅然离开金融行业，追寻创办一家旅行公司的梦想。"},{"sp":"讲座 3","en":"For as long as I can remember, I wanted to be a travel writer.","cn":"从我记事起，我就想成为一名旅行作家。"},{"sp":"讲座 3","en":"Before blogs existed and everything we read was online, I would go to travel writing seminars by writers who were published in travel magazines.","cn":"在博客尚未出现、我们阅读的所有内容都还是在线下的时候，我会参加由那些在旅行杂志上发表过作品的作家举办的旅行写作研讨会。"},{"sp":"讲座 3","en":"I was desperate to write for one of those magazines, but didn't know how to break into that industry.","cn":"我非常渴望为其中一本杂志撰稿，却不知道该如何进入那个行业。"},{"sp":"讲座 3","en":"After university, I ended up working in finance, but always had a desire to travel and write about it.","cn":"大学毕业后，我最终进入了金融行业工作，但始终渴望去旅行并写下旅行见闻。"},{"sp":"讲座 3","en":"In 2015, I was looking at ways to leave finance, and my best friend Vanessa, who grew up on a ranch on the Central Coast of California, suggested starting a blog.","cn":"2015年，我正在寻找离开金融行业的方法，我最好的朋友 Vanessa 从小在加利福尼亚州中部海岸的一座牧场长大，她建议我们创办一个博客。"},{"sp":"讲座 3","en":"But when we started creating it, we realized that was the same thing every girl was doing.","cn":"但当我们开始创建博客时，我们意识到，这正是每个女孩都在做的事情。"},{"sp":"讲座 3","en":"So we turned our attention to creating a community among these women.","cn":"于是，我们把注意力转向在这些女性之间建立一个社区。"},{"sp":"讲座 3","en":"This led us to start We Are Travel Girls, which has now grown into a community of over 200,000 followers.","cn":"这促使我们创办了 We Are Travel Girls，如今它已经发展成为一个拥有超过20万名关注者的社区。"},{"sp":"讲座 3","en":"To anyone thinking about becoming a travel writer, I would suggest they first try and look for a unique way to enter the industry.","cn":"对于任何考虑成为旅行作家的人，我建议他们首先尝试寻找一种独特的方式进入这个行业。"},{"sp":"讲座 3","en":"There are a lot of travel writers now and it can be hard to stand out from the crowd, which is really why we started We Are Travel Girls.","cn":"如今旅行作家很多，要在人群中脱颖而出可能很难，这正是我们创办 We Are Travel Girls 的原因。"},{"sp":"讲座 3","en":"Be prepared to work hard if you want to turn it into a full-time business, and try not to rush to selling advertising spaces before you have created a dedicated audience.","cn":"若想把它发展成一项全职事业，就要做好努力工作的准备，并且在建立起一批忠实的受众之前，不要急于出售广告位。"},{"sp":"讲座 3","en":"The size of your audience doesn't necessarily need to be huge, but you want them to be engaged.","cn":"你的受众规模不一定要非常庞大，但你希望他们积极参与。"},{"sp":"讲座 3","en":"If you post too many promotions early on, you will turn many people off.","cn":"如果一开始就发布太多推广内容，会让许多人失去兴趣。"}]},{"id":"cet6-2023-06-2","level":"CET6","exam":"2023_06_2","year":2023,"month":6,"set":2,"type":"整卷听力","title":"2023年6月 六级第2套 · 听力真题","source":"2023年6月 CET-6 第2套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet6-2023-06-set2.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"M: Have you decided what you wish to study?","cn":"M: 你决定想学什么了吗？"},{"sp":"长对话 1","en":"W: Yes, professor.","cn":"W: 是的，教授。"},{"sp":"长对话 1","en":"I wish to study architecture.","cn":"我想学习建筑学。"},{"sp":"长对话 1","en":"M: Ah, that's a wonderful profession.","cn":"M: 啊，那是一门很棒的职业。"},{"sp":"长对话 1","en":"Why did you choose it?","cn":"你为什么选择它？"},{"sp":"长对话 1","en":"W: I gave a lot of thought to things you said during our last discussion, and I decided architecture made the most sense for me.","cn":"W: 我认真思考了您在上次讨论中说的话，最后决定建筑学对我来说最合适。"},{"sp":"长对话 1","en":"In particular, I'm attracted to the marriage of design and engineering.","cn":"尤其是，我很喜欢设计与工程的结合。"},{"sp":"长对话 1","en":"M: That's great, but I seem to remember you were preoccupied with all the lofty mathematics.","cn":"M: 这很好，不过我记得你之前一直在担心那些高深的数学。"},{"sp":"长对话 1","en":"You no longer think this aspect will be too hard for you?","cn":"你现在不再觉得这方面对你来说太难了吗？"},{"sp":"长对话 1","en":"W: No. I was doing some online research and I think I should be able to manage. Math might be the toughest subject I encounter in the curriculum, but I'll simply put in the work required. I'm certain the fruits of my labor will pay off.","cn":"W: 不会。我做了一些网上调查，我觉得自己应该能够应付。数学可能是我在课程中遇到的最难的科目，但我会投入所需的努力。我相信我的劳动成果一定会得到回报。"},{"sp":"长对话 1","en":"M: I'm sure that's true.","cn":"M: 我相信确实如此。"},{"sp":"长对话 1","en":"Due to its material nature, architecture is one field where you will be able to clearly witness the contribution you make to a city.","cn":"由于建筑具有实体性，在这个领域，你将能够清楚地看到自己为一座城市所作出的贡献。"},{"sp":"长对话 1","en":"And the legacies you build will last much longer than any of us mortals.","cn":"而且你所建造的遗产将比我们这些凡人中的任何一个存在得都久远。"},{"sp":"长对话 1","en":"W: Yeah, I guess that's true too.","cn":"W: 嗯，我想这也是真的。"},{"sp":"长对话 1","en":"So what subjects do you think I should start brushing up on in preparation?","cn":"那么，为了做准备，您觉得我应该先复习哪些科目？"},{"sp":"长对话 1","en":"I have the whole summer.","cn":"我整个夏天都有时间。"},{"sp":"长对话 1","en":"M: These days, architecture is a very diverse and dynamic degree.","cn":"M: 如今，建筑学是一门非常多样且充满活力的学位专业。"},{"sp":"长对话 1","en":"Most universities will encourage you to learn different things from fields as wide-ranging as philosophy and economics.","cn":"大多数大学都会鼓励你学习来自哲学、经济学等广泛领域的不同知识。"},{"sp":"长对话 1","en":"Nevertheless, I would suggest you start with computer science because there will be many intricate visuals you will have to produce as part of your projects.","cn":"不过，我建议你先从计算机科学开始，因为作为项目的一部分，你将需要制作许多复杂的视觉图像。"},{"sp":"长对话 1","en":"W: Any software in particular you think I should start with?","cn":"W: 您觉得我应该先从哪种软件开始，具体来说？"},{"sp":"长对话 1","en":"M: Photoshop is a good place.","cn":"M: Photoshop 是个不错的起点。"},{"sp":"长对话 1","en":"If you aren't yet, try to become as proficient as you can with it.","cn":"如果你还不熟悉它，就尽量熟练掌握。"},{"sp":"长对话 1","en":"And another thing that I would recommend you learn as much as you can is fine arts, in particular, the history of Western art.","cn":"另外，我建议你尽可能多学习的一项内容是美术，尤其是西方艺术史。"},{"sp":"长对话 2","en":"W: So as I mentioned over the phone, we are looking for someone who is very discreet, I can't stress this enough.","cn":"W: 正如我在电话里提到的，我们正在寻找一个非常谨慎低调的人，这一点再怎么强调都不为过。"},{"sp":"长对话 2","en":"M: I fully understand.","cn":"M: 我完全明白。"},{"sp":"长对话 2","en":"W: As we all know, being such a famous football player at Real Madrid, Mr. Sanchez has a very high public profile.","cn":"W: 众所周知，桑切斯先生是皇家马德里非常著名的足球运动员，公众关注度很高。"},{"sp":"长对话 2","en":"This means he cannot leave the house without being recognized and harassed.","cn":"这意味着他出门时不可能不被认出来，也不可能不受到骚扰。"},{"sp":"长对话 2","en":"M: Yes, I completely understand how imperative it would be to respect Mr. Sanchez's private life.","cn":"M: 是的，我完全明白尊重桑切斯先生的私人生活有多么重要。"},{"sp":"长对话 2","en":"W: Good.","cn":"W: 很好。"},{"sp":"长对话 2","en":"As his personal assistant, you would be required to run common everyday chores for Mr. Sanchez, things he cannot do himself due to his fame, like going to the supermarket or post office.","cn":"作为他的私人助理，你需要替桑切斯先生处理日常琐事，也就是那些由于他的名气而无法亲自去做的事情，比如去超市或邮局。"},{"sp":"长对话 2","en":"So, well, at first sight it may appear that working for a celebrity is very glamorous.","cn":"所以，乍一看，为名人工作似乎很光鲜。"},{"sp":"长对话 2","en":"Nothing could be further from the truth.","cn":"但事实远非如此。"},{"sp":"长对话 2","en":"I'm telling you this so that you don't get any false expectations of what the job has to offer you.","cn":"我告诉你这些，是为了让你不要对这份工作能给你带来什么抱有不切实际的期待。"},{"sp":"长对话 2","en":"M: Thanks.","cn":"M: 谢谢。"},{"sp":"长对话 2","en":"I understand this too.","cn":"我对此也很清楚。"},{"sp":"长对话 2","en":"This is my first job after graduating from university.","cn":"这是我大学毕业后的第一份工作。"},{"sp":"长对话 2","en":"So frankly, I don't have much prior working experience.","cn":"所以坦白说，我之前没有多少工作经验。"},{"sp":"长对话 2","en":"I am, however, very excited about the prospect of joining this company and very keen to start from the bottom in whatever capacity I may be of use.","cn":"不过，我非常期待有机会加入这家公司，也很愿意从基层做起，无论在哪个岗位上，只要我能发挥作用就行。"},{"sp":"长对话 2","en":"W: That's good to hear.","cn":"W: 听你这么说很好。"},{"sp":"长对话 2","en":"You sound very energetic.","cn":"你听起来精力很充沛。"},{"sp":"长对话 2","en":"Tell me why you think you are well suited for this job?","cn":"告诉我，你为什么认为自己适合这份工作？"},{"sp":"长对话 2","en":"M: Well, firstly, I love football.","cn":"M: 首先，我热爱足球。"},{"sp":"长对话 2","en":"I'm a lifelong Real Madrid supporter and go to their games every weekend I can.","cn":"我是皇家马德里的终身支持者，只要有可能，我每个周末都会去看他们的比赛。"},{"sp":"长对话 2","en":"I would simply love to have a job where I'm involved in some capacity with Real Madrid, regardless of the position and salary.","cn":"我非常希望能找一份以某种方式参与皇家马德里事务的工作，不管职位和薪水如何。"},{"sp":"长对话 2","en":"And secondly, I think what this company does in sports consultancy is very cool.","cn":"其次，我觉得这家公司在体育咨询方面所做的事情非常酷。"},{"sp":"长对话 2","en":"And I think my language skills could prove very useful down the road.","cn":"我还认为，我的语言能力将来可能会派上很大用场。"},{"sp":"长对话 2","en":"W: Please tell me more about your language skills.","cn":"W: 请详细说说你的语言能力。"},{"sp":"长对话 2","en":"M: I am fully fluent in English and Spanish and have a working proficiency in French.","cn":"M: 我的英语和西班牙语都非常流利，法语也达到了工作交流水平。"},{"sp":"听力篇章 1","en":"Adventure sports are undeniably attractive to many energetic and thrill-seeking kids.","cn":"冒险运动对许多精力充沛、寻求刺激的孩子来说无疑很有吸引力。"},{"sp":"听力篇章 1","en":"Sports like rock climbing, surfing, skiing, and mountain biking, thus have lots of appeal.","cn":"因此，攀岩、冲浪、滑雪和山地自行车等运动颇受欢迎。"},{"sp":"听力篇章 1","en":"They don't have many of the rules and pressures of traditional team sports, but they still have all the benefits of outdoor physical activity.","cn":"它们没有传统团队运动中那么多的规则和压力，但仍具备户外体育活动的全部益处。"},{"sp":"听力篇章 1","en":"When properly supervised, extreme sports can be a part of a healthy, balanced life.","cn":"在得到适当监管的情况下，极限运动可以成为健康、均衡生活的一部分。"},{"sp":"听力篇章 1","en":"Some adventure sports may be associated with high risks of injury, so it's important for kids to figure out when to take risks, and when not to.","cn":"有些冒险运动可能伴随着较高的受伤风险，因此，孩子们必须弄清楚什么时候应该冒险，什么时候不应该冒险。"},{"sp":"听力篇章 1","en":"Risk-free activities deprive kids of the opportunity to test themselves and overcome their fears.","cn":"没有任何风险的活动会剥夺孩子们挑战自我、克服恐惧的机会。"},{"sp":"听力篇章 1","en":"But to some, these very risks are what makes these sports a bad choice.","cn":"但在一些人看来，正是这些风险使这类运动成为糟糕的选择。"},{"sp":"听力篇章 1","en":"They say that extreme sports can often lead to devastating injuries, especially as young thrill-seekers may attempt feats that are too advanced for them.","cn":"他们认为，极限运动往往会导致严重的伤害，尤其是年轻的冒险者可能会尝试对他们来说难度过高的动作。"},{"sp":"听力篇章 1","en":"But let's be real.","cn":"但我们还是面对现实吧。"},{"sp":"听力篇章 1","en":"Most kids do all kinds of dangerous stuff whether you want them to or not.","cn":"不管你愿不愿意，大多数孩子都会做各种各样的危险事情。"},{"sp":"听力篇章 1","en":"Adventure sports have many of the same risks and dangers, but they have an additional sense of adventure, courage and autonomy that is important to foster in young children.","cn":"冒险运动也有许多相同的风险和危险，但它们还具有一种额外的冒险精神、勇气和自主意识，而这些品质对年幼的孩子来说很重要，需要加以培养。"},{"sp":"听力篇章 1","en":"As always, it's up to parents to decide what's best for their kids.","cn":"一如既往，父母应当决定什么对自己的孩子最好。"},{"sp":"听力篇章 1","en":"But if you do decide that adventure sports are a bit too much, do try to introduce other forms of outdoor adventures into their lives.","cn":"但如果你确实认为冒险运动有些过于激烈，那就应该努力将其他形式的户外探险引入孩子的生活。"},{"sp":"听力篇章 1","en":"Camping under the stars, fishing, stargazing or even just playing in the woods can help a lot in building the same sense of self-confidence and risk-taking as in adventure sports.","cn":"在星空下露营、钓鱼、观星，甚至只是在树林里玩耍，都能大大帮助孩子培养与冒险运动相同的自信心和冒险精神。"},{"sp":"听力篇章 2","en":"The shiny gadgets of today will be waste tomorrow.","cn":"今天光鲜亮丽的电子产品明天就会成为废品。"},{"sp":"听力篇章 2","en":"Manufacturers don't talk much about this when they announce the big new thing that will replace your mostly just as good old thing.","cn":"当制造商宣布要推出替代你那几乎同样好用的旧产品的新款重磅产品时，他们很少提及这一点。"},{"sp":"听力篇章 2","en":"In fact, technology firms often purposely design devices that will not last long and cannot be repaired so that consumers will have to spend their money on a new one.","cn":"事实上，科技公司往往故意设计使用寿命不长且无法维修的设备，以便消费者不得不花钱购买新设备。"},{"sp":"听力篇章 2","en":"This year, the French government began requiring tech manufacturers to list a repairability score.","cn":"今年，法国政府开始要求科技制造商标注可维修性评分。"},{"sp":"听力篇章 2","en":"If a device can be repaired, then its life can be extended, saving consumers money and the planet the burden of so many trashed gadgets.","cn":"如果一台设备可以维修，其使用寿命就能延长，从而为消费者节省资金，并减轻大量报废电子设备给地球带来的负担。"},{"sp":"听力篇章 2","en":"Equipped with this knowledge, consumers can make better choices about which products to buy.","cn":"掌握了这一信息，消费者在决定购买哪些产品时就能做出更好的选择。"},{"sp":"听力篇章 2","en":"Some 59 million tons of old TVs, computers, screens, smartphones, washers and other electronics are discarded every year.","cn":"每年约有5900万吨旧电视、电脑、显示屏、智能手机、洗衣机和其他电子产品被废弃。"},{"sp":"听力篇章 2","en":"This waste is dangerous.","cn":"这种废弃物是危险的。"},{"sp":"听力篇章 2","en":"Batteries explode in recycling facilities.","cn":"电池会在回收设施中发生爆炸。"},{"sp":"听力篇章 2","en":"Toxic substances like mercury leak into soil and groundwater and disperse in the air.","cn":"汞等有毒物质会渗入土壤和地下水，并散播到空气中。"},{"sp":"听力篇章 2","en":"Manufacturing flat screens adds greenhouse gases to the atmosphere.","cn":"制造平板显示屏会向大气中排放额外的温室气体。"},{"sp":"听力篇章 2","en":"We need tech companies to take the lead to solve this problem.","cn":"我们需要科技公司带头解决这个问题。"},{"sp":"听力篇章 2","en":"If they won't, governments must make them do so.","cn":"如果他们不愿意，政府就必须强制他们这样做。"},{"sp":"听力篇章 2","en":"Although tech companies will often speak of environmental sustainability, many lobby against repair legislation, fearful it will eat into their profits.","cn":"尽管科技公司经常谈论环境可持续性，但许多公司却游说反对维修立法，担心这会侵蚀它们的利润。"},{"sp":"听力篇章 2","en":"Sustainability matters, but marketable design appears to matter more to these companies.","cn":"可持续性固然重要，但对这些公司而言，具有市场吸引力的设计似乎更为重要。"},{"sp":"听力篇章 2","en":"Consumers should support right-to-repair legislation.","cn":"消费者应当支持“维修权”立法。"},{"sp":"听力篇章 2","en":"In this world, damage is a certainty.","cn":"在这个世界上，损坏是必然会发生的。"},{"sp":"听力篇章 2","en":"But we cannot leave things broken: A problem of our creation is a problem that can be fixed.","cn":"但我们不能任由东西坏着不管：我们制造出的问题是一个可以被解决的问题。"},{"sp":"讲座 1","en":"On average, US workers spend about 10% of their workday surfing the internet, emailing friends or shopping online.","cn":"平均而言，美国工人每天约有10%的工作时间用于浏览互联网、给朋友发电子邮件或在线购物。"},{"sp":"讲座 1","en":"This behavior, called cyberloafing, is believed to cost employers up to $85 billion a year in lost productivity.","cn":"这种被称为“网络闲逛”的行为，据认为每年会因生产力损失而使雇主损失高达850亿美元。"},{"sp":"讲座 1","en":"The majority of cyberloafing research focuses on ways to prevent employees from engaging in this behavior through interventions such as internet monitoring and computer use policies.","cn":"大多数关于网络闲逛的研究都集中于如何通过互联网监控和计算机使用政策等干预措施，防止员工从事这种行为。"},{"sp":"讲座 1","en":"But it turns out, such behaviors may not be a sign that a worker is lazy or just wasting time.","cn":"但事实证明，这类行为未必意味着员工懒惰或只是在浪费时间。"},{"sp":"讲座 1","en":"Social media use at work has been linked to higher levels of employee engagement and job satisfaction.","cn":"研究表明，在工作中使用社交媒体与更高水平的员工敬业度和工作满意度相关。"},{"sp":"讲座 1","en":"New research suggests cyberloafing can help workers cope with an exceptionally stressful work environment.","cn":"新的研究显示，网络闲逛可以帮助员工应对压力异常大的工作环境。"},{"sp":"讲座 1","en":"But is cyberloafing actually effective at reducing employee stress levels?","cn":"但网络闲逛是否真的能有效降低员工的压力水平？"},{"sp":"讲座 1","en":"That's the question my research team wanted to answer in our new study.","cn":"这正是我的研究团队希望在新研究中回答的问题。"},{"sp":"讲座 1","en":"Our hypothesis was that cyberloafing may serve as a mini-break, giving employees an opportunity to recover from stressful work situations.","cn":"我们的假设是，网络闲逛可以起到短暂休息的作用，为员工提供从压力大的工作情境中恢复的机会。"},{"sp":"讲座 1","en":"To test this, we asked workers to complete an online survey and rank how much time they spent cyberloafing, checking non-work emails and shopping.","cn":"为了验证这一点，我们要求员工完成一份在线调查，并对自己花在网络闲逛、查看非工作邮件和购物上的时间进行排序。"},{"sp":"讲座 1","en":"We also asked them to rank job satisfaction, their desire to quit, and how often they've experienced mistreatment at work, such as being bullied, threatened or yelled at.","cn":"我们还要求他们对工作满意度、离职意愿，以及在工作中遭受不当对待的频率进行评定，例如受到欺凌、威胁或吼叫。"},{"sp":"讲座 1","en":"As you might expect, we found that overall, more mistreatment at work was correlated with lower levels of job satisfaction and a greater desire to quit.","cn":"正如你所料，我们发现总体而言，工作中遭受的不当对待越多，工作满意度越低，离职意愿越强。"},{"sp":"讲座 1","en":"More interestingly, we found that cyberloafing effectively buffered this connection.","cn":"更有意思的是，我们发现网络闲逛有效地缓冲了这种关联。"},{"sp":"讲座 1","en":"That is, mistreated workers who spent more time surfing the web and checking emails reported higher job satisfaction and were less likely to want to quit than similar participants who didn't cyberloaf as much.","cn":"也就是说，与网络闲逛较少的类似参与者相比，遭受不当对待但花更多时间浏览网页和查看电子邮件的员工报告了更高的工作满意度，也不太可能想要离职。"},{"sp":"讲座 1","en":"This suggests that cyberloafing acts as a sort of relief valve for workers, helping them recover from stressful experiences.","cn":"这表明，网络闲逛对员工而言就像一种减压阀，帮助他们从压力经历中恢复过来。"},{"sp":"讲座 1","en":"While we did not directly assess how cyberloafing affects worker performance, we believe by relieving stress it may not only reduce worker turnover, but also ultimately bolster productivity.","cn":"虽然我们没有直接评估网络闲逛如何影响员工的工作表现，但我们认为，通过缓解压力，它不仅可能减少员工流失，最终还可能提高生产力。"},{"sp":"讲座 1","en":"This fits with other recent research that suggests taking short breaks is associated with higher levels of daily job performance.","cn":"这与其他近期研究的结果相符，即进行短暂休息与更高水平的日常工作表现相关。"},{"sp":"讲座 1","en":"That isn't to say cyberloafing is always good.","cn":"这并不是说网络闲逛总是有益的。"},{"sp":"讲座 1","en":"Too much time spent on non-work activities likely causes performance to suffer.","cn":"花费过多时间从事非工作活动很可能会导致工作表现下降。"},{"sp":"讲座 1","en":"All in all, managers should be more lenient with employees.","cn":"总的来说，管理者应该对员工更加宽容。"},{"sp":"讲座 1","en":"We believe a bit of online shopping or surfing the internet at work could make workers more productive in the long run.","cn":"我们认为，在工作中进行一些在线购物或浏览互联网，从长远来看可能会让员工更具生产力。"},{"sp":"讲座 2","en":"When Julius Morton moved to Nebraska City in 1854, he faced a problem shared by many settlers in the territory: It was a treeless plain.","cn":"1854年，朱利叶斯·莫顿迁居内布拉斯加城时，面临着该地区许多定居者共同面对的问题：这里是一片没有树木的平原。"},{"sp":"讲座 2","en":"That meant no trees for building materials, or for fuel.","cn":"这意味着没有树木可用作建筑材料，也没有木材可作燃料。"},{"sp":"讲座 2","en":"But Morton was one of the world's first conservationists, stating, \"For prosperity, we ought to plant as many forests as we have exhausted and consumed\".","cn":"但莫顿是世界上最早的自然资源保护主义者之一，他说：“为了繁荣，我们应当种植与已经耗尽和消耗掉的森林一样多的森林。"},{"sp":"讲座 2","en":"So he started planting trees, beginning with his own land.","cn":"”于是，他开始植树，先从自己的土地种起。"},{"sp":"讲座 2","en":"By 1860 Morton possessed a forest of more than 300 trees.","cn":"到1860年，莫顿已经拥有一片由300多棵树组成的树林。"},{"sp":"讲座 2","en":"A few years later, he had more than 1,000.","cn":"几年后，他拥有的树木超过了1,000棵。"},{"sp":"讲座 2","en":"As the forest grew, so did Morton's influence in Nebraska.","cn":"随着树林不断生长，莫顿在内布拉斯加州的影响力也日益扩大。"},{"sp":"讲座 2","en":"This was largely because Morton founded the Nebraska City News, the state's first newspaper, in which he frequently wrote editorials about the practical and aesthetic benefits of tree planting.","cn":"这主要是因为莫顿创办了《内布拉斯加城新闻报》，这是该州的第一份报纸；他经常在报纸上撰写社论，介绍植树在实用和审美方面的益处。"},{"sp":"讲座 2","en":"He also organized the Nebraska State Gardening Society and served on the Nebraska State Board of Agriculture.","cn":"他还组织成立了内布拉斯加州园艺协会，并担任内布拉斯加州农业委员会委员。"},{"sp":"讲座 2","en":"While serving on the Board, Morton came up with an idea to spread his belief in tree planting statewide.","cn":"任职期间，莫顿想出了一个办法，要将他关于植树的信念传播到全州。"},{"sp":"讲座 2","en":"On January 4, 1872, Morton drafted a resolution that April 10 be designated day for the planting of trees in the State of Nebraska and urged people to go out and plant trees themselves.","cn":"1872年1月4日，莫顿起草了一项决议，提议将4月10日定为内布拉斯加州植树日，并号召人们走出家门，亲自植树。"},{"sp":"讲座 2","en":"Morton called the special event Arbor Day as \"arbor\" is Latin for \"tree\".","cn":"莫顿把这一特别活动称为“植树节”，因为“arbor”在拉丁语中意为“树”。"},{"sp":"讲座 2","en":"The state government agreed.","cn":"州政府同意了这一提议。"},{"sp":"讲座 2","en":"And on April 10, 1872, the first unofficial Arbor Day was celebrated throughout Nebraska.","cn":"1872年4月10日，内布拉斯加州各地庆祝了第一个非正式的植树节。"},{"sp":"讲座 2","en":"Prizes were awarded to counties, cities, and individuals who planted the largest number of trees.","cn":"植树数量最多的县、市和个人获得了奖励。"},{"sp":"讲座 2","en":"That day, an astounding one million trees were planted in Nebraska—an average of more than six for every man, woman and child in the state.","cn":"那一天，内布拉斯加州种下了惊人的100万棵树，平均每位州内居民，包括男女老幼在内，种下了六棵以上的树。"},{"sp":"讲座 2","en":"Since 1885, Nebraska has planted more than 700,000 acres of trees, earning it the nickname \"the Tree Planters State\".","cn":"自1885年以来，内布拉斯加州已经种植了超过70万英亩的树木，因此获得了“植树州”的昵称。"},{"sp":"讲座 2","en":"Arbor Day became a legal, civic holiday in the state in 1885.","cn":"1885年，植树节在该州成为法定的公民节日。"},{"sp":"讲座 2","en":"It was held on April 22—Julius Morton's birthday.","cn":"节日定于4月22日举行，这一天是朱利叶斯·莫顿的生日。"},{"sp":"讲座 2","en":"In addition to a parade in Nebraska City, Morton introduced what has since become a long-standing Arbor Day tradition: School children went outside and planted trees together.","cn":"除了在内布拉斯加城举行游行外，莫顿还引入了一项后来成为植树节长期传统的活动：学生们走到户外，一起植树。"},{"sp":"讲座 2","en":"In 1970, nearly a century after Arbor Day was first celebrated, President Richard Nixon declared the last Friday of every April to be observed as National Arbor Day.","cn":"1970年，也就是植树节首次庆祝近一个世纪后，理查德·尼克松总统宣布将每年4月的最后一个星期五定为全国植树节。"},{"sp":"讲座 2","en":"All 50 states recognize the April observance, although many hold an additional state Arbor Day in a month more suited to local tree planting.","cn":"美国50个州都承认在4月举行的这一节日，尽管许多州还会在更适合当地植树的月份另行庆祝本州植树节。"},{"sp":"讲座 3","en":"Modern humans arose in Africa about 200,000 years ago.","cn":"现代人类在大约20万年前起源于非洲。"},{"sp":"讲座 3","en":"They then spread across Europe and Asia sometime after 60,000 years ago.","cn":"随后，他们在距今6万年后的某个时间扩散到了欧洲和亚洲。"},{"sp":"讲座 3","en":"This is the \"Out of Africa\" model, as it's commonly known.","cn":"这就是人们通常所说的“走出非洲”模型。"},{"sp":"讲座 3","en":"In the 1990s, the hypothesis found widespread acceptance.","cn":"在20世纪90年代，这一假设得到了广泛接受。"},{"sp":"讲座 3","en":"But this popular idea is in need of revision, particularly given the number of important findings across Asia over the past few decades.","cn":"但鉴于过去几十年间在整个亚洲取得的一系列重要发现，这一流行观点有必要进行修改。"},{"sp":"讲座 3","en":"For instance, many new human fossils found, particularly in China, are now dated as older than 60,000 years.","cn":"例如，许多新发现的人类化石（特别是在中国发现的）现在的测年结果都早于6万年前。"},{"sp":"讲座 3","en":"This calls into question the idea that modern humans migrated out of Africa only 60,000 years ago.","cn":"这使人们对现代人类仅在6万年前才迁出非洲的观点提出了质疑。"},{"sp":"讲座 3","en":"Take the recent discovery of two modern human teeth found in the Luna cave in China's Guangxi Zhuang Autonomous Region.","cn":"以最近在中国广西壮族自治区陆那洞发现的两颗现代人类牙齿为例。"},{"sp":"讲座 3","en":"When my research team and I dated these teeth, we found they were more than 70,000 years old—a situation clearly impossible if modern humans moved out of Africa only 60,000 years ago.","cn":"当我和我的研究团队对这两颗牙齿进行测年时，我们发现它们有超过7万年的历史——如果现代人类仅在6万年前才走出非洲，这种情况显然是不可能的。"},{"sp":"讲座 3","en":"So with such findings, what happened exactly?","cn":"那么，面对这些发现，究竟发生了什么？"},{"sp":"讲座 3","en":"Where does the most current data suggest we came from?","cn":"最新的数据表明我们来自何方？"},{"sp":"讲座 3","en":"The first question we should ask is why did modern humans leave Africa to begin with?","cn":"我们首先应该问的问题是：现代人类最初为什么离开非洲？"},{"sp":"讲座 3","en":"If a population is perfectly adapted to a particular environment and has access to an abundance of resources, then there really is no reason to move or change.","cn":"如果一个群体完全适应了特定环境并且拥有丰富的资源，那么确实没有理由迁移或改变。"},{"sp":"讲座 3","en":"For instance, some monkeys in Africa have a set of teeth that has hardly changed over the course of millions of years, indicating that they found a place that has worked for them.","cn":"例如，非洲的一些猴子的牙齿在数百万年间几乎没有任何变化，这表明它们找到了适合自己的生存之地。"},{"sp":"讲座 3","en":"So what happened with humans?","cn":"那么人类发生了什么？"},{"sp":"讲座 3","en":"Some researchers have suggested that population density increased to the point where smaller human groups were forced to explore new lands.","cn":"一些研究人员提出，人口密度增加到了迫使较小的人类群体不得不去探索新土地的程度。"},{"sp":"讲座 3","en":"Other researchers have suggested that due to major environmental events in East Africa, humans were prompted to find greener pastures.","cn":"另一些研究人员则认为，由于东非发生的重大环境事件，促使人类去寻找更适宜生存的环境。"},{"sp":"讲座 3","en":"Yet another explanation could simply be that early modern human hunters were following the large animals that they relied on, and so they moved out of Africa without realizing that they were actually moving from one continent to another.","cn":"还有一种解释可能仅仅是，早期的现代人类猎人跟随着他们所依赖的大型动物，因此在没有意识到自己实际上正在从一个大洲迁移到另一个大洲的情况下就移出了非洲。"},{"sp":"讲座 3","en":"Humans need daily access to reliable fresh water, which appears to be absent from many coastal areas.","cn":"人类每天都需要获得可靠的淡水，而许多沿海地区似乎缺乏淡水。"},{"sp":"讲座 3","en":"This brings us to another question: by which route did modern humans move out of Africa?","cn":"这就带出了另一个问题：现代人类是通过哪条路线迁出非洲的？"},{"sp":"讲座 3","en":"No clear route across the Mediterranean from North Africa appears to be present, so the earlier dispersals out of Africa and into Europe and Asia might have been across the Arabian Peninsula.","cn":"从北非穿过地中海的路线似乎并不存在明确的路径，因此早期走出非洲进入欧洲和亚洲的扩散可能是穿过了阿拉伯半岛。"}]},{"id":"cet6-2023-12-1","level":"CET6","exam":"2023_12_1","year":2023,"month":12,"set":1,"type":"整卷听力","title":"2023年12月 六级第1套 · 听力真题","source":"2023年12月 CET-6 第1套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet6-2023-12-set1.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"M: Hello, doctor.","cn":"M：你好，医生。"},{"sp":"长对话 1","en":"W: Hello, please take a seat. I have your test results here, and it's good news. The blood test came back clear. There is no indication of any digestive issues.","cn":"W：你好，请坐。我这里有你的检查结果，而且是个好消息。血液检查结果正常，没有任何消化系统问题的迹象。"},{"sp":"长对话 1","en":"M: So then why do I feel so poorly all the time?","cn":"M：那我为什么总是感觉这么不舒服？"},{"sp":"长对话 1","en":"W: It's probably due to overwork and stress.","cn":"W：这可能是过度劳累和压力造成的。"},{"sp":"长对话 1","en":"M: No, it can't be.","cn":"M：不，不可能。"},{"sp":"长对话 1","en":"I've always been working hard, but I've never felt stress.","cn":"我一直都很努力地工作，但从来没有感到过压力。"},{"sp":"长对话 1","en":"Other people suffering complain about that, but I don't.","cn":"其他饱受压力折磨的人会抱怨这个问题，但我不会。"},{"sp":"长对话 1","en":"It must be something else.","cn":"一定是别的原因。"},{"sp":"长对话 1","en":"W: What you have just described is a common sentiment.","cn":"W：你刚才描述的情况很常见。"},{"sp":"长对话 1","en":"Many people who suffer from stress fail to recognise it.","cn":"许多承受压力的人都没有意识到自己正处于压力之中。"},{"sp":"长对话 1","en":"You told me you often work long into the night, right?","cn":"你告诉过我，你经常工作到深夜，对吧？"},{"sp":"长对话 1","en":"M: Yes, most days in fact.","cn":"M：对，实际上大多数日子都是这样。"},{"sp":"长对话 1","en":"But I've been doing that for about 20 years now.","cn":"但我这样已经有大约20年了。"},{"sp":"长对话 1","en":"W: That doesn't matter.","cn":"W：那并不代表什么。"},{"sp":"长对话 1","en":"You could have been suffering from stress for 20 years without knowing it, and now it's catching up to you.","cn":"你可能在不知情的情况下承受了20年的压力，现在它开始影响你了。"},{"sp":"长对话 1","en":"M: But what about my feeling tired all the time and not being able to sleep well at night?","cn":"M：可是我总是感到疲惫，晚上也睡不好，这又是怎么回事？"},{"sp":"长对话 1","en":"W: Those are common consequences of stress.","cn":"W：这些都是压力带来的常见后果。"},{"sp":"长对话 1","en":"And if you don't sleep well, then of course you will feel fatigued.","cn":"如果你睡不好，当然就会感到疲劳。"},{"sp":"长对话 1","en":"I'm going to prescribe some special sleeping pills for you.","cn":"我会给你开一些特殊的安眠药。"},{"sp":"长对话 1","en":"They have a soft, gentle effect and are made from natural ingredients, so your stomach should tolerate them fine, and there shouldn't be any negative side effects.","cn":"它们药效温和，是用天然成分制成的，所以你的胃应该能够很好地耐受，也不应产生任何负面副作用。"},{"sp":"长对话 1","en":"Take one with your dinner and come see me after a month.","cn":"晚餐时服用一片，一个月后再来见我。"},{"sp":"长对话 1","en":"If there is no improvement, I'll give you something stronger.","cn":"如果没有改善，我会给你开药效更强的药。"},{"sp":"长对话 1","en":"M: Thank you, doctor.","cn":"M：谢谢你，医生。"},{"sp":"长对话 1","en":"W: That's not all.","cn":"W：还不止这些。"},{"sp":"长对话 1","en":"You should try and work less.","cn":"你应该试着少工作一些。"},{"sp":"长对话 1","en":"Is there any way you can decrease your workload?","cn":"你有没有办法减轻自己的工作量？"},{"sp":"长对话 1","en":"M: Um, I'd have to think about it.","cn":"M：嗯，我得考虑一下。"},{"sp":"长对话 1","en":"I'm a restaurant manager and this industry is very competitive.","cn":"我是一名餐厅经理，而这个行业竞争非常激烈。"},{"sp":"长对话 1","en":"There are many things to keep track of and stay on top of.","cn":"有很多事情需要跟进并确保掌控。"},{"sp":"长对话 1","en":"W: I recommend you think about delegating some responsibilities to someone else.","cn":"W：我建议你考虑把一部分职责委派给其他人。"},{"sp":"长对话 1","en":"I'm not asking you to retire just to slow down a bit.","cn":"我不是让你退休，只是让你稍微放慢节奏。"},{"sp":"长对话 1","en":"It's for your own health.","cn":"这是为了你自己的健康。"},{"sp":"长对话 2","en":"W: Today on People in the News, our guest is John Williams.","cn":"W: 欢迎收看今天的《新闻人物》，我们的嘉宾是约翰·威廉姆斯。"},{"sp":"长对话 2","en":"The name may not sound familiar to you, but John was once an acclaimed basketball player.","cn":"这个名字大家可能不太熟悉，但约翰曾经是一位备受赞誉的篮球运动员。"},{"sp":"长对话 2","en":"John, you stunned fans by leaving the sport at just 25.","cn":"约翰，你在年仅25岁时退役让球迷们大吃一惊。"},{"sp":"长对话 2","en":"Why did you retire so early?","cn":"你当时为什么这么早就选择退役呢？"},{"sp":"长对话 2","en":"M: Meg, I loved being an athlete, but I didn't love being a celebrity.","cn":"M: 梅格，我热爱成为一名运动员，但我不喜欢成为名人。"},{"sp":"长对话 2","en":"I was in the limelight when I was still a high school student and went professional right after high school graduation, which was a mistake.","cn":"我还在上高中时就处于聚光灯下，高中一毕业就转为了职业球员，这其实是个错误。"},{"sp":"长对话 2","en":"I was a shy kid and I wasn't ready for all the media attention.","cn":"我当时是个害羞的孩子，还没做好应对所有媒体关注的准备。"},{"sp":"长对话 2","en":"W: But walking away from millions of dollars at the height of your career, most people wouldn't be able to resist the lure of such a high salary.","cn":"W: 但在职业生涯鼎盛时期放弃数百万美元，大多数人都无法抵挡如此高薪的诱惑。"},{"sp":"长对话 2","en":"When you left the sport, there was speculation that you were having issues with your teammates or even an injury.","cn":"当你离开赛场时，外界曾推测你是和队友产生了矛盾，甚至是有伤在身。"},{"sp":"长对话 2","en":"M: Not at all.","cn":"M: 完全不是这样。"},{"sp":"长对话 2","en":"It was hard to quit.","cn":"选择放弃确实很难。"},{"sp":"长对话 2","en":"I was tempted to stay in the game, because I love basketball and I loved my team.","cn":"我当时也纠结过要不要留下来继续打球，因为我热爱篮球，也热爱我的球队。"},{"sp":"长对话 2","en":"As for money, I turned professional at 18.","cn":"至于钱的问题，我18岁就转为了职业球员。"},{"sp":"长对话 2","en":"So I'd actually earned a lot and saved most of it, because I had great financial advisers.","cn":"因为我有优秀的理财顾问，所以我实际上已经赚了不少钱，并且存下了大部分。"},{"sp":"长对话 2","en":"I knew basketball wasn't a career with a lot of longevity for most players, so I wanted to change careers while I was still young.","cn":"我知道对大多数球员来说，篮球并不是一项能打很久的职业，所以我希望趁自己还年轻转换职业。"},{"sp":"长对话 2","en":"W: Okay, that was 20 years ago, and you're back in the news.","cn":"W: 好的，那是20年前的事了，现在你又重回大众视野。"},{"sp":"长对话 2","en":"You've created a foundation that works to get more kids playing team sports.","cn":"你创立了一个基金会，致力于让更多孩子参与团队运动。"},{"sp":"长对话 2","en":"Why?","cn":"这是为什么呢？"},{"sp":"长对话 2","en":"M: I went to university and I studied public health and learned about the seriousness of the obesity epidemic, particularly among kids and adolescents in poor communities.","cn":"M: 我读了大学，学习了公共卫生学，了解到肥胖流行问题的严重性，尤其是在贫困社区的儿童和青少年群体中。"},{"sp":"长对话 2","en":"I've spent the last two decades trying to alleviate the problem.","cn":"在过去二十年里，我一直在努力缓解这个问题。"},{"sp":"长对话 2","en":"The foundation is just the latest attempt.","cn":"这个基金会只是我最新的尝试。"},{"sp":"长对话 2","en":"W: The foundation uses private donations to support basketball teams for girls and boys in primary school, right?","cn":"W: 这个基金会利用私人捐款来资助小学的男女生篮球队，对吗？"},{"sp":"长对话 2","en":"M: Actually, we support teams for secondary school students, too, and also have some public funding.","cn":"M: 实际上，我们也资助中学生的球队，而且我们也有一些公共资金。"},{"sp":"听力篇章 1","en":"Kate Atkinson was born in York, England, in 1951.","cn":"凯特·阿特金森于1951年出生于英国约克。"},{"sp":"听力篇章 1","en":"She worked hard to gain her credentials as an author.","cn":"她努力获得了作为作家的资历。"},{"sp":"听力篇章 1","en":"She studied English Literature at University in Scotland.","cn":"她在苏格兰的一所大学学习英国文学。"},{"sp":"听力篇章 1","en":"After graduating in 1974, she researched a doctorate on American Literature.","cn":"1974年毕业后，她攻读美国文学博士学位。"},{"sp":"听力篇章 1","en":"Later, she taught at the university she graduated from, and began writing short stories in 1981.","cn":"后来，她在自己毕业的那所大学任教，并于1981年开始创作短篇小说。"},{"sp":"听力篇章 1","en":"She began writing for women's magazines after winning the 1986 Woman's Own Short Story Competition.","cn":"她赢得1986年《Woman's Own》短篇小说比赛后，开始为女性杂志撰稿。"},{"sp":"听力篇章 1","en":"Her first novel, Behind the Scenes at the Museum, won the 1995 UK Book of the Year award.","cn":"她的第一部小说《博物馆幕后》获得了1995年英国年度图书奖。"},{"sp":"听力篇章 1","en":"The book is set in Yorkshire and has been adapted for radio, theatre, and TV.","cn":"小说以约克郡为背景，后来被改编成广播剧、舞台剧和电视剧。"},{"sp":"听力篇章 1","en":"She has written two plays for a theatre in Edinburgh—the first was called Nice and the second Abandonment, performed as part of the Edinburgh Festival in August 2000.","cn":"她为爱丁堡的一家剧院创作了两部戏剧，第一部名为《Nice》，第二部名为《Abandonment》，于2000年8月作为爱丁堡艺术节的一部分演出。"},{"sp":"听力篇章 1","en":"Whatever genre Atkinson writes in, her books touch on the themes of love and loss and how to carry on.","cn":"无论阿特金森创作哪一种类型的作品，她的书都触及爱与失去以及如何继续生活下去等主题。"},{"sp":"听力篇章 1","en":"They are always presented with ingenuity and a wicked sense of humor.","cn":"她总是以独具匠心的方式呈现这些主题，并带有一种辛辣的幽默感。"},{"sp":"听力篇章 1","en":"Her books tend to be populated by odd, sometimes sinful, and generally flawed eccentrics who become credible by virtue of being so fully realized.","cn":"她的书中往往充满古怪、有时甚至有罪过、总体上存在缺陷的特立独行者；正因为这些人物被刻画得如此完整，他们才显得可信。"},{"sp":"听力篇章 1","en":"Her books have frequently been described as comedies of manners.","cn":"她的书经常被称为风俗喜剧。"},{"sp":"听力篇章 1","en":"That is to say, comedies that represent the complex and sophisticated code of behaviour current in fashionable circles of society, where appearances count more than true moral character.","cn":"也就是说，这类喜剧描绘的是社会时尚圈中复杂而精致的行为规范，在那里，外表比真正的道德品质更重要。"},{"sp":"听力篇章 1","en":"A comedy of manners tends to reward its clever and deceitful characters, rather than punish their bad deeds.","cn":"风俗喜剧往往奖赏那些聪明而诡诈的人物，而不是惩罚他们的恶行。"},{"sp":"听力篇章 1","en":"The humor of a comedy of manners relies on verbal wit and playful teasing.","cn":"风俗喜剧的幽默依靠语言机智和顽皮的调侃。"},{"sp":"听力篇章 2","en":"Why is adaptability an important skill to exercise in the workplace?","cn":"为什么说适应能力是在职场中需要培养的一项重要技能？"},{"sp":"听力篇章 2","en":"Simply put, adaptability is a skill employers are increasingly looking for.","cn":"简单来说，适应能力是雇主日益重视的一项技能。"},{"sp":"听力篇章 2","en":"When you spend time learning a new task rather than resisting it, your productivity goes up.","cn":"当你花时间学习一项新任务，而不是抗拒它时，你的工作效率就会提高。"},{"sp":"听力篇章 2","en":"You can also serve as an example to your co-workers who may be having trouble adapting, and can help lead your team forward.","cn":"你还可以为那些在适应方面可能遇到困难的同事树立榜样，并帮助带领团队向前发展。"},{"sp":"听力篇章 2","en":"Strategy consultant, Dorie Clark, explains it to us this way.","cn":"战略顾问多莉·克拉克这样向我们解释：“我认为，适应能力之所以是职场中的一项重要技能，是因为坦率地说，环境会发生变化。"},{"sp":"听力篇章 2","en":"\"I'd say that adaptability is an important skill in the workplace because frankly, circumstances change.","cn":"竞争对手会推出新产品，经济可能会陷入衰退，客户偏好会随着时间而改变，等等。"},{"sp":"听力篇章 2","en":"Competitors introduce new products, economy might enter a recession, customer preferences differ over time, and more.","cn":"如果你对着天空挥拳，问为什么不能一成不变，那不会带来什么实际帮助。"},{"sp":"听力篇章 2","en":"If you shake your fist at the sky and say why can't it stay the same, that's not going to do very much good.","cn":"相反，你需要认识到环境已经发生变化，从而根据现实情况，而不是根据你希望世界呈现的样子，采取适当行动。"},{"sp":"听力篇章 2","en":"Instead, you need to recognise when circumstances have changed, so you can take appropriate action based on what is, rather than how you wish the world would be.","cn":"这样一来，你就能作出更准确、更有依据且更有效的选择。"},{"sp":"听力篇章 2","en":"That enables you to make more accurate, informed and effective choices.\"","cn":"”"},{"sp":"听力篇章 2","en":"Also, the workplace itself has been evolving.","cn":"此外，职场本身也一直在不断发展变化。"},{"sp":"听力篇章 2","en":"Today's work culture and management style is often based on teamwork, rather than a rigid hierarchy.","cn":"如今的职场文化和管理方式通常以团队合作为基础，而不是建立在僵化的等级制度之上。"},{"sp":"听力篇章 2","en":"Brainstorming, which requires creativity, flexibility, and emotional intelligence, is a typical problem-solving technique.","cn":"头脑风暴要求具备创造力、灵活性和情商，是一种典型的问题解决方法。"},{"sp":"听力篇章 2","en":"Employees who are unable or unwilling to participate will not easily move forward in the company.","cn":"无法或不愿参与的员工，很难在公司中顺利发展。"},{"sp":"听力篇章 2","en":"Employees who are flexible demonstrate other skills too.","cn":"灵活变通的员工还展现出其他技能。"},{"sp":"听力篇章 2","en":"They can reprioritize quickly when changes occur and suggest additional modifications when something is not working.","cn":"他们能够在发生变化时迅速调整优先事项，并在某件事不起作用时提出进一步的修改建议。"},{"sp":"听力篇章 2","en":"They can also regroup quickly when a setback occurs, adapting to the new situation confidently and without overreacting.","cn":"当遭遇挫折时，他们也能迅速重新组织起来，自信地适应新情况，而不会反应过度。"},{"sp":"讲座 1","en":"What makes humans different from other species?","cn":"是什么使人类区别于其他物种？"},{"sp":"讲座 1","en":"Some philosophers argue it's morals or ethics, while some scientists assert it's our greater cognitive development.","cn":"一些哲学家认为是道德或伦理，而一些科学家断言是我们更高的认知发展水平。"},{"sp":"讲座 1","en":"But I argue that the main difference is our desire to combat routine.","cn":"但我认为，主要区别在于我们渴望对抗惯常模式。"},{"sp":"讲座 1","en":"This makes being creative a biological mandate, as what we seek in art and technology is surprise, not simply a fulfillment of expectations.","cn":"这使创造具有生物学意义上的必然性，因为我们在艺术和技术中寻求的是惊喜，而不只是满足预期。"},{"sp":"讲座 1","en":"As a result, a wild imagination has characterized the history of our species.","cn":"因此，狂野的想象力贯穿了我们这个物种的历史。"},{"sp":"讲座 1","en":"We build intricate habitats, devise complex recipes for our food, wear clothes that reflect constant changes in fashion, communicate with elaborate signs, symbols, and sounds, and travel between habitats on wings and wheels of our own design.","cn":"我们建造精巧复杂的栖息地，为食物设计复杂的食谱，穿着体现时尚不断变化的服装，用繁复的标志、符号和声音进行交流，还乘坐由我们自己设计的翅膀和轮子，在不同栖息地之间往来。"},{"sp":"讲座 1","en":"To satisfy our appetite for novelty, innovation is key.","cn":"为了满足我们对新奇事物的渴望，创新至关重要。"},{"sp":"讲座 1","en":"But who innovates?","cn":"但谁在创新？"},{"sp":"讲座 1","en":"Now, many people, both laymen and experts, believe that only geniuses innovate.","cn":"如今，许多人，包括普通人和专家，都认为只有天才才能创新。"},{"sp":"讲座 1","en":"But I believe that innovation is not something that only a few people do.","cn":"但我认为，创新并不是只有少数人才会做的事情。"},{"sp":"讲座 1","en":"The innovative drive lives in every human brain, and the resulting war against the repetitive is what powers the massive changes that distinguish one generation from the next.","cn":"创新的驱动力存在于每个人的大脑中，而由此产生的反重复之战，正是推动巨大变革的力量，使一代人与下一代人彼此不同。"},{"sp":"讲座 1","en":"The drive to create the new is a trait of being human.","cn":"创造新事物的动力是人类特有的特征。"},{"sp":"讲座 1","en":"We build cultures by the hundreds and tell new stories by the millions.","cn":"我们成百上千地建立文化，以数百万计讲述新的故事。"},{"sp":"讲座 1","en":"We create and surround ourselves with things that have never existed before, while animals do not.","cn":"我们创造并置身于此前从未存在过的事物之中，而动物不会这样做。"},{"sp":"讲座 1","en":"But where do our new ideas come from?","cn":"但我们的新思想究竟从何而来？"},{"sp":"讲座 1","en":"According to many, new ideas come from seemingly nowhere to great minds.","cn":"许多人认为，新思想会凭空出现在伟大思想家的脑海中。"},{"sp":"讲座 1","en":"From this perspective, new ideas are almost like magic.","cn":"从这个角度看，新思想几乎像是魔法。"},{"sp":"讲座 1","en":"They come in a flash of inspiration to a select few.","cn":"它们以灵感闪现的方式降临到少数人身上。"},{"sp":"讲座 1","en":"However, the reality is that, across the spectrum of human activities, prior work propels the creative process.","cn":"然而，现实是，在人类活动的各个领域，先前的工作推动着创造过程。"},{"sp":"讲座 1","en":"We may think of innovation as being the result of inspiration or genius, but it's really the result of developing the ideas of others further.","cn":"我们可能认为创新源于灵感或天才，但实际上，它是进一步发展他人思想的结果。"},{"sp":"讲座 1","en":"This happens in technology, where one invention enables or inspires further inventions.","cn":"这种情况发生在技术领域：一项发明会促成或启发更多发明。"},{"sp":"讲座 1","en":"And it happens in the arts, as writers, composers, and painters use the work of previous artists in their own work.","cn":"在艺术领域也是如此，作家、作曲家和画家会将前辈艺术家的作品运用到自己的创作中。"},{"sp":"讲座 1","en":"The human brain works from precedent.","cn":"人类大脑以先例为基础运作。"},{"sp":"讲座 1","en":"We take the ideas we've inherited and put them together into some new shape.","cn":"我们吸收继承而来的思想，并将它们重新组合成某种新的形式。"},{"sp":"讲座 1","en":"What is a true creator? Is a creator a genius who makes something out of nothing? No. Creators are simply humans who use what they inherit, who absorb the past and manipulate it to create possible futures. Thus, humans are creators as a rule rather than as an exception.","cn":"什么是真正的创造者？创造者是那个能从无到有创造出某种事物的天才吗？不是。创造者只不过是运用继承之物、吸收过去并加以改造，从而创造出未来可能性的人类。因此，人类通常都是创造者，而不是只有少数例外者。"},{"sp":"讲座 2","en":"Many dog owners would tell you that their dog somehow knows when they're ill or upset, and according to researchers who study dog cognition, those pet owners are right.","cn":"许多养狗的人都会告诉你，他们的狗不知怎么就能察觉到自己生病或情绪低落；而根据研究犬类认知的研究人员所说，这些宠物主人是对的。"},{"sp":"讲座 2","en":"Dogs do know when their human companions are having a rough time.","cn":"狗确实知道它们的人类伴侣正经历艰难时期。"},{"sp":"讲座 2","en":"Not only can your dog sense when you have a cold, but domestic dogs have shown an aptitude for detecting both much smaller mood fluctuations and far more serious physical conditions.","cn":"你的狗不仅能察觉你感冒了，家犬还表现出了发现细微情绪波动以及更严重身体状况的能力。"},{"sp":"讲座 2","en":"This is because dogs are extremely sensitive to changes in the people they're familiar with, and illness causes change.","cn":"这是因为狗对熟悉之人的变化极其敏感，而疾病会引起变化。"},{"sp":"讲座 2","en":"If a person is infected with a virus or bacteria, for example, their odor will be abnormal, and dogs are able to smell that change even if the human can't, because dogs have a much more powerful sense of smell than humans.","cn":"例如，如果一个人感染了病毒或细菌，他的气味就会异常；即使人类自己察觉不到这种变化，狗也能闻出来，因为狗的嗅觉比人类强大得多。"},{"sp":"讲座 2","en":"Researchers have also found that a person's mood, which can be an indicator of a larger illness, triggers a dog's sense of smell.","cn":"研究人员还发现，一个人的情绪可能是更严重疾病的迹象，并会触发狗的嗅觉。"},{"sp":"讲座 2","en":"Human emotions manifest physically in chemical signals that are emitted by the body, and dogs are able to smell those as well.","cn":"人类的情绪会以身体释放出的化学信号在生理上表现出来，而狗同样能够闻到这些信号。"},{"sp":"讲座 2","en":"Beyond smell, dogs gather information from a person's voice in order to sense changes.","cn":"除了嗅觉之外，狗还会从人的声音中获取信息，以察觉变化。"},{"sp":"讲座 2","en":"In 2014, researchers discovered that dogs have an area of the brain similar to one in humans that allows them to understand emotional cues in the tone of a speaker's voice, beyond what they'd be able to pick up from familiar words alone.","cn":"2014年，研究人员发现，狗的大脑中有一个区域与人类大脑中的某个区域相似，使它们能够理解说话者声音语调中的情绪线索，而不仅仅是从熟悉的词语中获取信息。"},{"sp":"讲座 2","en":"A person's voice can also carry indicators of illness.","cn":"一个人的声音也可能携带疾病的迹象。"},{"sp":"讲座 2","en":"What's not understood quite so well is what dogs understand about these changes.","cn":"人们目前还不太清楚狗究竟理解这些变化到了什么程度。"},{"sp":"讲座 2","en":"Humans send out lots of cues, but whether dogs know some of these cues mean illness isn't clear.","cn":"人类会发出许多线索，但狗是否知道其中一些线索意味着疾病，还不明确。"},{"sp":"讲座 2","en":"What we perceive as concern on a dog's part might be more like increased curiosity or suspicion that something is wrong with us, and sticking close by is a great way to gather more information about the situation.","cn":"我们认为狗表现出的关切，可能更像是它们对我们出了问题这一情况产生了更强的好奇或怀疑，而待在我们身边则是获取更多相关信息的好方法。"},{"sp":"讲座 2","en":"Some researchers assert dogs will one day help doctors diagnose diseases, as some dogs have already demonstrated the ability to detect an assortment of ailments, including diabetes and certain types of cancer.","cn":"一些研究人员断言，狗有朝一日将帮助医生诊断疾病，因为有些狗已经展现出检测多种疾病的能力，包括糖尿病和某些类型的癌症。"},{"sp":"讲座 2","en":"But those researchers concede that's probably in the distant future.","cn":"但这些研究人员也承认，那可能是遥远未来的事。"},{"sp":"讲座 2","en":"For now, research suggests dog ownership can have an array of benefits in and of itself.","cn":"目前的研究表明，养狗本身就能带来一系列益处。"},{"sp":"讲座 2","en":"Keeping a pet dog has been shown to bolster health and boost mood.","cn":"事实证明，饲养宠物狗有助于增进健康、改善情绪。"},{"sp":"讲座 2","en":"Dogs also help people relax, and they can be a particular comfort to those with chronic diseases.","cn":"狗还能帮助人放松，对于患有慢性疾病的人来说，它们尤其能带来安慰。"},{"sp":"讲座 3","en":"Earlier this month, the think-tank called Onward published a report, \"A Question of Degree\", which argues that degrees in the creative arts are not good value for money.","cn":"本月早些时候，名为 Onward 的智库发布了一份题为《程度问题》的报告，认为创意艺术类学位的性价比不高。"},{"sp":"讲座 3","en":"Ministers, according to Onward, should \"crack down on courses that offer extremely limited value for money to students ten years after graduation\", restricting the ability of such courses to recruit new students, if the average graduate earns below the student loans payment threshold.","cn":"Onward 认为，部长们应当“严厉整治那些在学生毕业十年后仍只能为其提供极低性价比的课程”；如果此类课程的毕业生平均收入低于学生贷款还款门槛，就应限制这些课程招收新生。"},{"sp":"讲座 3","en":"Courses like science, technology, engineering, and math, and economics, where the average graduate earns a lot, should be favored.","cn":"对于科学、技术、工程、数学以及经济学等专业，由于其毕业生平均收入较高，则应予以优先考虑。"},{"sp":"讲座 3","en":"The report provides insight into a government review which looks at how to reform technical education and how to ensure students get good value for money.","cn":"这份报告为政府正在进行的一项审查提供了参考，该审查旨在研究如何改革技术教育，以及如何确保学生获得良好的性价比。"},{"sp":"讲座 3","en":"At first glance, it might even seem like Onward have a point.","cn":"乍看之下，Onward 似乎确实有道理。"},{"sp":"讲座 3","en":"According to their data, the majority of creative arts students earn less than 25,000 pounds a year, ten years after graduation.","cn":"根据其数据，大多数创意艺术类学生在毕业十年后年收入低于25,000英镑。"},{"sp":"讲座 3","en":"The average male creative arts students, indeed, apparently earn much less than they would, had they simply never gone to university.","cn":"事实上，据称创意艺术类专业的男性学生平均收入远低于他们如果当初根本没有上大学所能获得的收入。"},{"sp":"讲座 3","en":"This isn't really good for anyone, and it's certainly no good for graduates, who are forced to endure a lifestyle where they can never save up, never buy a house, never hope to retire.","cn":"这对任何人来说都不利，对毕业生而言尤其如此，因为他们被迫忍受一种永远无法攒下钱、永远买不起房、永远不敢指望退休的生活方式。"},{"sp":"讲座 3","en":"Onward has identified a real problem.","cn":"Onward 确实发现了一个真实存在的问题。"},{"sp":"讲座 3","en":"Creative arts graduates from top universities—like Oxford, with a high proportion of privately-educated students—have fairly good work prospects.","cn":"顶尖大学的创意艺术类毕业生，例如牛津大学的毕业生，由于其中有很大一部分学生来自私立学校，因此往往拥有相当不错的就业前景。"},{"sp":"讲座 3","en":"Well, 40 percent of all graduates—regardless of their degree—are on less than 25,000 pounds a year, 5 years after graduation.","cn":"可是，所有毕业生中有40%——无论他们所学的是什么学位——在毕业五年后年收入低于25,000英镑。"},{"sp":"讲座 3","en":"This suggests that the problem isn't really to do with specific students studying specific degrees, but really with the economy as a whole.","cn":"这表明，问题其实并不在于某些特定学生攻读某些特定学位，而在于整个经济状况。"},{"sp":"讲座 3","en":"Regardless of what they've studied, young people find it hard to get ahead unless they're lucky enough to be born with successful parents.","cn":"无论年轻人学了什么，除非他们足够幸运，出生在拥有成功事业的家庭，否则都很难取得进展。"},{"sp":"讲座 3","en":"If ministers want to make education pay for young people, they need to look beyond the higher education sector, towards the wider world.","cn":"如果部长们希望让教育为年轻人带来回报，就需要把视野放在高等教育领域之外，转向更广阔的社会。"},{"sp":"讲座 3","en":"The rewards that education gives us are not measurable.","cn":"教育带给我们的回报是无法衡量的。"},{"sp":"讲座 3","en":"They are not always instantly obvious, and certainly not always direct.","cn":"它们并不总是立刻显现出来，当然也并不总是直接的。"},{"sp":"讲座 3","en":"An education makes you a different person from the one you would have been if you hadn't received it.","cn":"接受教育会让你成为一个不同于未接受教育时的自己的人。"},{"sp":"讲座 3","en":"We need to look at the value of education not in the context of a bank balance, but of a life.","cn":"我们需要从人生的角度，而不是从银行账户余额的角度，来审视教育的价值。"},{"sp":"讲座 3","en":"If we continue to allow ourselves to be distracted with talk of \"value for money\", we will all be made poorer as a result.","cn":"如果我们继续让自己被“性价比”之类的说法分散注意力，最终我们所有人的生活都会因此变得更加贫乏。"}]},{"id":"cet6-2023-12-2","level":"CET6","exam":"2023_12_2","year":2023,"month":12,"set":2,"type":"整卷听力","title":"2023年12月 六级第2套 · 听力真题","source":"2023年12月 CET-6 第2套 · 听力（本地原音 + 逐句原文）","audio":"assets/audio/2023/cet6-2023-12-set2.mp3","intro":"听力原文按录音篇目逐句拆分，中文译文仅供参考；音频为本地真题原音，整卷原音无法定位单句，逐句请用下方播放器。","questions":[],"lines":[{"sp":"长对话 1","en":"W: So, I've been thinking, this summer, instead of our usual holiday rental, I'd like to try renting a camper van and exploring a bit more.","cn":"W: 我一直在想，今年夏天，我们不如不租平常那种度假屋，试试租一辆露营车，到处多探索一下。"},{"sp":"长对话 1","en":"M: A camper van?","cn":"M: 露营车？"},{"sp":"长对话 1","en":"You mean to spend the summer living out of a car?","cn":"你的意思是整个夏天都住在车里？"},{"sp":"长对话 1","en":"W: Yes, a camper van. And no, it's nothing like living out of a car. These are proper vans with full-size beds to sleep in. Some even have kitchens. This way, we wouldn't have to be locked into one place during our holiday. We'd be able to visit so many more places and travel at our own pace. The rates of most hotels and holiday homes really soar in the summer anyway. We'd probably save a lot of money as well.","cn":"W: 对，露营车。不过，这跟住在车里完全不是一回事。这种车是真正的厢式车，里面有全尺寸的床可以睡，有些甚至还带厨房。这样一来，度假的时候我们就不用被固定在一个地方了。我们可以多去很多地方，按照自己的节奏旅行。反正夏天大多数酒店和度假屋的价格都会大幅上涨。这样我们可能还能省下一大笔钱。"},{"sp":"长对话 1","en":"M: I think my grandfather had a van like that.","cn":"M: 我觉得我爷爷以前就有一辆那样的车。"},{"sp":"长对话 1","en":"It doesn't sound that appealing to me.","cn":"听起来对我没那么有吸引力。"},{"sp":"长对话 1","en":"W: Today's camper vans are completely different.","cn":"W: 现在的露营车完全不一样了。"},{"sp":"长对话 1","en":"These days, they're equipped with all the modern comforts.","cn":"如今，它们都配备了各种现代化的舒适设施。"},{"sp":"长对话 1","en":"I've seen quite a few with solar panels that provide electricity for when you're stopped.","cn":"我见过不少装有太阳能电池板的露营车，停车时可以用来供电。"},{"sp":"长对话 1","en":"This way, you can still use your computer or charge your phone.","cn":"这样你仍然可以使用电脑或给手机充电。"},{"sp":"长对话 1","en":"And most even have Wi-Fi, so if the weather's not great, you could stream videos.","cn":"而且大多数车甚至还配有 Wi-Fi，所以如果天气不太好，你还可以在线看视频。"},{"sp":"长对话 1","en":"M: I'm warming up to the idea.","cn":"M: 我开始有点接受这个想法了。"},{"sp":"长对话 1","en":"Keep talking.","cn":"继续说。"},{"sp":"长对话 1","en":"W: Loads of people are committing to this trend full time.","cn":"W: 现在有很多人全职投入这种生活方式。"},{"sp":"长对话 1","en":"Check it out online.","cn":"你可以上网看看。"},{"sp":"长对话 1","en":"Lots of people stream videos of their alternative lifestyles and actually earn a salary.","cn":"很多人把自己的另类生活方式拍成视频直播，实际上还能赚到工资。"},{"sp":"长对话 1","en":"Imagine having that kind of freedom to go anywhere you want and work from anywhere in the world.","cn":"想想看，要是能拥有那样的自由，想去哪儿就去哪儿，还能在世界任何地方工作，那该多好。"},{"sp":"长对话 1","en":"M: Okay, we can consider it.","cn":"M: 好吧，我们可以考虑一下。"},{"sp":"长对话 1","en":"As long as the basic needs like toilet and showers are covered, I'm definitely in.","cn":"只要厕所和淋浴之类的基本需求能得到满足，我肯定参加。"},{"sp":"长对话 1","en":"Do you think there will be enough room for my mountain bike?","cn":"你觉得我的山地车有足够的地方放吗？"},{"sp":"长对话 1","en":"What about food delivery?","cn":"那食物配送呢？"},{"sp":"长对话 1","en":"Will we be able to order at the van?","cn":"我们能在露营车这里点外卖吗？"},{"sp":"长对话 1","en":"Will there be enough space for the dog?","cn":"狗狗有足够的空间吗？"},{"sp":"长对话 1","en":"We wouldn't want to leave him behind.","cn":"我们可不想把它丢在家里。"},{"sp":"长对话 1","en":"W: Slow down.","cn":"W: 别急。"},{"sp":"长对话 1","en":"Glad you're excited about it.","cn":"很高兴你这么兴奋。"},{"sp":"长对话 1","en":"Let's start by looking at what's available first.","cn":"我们先看看现在有哪些选择吧。"},{"sp":"长对话 2","en":"W: You wanted to see me?","cn":"W: 你找我？"},{"sp":"长对话 2","en":"M: Yes, I'll get straight to the point.","cn":"M: 是的，我就直说了。"},{"sp":"长对话 2","en":"Over the past month or so, it has become apparent that your performance has dipped.","cn":"过去一个月左右，很明显你的工作表现有所下滑。"},{"sp":"长对话 2","en":"You've been late to work several times these past few weeks, which is very uncharacteristic of you.","cn":"最近几周你迟到过好几次，这很不像平时的你。"},{"sp":"长对话 2","en":"But what really concerns me is your curtailed output.","cn":"但真正让我担心的是你的工作产出减少了。"},{"sp":"长对话 2","en":"Lately, you seem to be constantly one step behind.","cn":"最近你似乎总是慢人一步。"},{"sp":"长对话 2","en":"What's going on?","cn":"到底怎么回事？"},{"sp":"长对话 2","en":"W: I'm sorry.","cn":"W: 对不起。"},{"sp":"长对话 2","en":"I'm going through some unfortunate family issues at the moment.","cn":"我最近正面临一些不幸的家庭问题。"},{"sp":"长对话 2","en":"It's a personal matter, so if you don't mind, I much prefer we don't get into it.","cn":"这是私事，所以如果你不介意的话，我很希望我们不要谈这个。"},{"sp":"长对话 2","en":"Nevertheless, I expect it to have all blown over in another month or so.","cn":"不过，我预计再过一个月左右，一切应该就会平息下来。"},{"sp":"长对话 2","en":"M: Do you need some time off?","cn":"M: 你需要请一段时间假吗？"},{"sp":"长对话 2","en":"W: Actually, yes.","cn":"W: 其实，是的。"},{"sp":"长对话 2","en":"Would it be possible to take the next two Mondays off?","cn":"下两个星期一我可以请假吗？"},{"sp":"长对话 2","en":"I was deliberating whether I should ask for this, but now that we're here…","cn":"我之前一直在犹豫要不要提出这个请求，不过既然我们现在谈到这儿了……"},{"sp":"长对话 2","en":"M: Sure thing.","cn":"M: 当然可以。"},{"sp":"长对话 2","en":"But if you needed some leave, why didn't you ask for it earlier?","cn":"但如果你需要休假，为什么不早点申请呢？"},{"sp":"长对话 2","en":"W: I'm not sure why.","cn":"W: 我也不知道为什么。"},{"sp":"长对话 2","en":"I guess I kind of felt bad asking for it.","cn":"我想我只是觉得提出休假请求不太好。"},{"sp":"长对话 2","en":"M: You shouldn't feel bad asking for leave, especially if you need it.","cn":"M: 你不应该因为请假而感到不好意思，尤其是在你确实需要休假的时候。"},{"sp":"长对话 2","en":"W: I know.","cn":"W: 我知道。"},{"sp":"长对话 2","en":"You're right.","cn":"你说得对。"},{"sp":"长对话 2","en":"I'm sorry.","cn":"对不起。"},{"sp":"长对话 2","en":"M: Look, you've been with us almost five years and I personally really value your proficiency at your job.","cn":"M: 听着，你在我们这儿工作快五年了，而我个人确实非常看重你的工作能力。"},{"sp":"长对话 2","en":"It makes my job far easier.","cn":"这让我的工作轻松多了。"},{"sp":"长对话 2","en":"In addition, I can assure you that management as a whole also holds you in high regard.","cn":"另外，我可以向你保证，管理层整体上也非常认可你。"},{"sp":"长对话 2","en":"W: Thank you.","cn":"W: 谢谢。"},{"sp":"长对话 2","en":"M: What I need is for you to be back at your 100%.","cn":"M: 我需要的是你恢复到百分之百的状态。"},{"sp":"长对话 2","en":"Are you sure taking two Mondays off will suffice?","cn":"你确定只休两个星期一就够了吗？"},{"sp":"长对话 2","en":"W: It'll be enough.","cn":"W: 够了。"},{"sp":"长对话 2","en":"I'm sure of it.","cn":"我确定。"},{"sp":"长对话 2","en":"M: Okay, good. So this is what we're going to do. You will take those days off, and I expect that you will gradually come back to your usual self. Then in two months' time, we will catch up again to see how you are faring.","cn":"M: 好，那就好。我们这样安排：你把那几天休掉，我希望你能逐渐恢复到平时的状态。两个月后，我们再聊一次，看看你目前的情况。"},{"sp":"长对话 2","en":"W: Sounds good.","cn":"W: 听起来不错。"},{"sp":"长对话 2","en":"Thank you for your understanding.","cn":"谢谢你的理解。"},{"sp":"听力篇章 1","en":"There are many factors that impact our health. These include our finances, our emotions and the way we work. Education is one such factor. Research suggests that higher levels of education can lead to better health and even greater longevity. But what about the education of your partner? New research seeks to answer this question. Researchers use data from a longitudinal study. The data came from surveys first administered to high school seniors in 1957. The surveys ended in 2011. The team found that a person whose spouse had a higher level of education tended to report better health. This remained the case when adjusting for other factors, such as participants' own education, social background and health status before and after marriage. The authors suggest that high levels of education provide shared social, intellectual, emotional and financial resources. These include things like higher levels of emotional intelligence, particular skills or knowledge, or more money. The researchers concede that an individual's own level of education is clearly important for their health, but they assert that individuals also can reap the benefits of their partner's education. It is noteworthy that the effects vary by gender. For women, health was more closely correlated to their spouse's education than for men. The team suggests this may be related to the time period of the study. Women in this sample had lower levels of education and lower occupational achievements than the men. The researchers' hypothesis is that this made the husband's resources more likely to have a shared impact.","cn":"有许多因素会影响我们的健康，包括我们的经济状况、情绪以及工作方式。教育就是其中一个因素。研究表明，较高的教育水平可能带来更好的健康状况，甚至更长的寿命。那么，伴侣的教育水平又会怎样呢？一项新的研究试图回答这个问题。研究人员使用了一项纵向研究的数据。这些数据来自1957年首次对高中毕业生进行的调查，调查于2011年结束。研究团队发现，配偶受教育程度较高的人往往会报告更好的健康状况。在对其他因素进行调整后，这一情况依然成立，这些因素包括参与者自身的教育程度、社会背景，以及婚前和婚后的健康状况。研究作者认为，较高的教育水平能够提供共享的社会、智力、情感和经济资源。这些资源包括更高的情商、特定的技能或知识，或者更多的钱。研究人员承认，个人自身的教育水平显然对其健康很重要，但他们指出，个人也能从伴侣的教育水平中获益。值得注意的是，这些影响因性别而异。对女性而言，健康状况与配偶教育水平的相关性比男性更密切。研究团队认为，这可能与研究所处的时代有关。该样本中的女性教育水平较低，职业成就也低于男性。研究人员的假设是，这使得丈夫所拥有的资源更有可能对夫妻双方产生共同影响。"},{"sp":"听力篇章 2","en":"Climate scientists predict that many parts of the world will be increasingly prone to floods.","cn":"气候科学家预测，世界许多地区将越来越容易发生洪水。"},{"sp":"听力篇章 2","en":"This is a serious risk to human lives and property.","cn":"这对人类生命和财产构成严重风险。"},{"sp":"听力篇章 2","en":"So understanding and accurately forecasting flood risks is a key challenge for vulnerable cities around the globe.","cn":"因此，了解并准确预测洪水风险，是全球易受影响城市面临的关键挑战。"},{"sp":"听力篇章 2","en":"In 2017, Derek Loftis of the Virginia Institute of Marine Science started a project called Catch the King.","cn":"2017年，弗吉尼亚海洋科学研究所的德里克·洛夫蒂斯启动了一个名为“Catch the King”的项目。"},{"sp":"听力篇章 2","en":"It uses a smartphone app to collect the data of ordinary citizens during high tides.","cn":"该项目利用一款智能手机应用，在高潮期间收集普通市民提供的数据。"},{"sp":"听力篇章 2","en":"He'll use those data to validate and improve his mathematical flooding model, called TideWatch.","cn":"他将利用这些数据验证并改进自己的数学洪水模型，该模型名为“TideWatch”。"},{"sp":"听力篇章 2","en":"Loftis's mission is to know where the water goes before it goes there.","cn":"洛夫蒂斯的使命，是在水流到某处之前弄清楚它将流向哪里。"},{"sp":"听力篇章 2","en":"But collecting necessary data and then processing that information quickly enough to make usable forecasts is anything but easy.","cn":"然而，收集必要的数据，并随后足够迅速地处理这些信息，以便做出可用的预报，绝非易事。"},{"sp":"听力篇章 2","en":"Accurate flood forecasts require an understanding of the situation on the ground.","cn":"准确的洪水预报需要了解地面实际情况。"},{"sp":"听力篇章 2","en":"By the early 2000s, supercomputing had advanced enough that scientists could integrate weather forecasting models with such measurements.","cn":"到21世纪初，超级计算技术已经发展到足以让科学家将天气预报模型与此类测量数据结合起来。"},{"sp":"听力篇章 2","en":"But they still didn't have the critically important ability to forecast fast-moving floods in real time.","cn":"但他们仍然不具备实时预测快速移动洪水这一至关重要的能力。"},{"sp":"听力篇章 2","en":"So, in 2017, Loftis and colleagues set up a group of 28 Internet-connected water-level sensors throughout the flood risk community of Norfolk, Virginia.","cn":"因此，2017年，洛夫蒂斯和同事在弗吉尼亚州诺福克的洪水风险社区内设置了一个由28个联网水位传感器组成的网络。"},{"sp":"听力篇章 2","en":"The new sensors relayed rough measurements about water height and movement to a computer at the Virginia Institute.","cn":"新传感器将有关水位高度和移动情况的粗略测量结果传送到弗吉尼亚海洋科学研究所的一台计算机上。"},{"sp":"听力篇章 2","en":"Along with those sensors, hundreds of local citizens take photos of rising tides and transmit them in real time to the institute.","cn":"除了这些传感器之外，数百名当地市民还拍摄潮水上涨的照片，并将照片实时传送给该研究所。"},{"sp":"听力篇章 2","en":"Scientists hope that the data collected by these citizens can help sharpen the ability to forecast exactly when and where damaging floods will occur.","cn":"科学家希望，这些市民收集的数据能够帮助提高预测能力，从而准确预报破坏性洪水将在何时何地发生。"},{"sp":"讲座 1","en":"Now, it's become something of a ritual to debate the value of a college degree, but as Current Population Survey data show, there has been a sharp decline in employment among men without college degrees compared with those who have them.","cn":"如今，讨论大学学位价值已经成了某种惯例，但正如当前人口调查数据显示的那样，与拥有大学学位的男性相比，没有大学学位的男性就业率出现了大幅下降。"},{"sp":"讲座 1","en":"This decline began in the 1960s and has become more serious over time.","cn":"这种下降始于20世纪60年代，并且随着时间推移变得更加严重。"},{"sp":"讲座 1","en":"What has actually caused this decline?","cn":"究竟是什么导致了这种下降？"},{"sp":"讲座 1","en":"Well, economists have been working to ascertain the roots of the decline for decades and have come up with several theories.","cn":"几十年来，经济学家一直在努力探究其根源，并提出了几种理论。"},{"sp":"讲座 1","en":"One popular theory is that it's a case of too low wages for jobs that don't require a degree.","cn":"一种流行的理论认为，这是因为不要求大学学位的工作薪资过低。"},{"sp":"讲座 1","en":"An alternate theory is that there were more jobs not requiring a college degree in the past than now.","cn":"另一种理论则认为，过去不要求大学学位的工作比现在更多。"},{"sp":"讲座 1","en":"A recent working paper from the National Bureau of Economic Research reviewed those theories and put forward additional hypotheses about the causes of the problem.","cn":"美国国家经济研究局最近的一篇工作论文审视了这些理论，并进一步提出了有关这一问题成因的其他假设。"},{"sp":"讲座 1","en":"Let's look at that paper now.","cn":"现在让我们来看看这篇论文。"},{"sp":"讲座 1","en":"First, the researchers considered the issue of wages.","cn":"首先，研究人员考察了工资问题。"},{"sp":"讲座 1","en":"As the wage gap has grown between those with college degrees and those without, economists have suggested that men aren't as interested in taking some of the less lucrative jobs.","cn":"由于大学毕业者与未获得大学学位者之间的工资差距不断扩大，经济学家认为，男性对从事一些收入较低的工作不再那么感兴趣。"},{"sp":"讲座 1","en":"While the authors of the paper found truth in this explanation, they assert that low wages can't be the only factor, as wages for men without college degrees, adjusting for inflation, haven't changed much since the 1960s, making it hard to see why fewer men seem willing to accept those wages.","cn":"虽然论文作者发现这种解释有一定道理，但他们断言，低工资不可能是唯一因素，因为没有大学学位男性的工资按通货膨胀调整后，自20世纪60年代以来并没有太大变化，这使人们难以理解为什么似乎有更少的男性愿意接受这样的工资。"},{"sp":"讲座 1","en":"This leads to the second theory, that more jobs require a college degree today than in the past.","cn":"这就引出了第二种理论，即如今比过去有更多的工作要求求职者拥有大学学位。"},{"sp":"讲座 1","en":"Indeed, that theory seems valid, because in America today, 2/3 of jobs are filled by workers with at least some college education.","cn":"事实上，这一理论似乎是成立的，因为在今天的美国，三分之二的工作由至少接受过部分大学教育的劳动者担任。"},{"sp":"讲座 1","en":"However, the authors of the paper argue that there are other factors amplifying the problem.","cn":"然而，论文作者认为，还有其他因素加剧了这一问题。"},{"sp":"讲座 1","en":"They identified two new potential explanations: the first being the tremendous decline in marriage among men without college degrees since the 1960s; and the second being the increase in women participating in the workforce that was concurrent with the decline in marriage.","cn":"他们找出了两种新的潜在解释：第一，自20世纪60年代以来，没有大学学位男性的结婚率大幅下降；第二，女性参与劳动力市场的比例有所上升，而这一变化与结婚率下降同时发生。"},{"sp":"讲座 1","en":"These two changes mean that men might not have families to support, or if they do, their wives might be doing more of the providing, both of which might remove the financial incentive to work.","cn":"这两种变化意味着，男性可能没有需要供养的家庭；即使有，他们的妻子也可能承担了更多供养家庭的责任，而这两种情况都可能削弱男性工作的经济激励。"},{"sp":"讲座 1","en":"The authors of the paper concede that research on the subject isn't complete, but they argue that their work supports the value of a college education.","cn":"论文作者承认，对这一问题的研究尚未完成，但他们认为，其研究成果支持接受大学教育的价值。"},{"sp":"讲座 2","en":"While an increasing number of people are trying to eat less meat, a market research team has found in its latest fashion and sustainability report that the trend is now spreading from kitchen to closet.","cn":"尽管越来越多的人正在努力少吃肉，但一个市场研究团队在其最新的时尚与可持续发展报告中发现，这一趋势如今正从厨房蔓延到衣柜。"},{"sp":"讲座 2","en":"It found animal welfare came top of a list of issues that people considered before buying clothes, with 42% saying it was important to them.","cn":"报告发现，在人们购买服装前考虑的一系列问题中，动物福利位居首位，42%的人表示这对他们很重要。"},{"sp":"讲座 2","en":"The researchers of the team predicted that the next year would see a boom in animal-free shoe collections, since they heard shoppers of all ages say they would buy footwear designated as \"vegan\", meaning the goods were produced without using any animal or animal part.","cn":"该团队的研究人员预测，明年不使用动物材料的鞋类系列将迎来蓬勃发展，因为他们听到各个年龄段的消费者都表示愿意购买标有“纯素”字样的鞋类，这意味着这些商品的生产没有使用任何动物或动物的一部分。"},{"sp":"讲座 2","en":"As well as being on trend, and with a much better ring to it than synthetic leather, the vegan label does convey an important extra distinction.","cn":"除了符合潮流，而且比“合成皮革”听起来悦耳得多之外，“纯素”这一标签确实传达了一个重要的额外区别。"},{"sp":"讲座 2","en":"If you label something as vegan, then the whole product needs to be animal free.","cn":"如果将某件商品标为纯素，那么整件产品都必须不含动物成分。"},{"sp":"讲座 2","en":"That means checking things like the glue that holds the shoe together, for example, and the chemicals used for finishing them.","cn":"这意味着，例如，需要检查用于粘合鞋子的胶水，以及用于进行表面处理的化学品。"},{"sp":"讲座 2","en":"At the top end, some of the world-renowned fashion designers have avoided leather and fur for some time.","cn":"在高端领域，一些世界知名的时装设计师已经有一段时间不再使用皮革和皮草。"},{"sp":"讲座 2","en":"In fact, some of the companies are now exploring a leather substitute and a silk replacement made from mushrooms.","cn":"事实上，其中一些公司如今正在探索用蘑菇制成的皮革替代品和丝绸替代品。"},{"sp":"讲座 2","en":"The Animal Free Product Society says they've seen a boom in products registered with the vegan trademark.","cn":"Animal Free Product Society表示，他们看到注册纯素商标的产品数量激增。"},{"sp":"讲座 2","en":"In 2018, there were 119.","cn":"2018年，这类产品有119件。"},{"sp":"讲座 2","en":"So far this year, it says an unprecedented 1,956 have been registered.","cn":"截至今年目前为止，该协会称已有创纪录的1,956件产品完成注册。"},{"sp":"讲座 2","en":"New products are being added daily.","cn":"每天都有新产品加入其中。"},{"sp":"讲座 2","en":"There are fur coats that are vegan, plastic vegan belts and shoes made from tree bark or natural rubber labelled vegan.","cn":"标为纯素的产品包括皮草大衣、塑料制纯素腰带，以及用树皮或天然橡胶制成的鞋子。"},{"sp":"讲座 2","en":"These new products aren't coming at an extra cost to consumers though.","cn":"不过，这些新产品并没有让消费者承担额外费用。"},{"sp":"讲座 2","en":"Vegan boots cost the same as the leather originals.","cn":"纯素靴子的价格与原皮革靴子相同。"},{"sp":"讲座 2","en":"New Look, one of the first reputable store chains to use the vegan trademark, prices ballet shoes at £7.99 and a vegan laptop handbag at £29.99, comparable with its other products.","cn":"New Look是最早使用纯素商标的知名连锁店之一，其芭蕾舞鞋售价为7.99英镑，纯素笔记本电脑手提包售价为29.99英镑，与其他产品的价格相当。"},{"sp":"讲座 2","en":"This signifies a change.","cn":"这标志着一种变化。"},{"sp":"讲座 2","en":"In the past, ethical products, whether they were fair trade or organic, came at a premium.","cn":"过去，无论是公平贸易产品还是有机产品，伦理类商品的价格都更高。"},{"sp":"讲座 2","en":"However, it is unclear whether these new products can be considered ethical.","cn":"然而，这些新产品是否可以被视为符合伦理标准，尚不明确。"},{"sp":"讲座 2","en":"The debate over durability, crop-growing impacts, pollution and recyclability is a complicated one, not to mention the ethics around the working conditions for people making the products, whatever the component materials.","cn":"关于耐用性、作物种植的影响、污染和可回收性的争论十分复杂，更不用说无论所用材料为何，生产这些产品的工人的工作条件所涉及的伦理问题了。"},{"sp":"讲座 2","en":"Environmental campaigners advise that the best approach is to buy less, never mind what the item is made of.","cn":"环保人士建议，最好的做法是少买东西，不管商品是由什么制成的。"},{"sp":"讲座 3","en":"By the end of 2016, anyone who had been paying even passing attention to the news headlines was highly likely to conclude that everything was terrible, and that the world was going to hell.","cn":"到2016年底，任何哪怕只是偶尔关注新闻头条的人，都极有可能得出这样的结论：一切都糟透了，世界正走向毁灭。"},{"sp":"讲座 3","en":"It was easy to feel depressed by the wars in different parts of the world, the spread of deadly viruses or terror attacks.","cn":"世界各地的战争、致命病毒的传播或恐怖袭击，很容易让人感到沮丧。"},{"sp":"讲座 3","en":"Yet, 2016 was the best year in the history of humanity.","cn":"然而，2016年却是人类历史上最好的一年。"},{"sp":"讲座 3","en":"Child mortality was roughly half what it was as recently as 1990.","cn":"儿童死亡率大约只有就在1990年时的一半。"},{"sp":"讲座 3","en":"And 300,000 more people gained access to electricity each day.","cn":"每天还有30万人获得了用电的机会。"},{"sp":"讲座 3","en":"Every single measure of material and environmental welfare in America, Europe, Asia, Africa and the world as a whole has improved rather than deteriorated.","cn":"在美国、欧洲、亚洲、非洲以及全世界范围内，衡量物质和环境福祉的每一项指标都在改善，而不是恶化。"},{"sp":"讲座 3","en":"We are living in history's most peaceful era, with violence of all kinds in steep decline.","cn":"我们正生活在人类历史上最和平的时代，各种形式的暴力都在急剧减少。"},{"sp":"讲座 3","en":"Those are the facts.","cn":"这些都是事实。"},{"sp":"讲座 3","en":"So why aren't we all optimists?","cn":"那么，我们为什么没有全都成为乐观主义者呢？"},{"sp":"讲座 3","en":"In a 2015 survey for YouGov, 65% of British people and 81% of the French said they thought the world was getting worse.","cn":"在YouGov于2015年进行的一项调查中，65%的英国人和81%的法国人表示，他们认为世界正在变得越来越糟。"},{"sp":"讲座 3","en":"However, according to numerous sensible statistics, these people are simply wrong.","cn":"然而，根据大量合理的统计数据，这些人的看法显然是错误的。"},{"sp":"讲座 3","en":"Nobody in their right mind should wish to have lived in a previous century.","cn":"任何心智正常的人都不应希望自己生活在过去的某个世纪。"},{"sp":"讲座 3","en":"Yet people do.","cn":"然而，人们确实会有这样的愿望。"},{"sp":"讲座 3","en":"Why?","cn":"为什么？"},{"sp":"讲座 3","en":"Our prevailing mood of despair is irrational.","cn":"我们普遍的绝望情绪是不理性的。"},{"sp":"讲座 3","en":"It says more about us than it does about how things really are.","cn":"它更多地反映了我们自身，而不是事物真实的状况。"},{"sp":"讲座 3","en":"It is best explained as the result of various psychological biases that served a purpose for our evolutionary ancestors—but now, in a media-saturated era, constantly mislead us.","cn":"对这种情绪最好的解释是：它源于各种曾为我们进化时期的祖先发挥过作用的心理偏差，但如今在媒体充斥的时代，这些心理偏差却不断误导我们。"},{"sp":"讲座 3","en":"Once upon a time, it was of great survival value to be worried about everything that could go wrong.","cn":"曾几何时，对所有可能出错的事情保持担忧具有极大的生存价值。"},{"sp":"讲座 3","en":"This is what makes bad news especially compelling.","cn":"正因如此，坏消息尤其引人关注。"},{"sp":"讲座 3","en":"In our evolutionary past, it was a very good thing that our attention could be easily seized by negative information, since it might well indicate a dangerous risk to our own survival.","cn":"在我们的进化史中，我们的注意力很容易被负面信息吸引是一件非常有益的事，因为这些信息很可能意味着对自身生存构成的危险。"},{"sp":"讲座 3","en":"The caveman who always assumed there was a lion behind the next rock would usually be wrong, but he'd be much more likely to survive and reproduce than one who always assumed the opposite.","cn":"那个总是假定下一块岩石后面有一头狮子的穴居人通常会判断错误，但与总是假定情况相反的人相比，他存活并繁衍后代的可能性要大得多。"},{"sp":"讲座 3","en":"But that was all before newspapers, television and the internet.","cn":"但那是在报纸、电视和互联网出现以前。"},{"sp":"讲座 3","en":"In today's hyper connected times, our addiction to bad news just leads us to vacuum up depressing or enraging stories from across the globe.","cn":"如今，在这个高度互联的时代，我们对坏消息的沉迷只会让我们从全球各地吸纳令人沮丧或愤怒的故事。"},{"sp":"讲座 3","en":"Whether these news stories threaten us or not, we conclude that things are much worse than they actually are.","cn":"无论这些新闻是否真的对我们构成威胁，我们都会得出这样的结论：事情比实际情况糟糕得多。"},{"sp":"讲座 3","en":"Really good news, on the other hand, can be a lot harder to spot in a newspaper because predictable daily events by definition aren't news.","cn":"另一方面，真正的好消息在报纸上往往更难被发现，因为可预见的日常事件按定义来说并不算新闻。"}]}];
